EXPL_INDEX = {"models": [{"id": "abl-gemma-4-31b", "slug": "abl-gemma-4-31b", "n": 900, "counts": {"1": 360, "2": 30, "3": 39, "4": 21, "5": 8, "6": 30, "7": 80, "8": 230, "9": 24, "10": 66, "11": 12}, "with_answer": 360, "with_code": 0}, {"id": "abl-opus-35b-a3b", "slug": "abl-opus-35b-a3b", "n": 907, "counts": {"1": 360, "2": 30, "3": 39, "4": 28, "5": 8, "6": 30, "7": 80, "8": 230, "9": 24, "10": 66, "11": 12}, "with_answer": 345, "with_code": 0}, {"id": "abl-qwen3.6-27b", "slug": "abl-qwen3-6-27b", "n": 547, "counts": {"2": 30, "3": 39, "4": 28, "5": 8, "6": 30, "7": 80, "8": 230, "9": 24, "10": 66, "11": 12}, "with_answer": 0, "with_code": 0}, {"id": "agents-a1-35b", "slug": "agents-a1-35b", "n": 886, "counts": {"1": 360, "2": 30, "3": 39, "4": 7, "5": 8, "6": 30, "7": 80, "8": 230, "9": 24, "10": 66, "11": 12}, "with_answer": 506, "with_code": 0}, {"id": "bonsai-ternary-27b", "slug": "bonsai-ternary-27b", "n": 907, "counts": {"1": 360, "2": 30, "3": 39, "4": 28, "5": 8, "6": 30, "7": 80, "8": 230, "9": 24, "10": 66, "11": 12}, "with_answer": 527, "with_code": 0}, {"id": "gemma-4-26b-a4b", "slug": "gemma-4-26b-a4b", "n": 893, "counts": {"1": 360, "2": 30, "3": 39, "4": 14, "5": 8, "6": 30, "7": 80, "8": 230, "9": 24, "10": 66, "11": 12}, "with_answer": 533, "with_code": 0}, {"id": "gemma-4-31b-dense", "slug": "gemma-4-31b-dense", "n": 897, "counts": {"1": 360, "2": 27, "3": 39, "4": 21, "5": 8, "6": 30, "7": 80, "8": 230, "9": 24, "10": 66, "11": 12}, "with_answer": 543, "with_code": 0}, {"id": "glm-4.5-air", "slug": "glm-4-5-air", "n": 897, "counts": {"1": 360, "2": 27, "3": 39, "4": 21, "5": 8, "6": 30, "7": 80, "8": 230, "9": 24, "10": 66, "11": 12}, "with_answer": 541, "with_code": 0}, {"id": "gpt-oss-120b", "slug": "gpt-oss-120b", "n": 897, "counts": {"1": 360, "2": 27, "3": 39, "4": 21, "5": 8, "6": 30, "7": 80, "8": 230, "9": 24, "10": 66, "11": 12}, "with_answer": 549, "with_code": 0}, {"id": "gpt-oss-20b", "slug": "gpt-oss-20b", "n": 893, "counts": {"1": 360, "2": 30, "3": 39, "4": 14, "5": 8, "6": 30, "7": 80, "8": 230, "9": 24, "10": 66, "11": 12}, "with_answer": 543, "with_code": 0}, {"id": "granite-4.1-30b", "slug": "granite-4-1-30b", "n": 900, "counts": {"1": 360, "2": 30, "3": 39, "4": 21, "5": 8, "6": 30, "7": 80, "8": 230, "9": 24, "10": 66, "11": 12}, "with_answer": 552, "with_code": 0}, {"id": "laguna-s-2.1", "slug": "laguna-s-2-1", "n": 907, "counts": {"1": 360, "2": 30, "3": 39, "4": 28, "5": 8, "6": 30, "7": 80, "8": 230, "9": 24, "10": 66, "11": 12}, "with_answer": 349, "with_code": 0}, {"id": "llama-4-scout", "slug": "llama-4-scout", "n": 674, "counts": {"1": 360, "2": 18, "3": 39, "4": 21, "5": 8, "6": 30, "7": 80, "8": 16, "9": 24, "10": 66, "11": 12}, "with_answer": 548, "with_code": 0}, {"id": "nemotron-3-nano-30b", "slug": "nemotron-3-nano-30b", "n": 886, "counts": {"1": 360, "2": 30, "3": 39, "4": 7, "5": 8, "6": 30, "7": 80, "8": 230, "9": 24, "10": 66, "11": 12}, "with_answer": 537, "with_code": 0}, {"id": "ornith-1.0-35b", "slug": "ornith-1-0-35b", "n": 886, "counts": {"1": 360, "2": 30, "3": 39, "4": 7, "5": 8, "6": 30, "7": 80, "8": 230, "9": 24, "10": 66, "11": 12}, "with_answer": 526, "with_code": 0}, {"id": "ornith-1.0-9b", "slug": "ornith-1-0-9b", "n": 900, "counts": {"1": 360, "2": 30, "3": 39, "4": 21, "5": 8, "6": 30, "7": 80, "8": 230, "9": 24, "10": 66, "11": 12}, "with_answer": 516, "with_code": 0}, {"id": "qwen3-235b", "slug": "qwen3-235b", "n": 572, "counts": {"1": 360, "2": 27, "3": 39, "4": 28, "5": 8, "6": 30, "7": 80}, "with_answer": 556, "with_code": 0}, {"id": "qwen3-coder-30b", "slug": "qwen3-coder-30b", "n": 886, "counts": {"1": 360, "2": 30, "3": 39, "4": 7, "5": 8, "6": 30, "7": 80, "8": 230, "9": 24, "10": 66, "11": 12}, "with_answer": 538, "with_code": 0}, {"id": "qwen3.6-27b-dense", "slug": "qwen3-6-27b-dense", "n": 900, "counts": {"1": 360, "2": 30, "3": 39, "4": 21, "5": 8, "6": 30, "7": 80, "8": 230, "9": 24, "10": 66, "11": 12}, "with_answer": 524, "with_code": 0}, {"id": "qwen3.6-27b-fable-fusion", "slug": "qwen3-6-27b-fable-fusion", "n": 254, "counts": {"8": 230, "9": 24}, "with_answer": 0, "with_code": 0}, {"id": "qwen3.6-35b-a3b", "slug": "qwen3-6-35b-a3b", "n": 963, "counts": {"1": 360, "2": 30, "3": 39, "4": 84, "5": 8, "6": 30, "7": 80, "8": 230, "9": 24, "10": 66, "11": 12}, "with_answer": 546, "with_code": 0}], "prompts": {"b1.coding-01": "A law firm's billing system needs a function that converts raw minutes worked into billable\nhours under the firm's outside-counsel-guideline (OCG) rounding rule: time is billed in\ntenth-of-an-hour (6-minute) increments, and any partial increment is always rounded UP, never\ndown -- except that zero minutes worked must bill as exactly 0.0, not rounded up to a phantom\n0.1.\n\nWrite a Python function `round_billable(minutes)` that:\n- Returns `0.0` if `minutes == 0`.\n- Otherwise returns the number of hours, rounded UP to the nearest 0.1 (i.e., the nearest\n  6-minute increment), for any `minutes > 0`.\n- Raises `ValueError` if `minutes` is negative, since a billing entry can't have negative\n  time.\n\nTrace your function against these cases and show the results: `minutes=0`, `minutes=1`,\n`minutes=6`, `minutes=65`, and `minutes=-5`.\n", "b1.coding-02": "A payments processor uses transaction reference IDs in the exact format\n`TXN-` followed by 10 digits, followed by `-`, followed by a 3-letter uppercase ISO currency\ncode -- for example `TXN-0048291344-USD`.\n\nConstruct a single Python regular expression, intended to be used with `re.fullmatch`, that\ncorrectly classifies each of the following 7 test strings as MATCH or NO MATCH:\n\n1. `TXN-0048291344-USD` -> should MATCH\n2. `TXN-9999999999-EUR` -> should MATCH\n3. `TXN-004829134-USD` -> should NOT match (only 9 digits)\n4. `TXN-0048291344-usd` -> should NOT match (lowercase currency code)\n5. `TXN-00482913445-USD` -> should NOT match (11 digits)\n6. `TXN-0048291344-USDX` -> should NOT match (trailing extra character after the currency\n   code)\n7. `TXN0048291344-USD` -> should NOT match (missing the hyphen right after TXN)\n\nGive the regex, classify all 7 strings against it, and explain specifically why using\n`re.search` with your pattern instead of `re.fullmatch` (or omitting start/end anchors)\nwould change the correct classification of test string 6.\n", "b1.coding-03": "You're writing a compliance-audit query against a USDA-inspected poultry plant's\nlot-tracking database (PostgreSQL). Schema:\n\n- `lots(lot_id INT PRIMARY KEY, product_line VARCHAR, production_date DATE)`\n- `scan_events(event_id INT PRIMARY KEY, lot_id INT REFERENCES lots(lot_id),\n  station VARCHAR, scanned_at TIMESTAMP)`\n- `recalls(recall_id INT PRIMARY KEY, lot_id INT REFERENCES lots(lot_id),\n  recall_date DATE, reason VARCHAR)`\n\nUSDA rules require every lot to have at least 3 recorded scan checkpoints (intake,\nprocessing, shipping). A lot with fewer than 3 scan_events rows is a documentation gap that\nis itself a compliance finding, even if the lot was never recalled and the product shipped\nfine.\n\nWrite a single SQL query that returns every lot produced in the last 24 months that has:\n(a) zero matching rows in `recalls`, AND (b) fewer than 3 rows in `scan_events` -- including\nlots with ZERO scan_events at all, which is the worst version of this gap. Return\n`lot_id`, `product_line`, `production_date`, and the scan-event count, ordered by\n`production_date` ascending (oldest gap first).\n", "b1.coding-04": "A county government's online building-permit portal throws the error below when an applicant\nsubmits a permit fee calculation. Explain exactly why the error occurs, and provide a fixed\nversion of the function.\n\nCode (`permits.py`):\n```\n 1  FEE_SCHEDULE = {\n 2      \"residential_addition\": 150,\n 3      \"large_project_surcharge\": 2.5,\n 4  }\n 5\n 6  def calculate_permit_fee(permit_type, square_footage, fee_schedule):\n 7      base_fee = fee_schedule[permit_type]\n 8      if square_footage > 5000:\n 9          surcharge = fee_schedule.get(\"large_project_surcharge\")\n10      total = base_fee + surcharge * square_footage / 1000\n11      return round(total, 2)\n12\n13  fee = calculate_permit_fee(\"residential_addition\", 1200, FEE_SCHEDULE)\n14  print(fee)\n```\n\nTraceback:\n```\nTraceback (most recent call last):\n  File \"permits.py\", line 13, in <module>\n    fee = calculate_permit_fee(\"residential_addition\", 1200, FEE_SCHEDULE)\n  File \"permits.py\", line 10, in calculate_permit_fee\n    total = base_fee + surcharge * square_footage / 1000\nUnboundLocalError: local variable 'surcharge' referenced before assignment\n```\n\nExplain why line 10 fails specifically for this call (`square_footage=1200`), then rewrite\n`calculate_permit_fee` so it still applies the large-project surcharge only when\n`square_footage > 5000`, but never leaves `surcharge` undefined for the normal case -- and\nalso handle the case where `fee_schedule` is missing the `\"large_project_surcharge\"` key at\nall, for a lot over 5000 sq ft.\n", "b1.coding-05": "Review this diff for a clinic's patient-lookup API endpoint (the clinic is a HIPAA covered\nentity). Identify every security or compliance issue the diff introduces, cite the specific\nline(s) it appears on, and give corrected code for the query-construction line.\n\n```diff\n--- a/patient_lookup.py\n+++ b/patient_lookup.py\n@@ -10,12 +10,14 @@ def lookup_patient(request):\n     mrn = request.args.get(\"mrn\")\n-    query = \"SELECT id, name, dob FROM patients WHERE mrn = %s\"\n-    cursor.execute(query, (mrn,))\n+    query = f\"SELECT id, name, dob, ssn FROM patients WHERE mrn = '{mrn}'\"\n+    cursor.execute(query)\n+    logging.info(f\"Patient lookup request: {request.args}\")\n     row = cursor.fetchone()\n     return jsonify(row)\n```\n", "b1.coding-06": "This Python script summarizes SCADA pressure-sensor readings for a drilling rig's daily\nreport. It has TWO distinct bugs: one you can find by comparing the code to the spec comment\non line 3, and one that will not throw any error or crash, but silently corrupts output when\nthe report covers more than one well in the same run. Find both, cite the line each one is\non, and give the fix for each.\n\n```\n 1  import statistics\n 2\n 3  ALERT_THRESHOLD_PSI = 4500  # engineering spec: flag any reading >= 4500 psi\n 4\n 5\n 6  def load_readings(sensor_log):\n 7      \"\"\"sensor_log: list of (well_id, psi_reading) tuples from the SCADA feed.\"\"\"\n 8      readings_by_well = {}\n 9      for well_id, psi in sensor_log:\n10          readings_by_well.setdefault(well_id, []).append(psi)\n11      return readings_by_well\n12\n13\n14  def flag_overpressure_events(readings, alerts=[]):\n15      \"\"\"Return the list of psi readings that breach the over-pressure threshold.\"\"\"\n16      for psi in readings:\n17          if psi > ALERT_THRESHOLD_PSI:\n18              alerts.append(psi)\n19      return alerts\n20\n21\n22  def summarize_well(well_id, readings):\n23      events = flag_overpressure_events(readings)\n24      avg = statistics.mean(readings)\n25      return {\n26          \"well_id\": well_id,\n27          \"avg_psi\": round(avg, 1),\n28          \"overpressure_events\": len(events),\n29          \"max_psi\": max(readings),\n30      }\n31\n32\n33  def generate_daily_report(sensor_log):\n34      \"\"\"Called once per rig, once per day, over all wells reporting that day.\"\"\"\n35      readings_by_well = load_readings(sensor_log)\n36      report = []\n37      for well_id, readings in readings_by_well.items():\n38          report.append(summarize_well(well_id, readings))\n39      return report\n```\n", "b1.coding-07": "Refactor this construction-billing helper for clarity while preserving its EXACT behavior\nfor every input combination -- do not just simplify it and assume it's equivalent, prove it.\n\n```python\ndef get_retention_rate(percent_complete, is_final_punchlist):\n    if is_final_punchlist == True:\n        if percent_complete >= 100:\n            rate = 0\n        else:\n            rate = 0.05\n    else:\n        if percent_complete < 50:\n            rate = 0.10\n        else:\n            if percent_complete < 90:\n                rate = 0.10\n            else:\n                if percent_complete <= 100:\n                    rate = 0.05\n                else:\n                    rate = 0.05\n    return rate\n```\n\nA naive refactor is likely to combine the two branches into something like:\n`return 0 if (is_final_punchlist and percent_complete >= 100) else (0.10 if percent_complete\n< 90 else 0.05)`. Trace that candidate against `is_final_punchlist=True,\npercent_complete=70` and state whether it actually matches the original function's output\nfor that input. Then give your final, clean refactor, and show it handles that same input\ncorrectly.\n", "b1.coding-08": "Write a bash script `archive_freezer_logs.sh` for a biotech lab's ultra-low-temperature\nfreezer monitoring system. Requirements:\n\n1. It processes every `.csv` file directly inside `/data/freezer_logs/` -- filenames may\n   contain spaces (e.g., `Freezer 3 Log.csv`), since that's how the monitoring software\n   names its exports.\n2. Any file whose last-modified time is more than 7 days old gets gzip-compressed into\n   `/data/freezer_logs/archive/`, then the original is removed -- but ONLY after the\n   compression step has actually succeeded. These are irreplaceable sponsor-sample\n   temperature logs, so a file must never be deleted if its archive copy might not have\n   been written correctly.\n3. Files modified within the last 7 days must NOT be touched -- the logging process may\n   still be actively appending to them.\n4. The script runs daily via cron. It must be safe to re-run on a directory that already has\n   some files archived, without erroring out or re-compressing files it already archived on\n   a previous run.\n\nWrite the script, then explain the two specific bugs a naive version commonly has that yours\navoids: (a) iterating over filenames in a way that breaks on the spaces described in\nrequirement 1, and (b) deleting a source file even when its compression step actually\nfailed.\n", "b1.it_infra-01": "Your MSP manages IT for a USDA-inspected poultry processing plant. The plant's file-and-scan\nserver (a Hyper-V VM: 8 vCPU, 32GB RAM, 500GB SSD volume) hosts the shared folder that\nhandheld barcode scanners on the production floor write to for USDA-mandated lot-tracking\nrecords. Current monitoring shows two things: (1) CPU is sustained at 91% for roughly 20\nminutes at each of the plant's three daily shift changes (07:00, 15:00, 23:00), when all\nscanners re-sync in a burst; and (2) the SSD volume is 82% full, growing at about 23GB per\nweek from retained lot-tracking scan logs -- a 2-year USDA retention requirement means the\nold logs can't simply be purged to reclaim space. The plant cannot tolerate any scanner\ndowntime during a shift-change window, because a gap in lot-tracking coverage during a shift\nchange is itself a USDA compliance finding. Recommend a right-sized VM spec (vCPU/RAM), a\nstorage plan that respects the 2-year retention requirement, and a timeline for making the\nchange that avoids all three daily shift-change windows.\n", "b1.it_infra-02": "Your MSP supports IT for a remote drilling rig site whose only network backhaul is a\nVSAT satellite link (2 Mbps up / 10 Mbps down), shared with the SCADA/drilling-telemetry\nsystems. This month's Windows Server 2022 cumulative security update needs to be deployed\nto the rig's 14 domain-joined endpoints, including the domain controller that authenticates\nthe SCADA operator workstations. The rig runs on a 14-day hitch schedule (crews rotate in\nand out every 14 days), and the site's only approved maintenance window is a 4-hour block\nduring the day-to-night crew changeover, once per hitch, because the rig cannot tolerate\ndegraded authentication or network performance while drilling operations are active at any\nother time. Pushing the update to all 14 endpoints at once over the VSAT link would saturate\nthe link and disrupt SCADA telemetry. Write a patch-window runbook: the pre-patch step to\ntake before touching anything, how you sequence the 14 endpoints given the bandwidth\nconstraint, and how the plan fits the 14-day hitch cadence.\n", "b1.it_infra-03": "Your MSP manages IT for a multi-provider outpatient clinic. The clinic's network is\neffectively flat: EHR workstations, medical IoT devices (infusion pumps, patient monitors),\nguest WiFi, and back-office admin systems all sit on the same VLAN (10.10.0.0/22). A recent\ninternal security review found that a laptop connected to the guest WiFi could reach the EHR\napplication server directly over RDP (port 3389 open, no ACL blocking it) -- guest traffic\nshould never be able to reach a system that touches electronic protected health information\n(ePHI). This is a real gap against the clinic's HIPAA Security Rule access-control\nobligations. The clinic cannot tolerate any EHR downtime between 8:00 AM and 6:00 PM, since\nproviders need the EHR live for patient charting during clinic hours. Write a network\nsegmentation review: propose the VLAN structure that closes this specific gap, state exactly\nwhat closes the guest-to-EHR RDP path, and give a change plan (including a rollback step) that\nrespects the 8 AM-6 PM no-downtime window.\n", "b1.it_infra-04": "Two architecture firms are merging. Firm A (120 users) is absorbing Firm B (45 users) into\nFirm A's Microsoft 365 / Active Directory tenant. Firm B's active project files live on an\non-prem file share, and many of Firm B's AutoCAD drawings contain external references\n(Xrefs) that point to that share using absolute UNC paths (e.g., \\\\FIRMB-FS01\\Projects\\...).\nChanging the file share's path or name, or moving a drafter's mailbox/UPN, during active work\nhours risks breaking those Xref links mid-drawing for engineers who have files open. Firm B\ncurrently has two projects with permit-submission deadlines to the local building department\nin 10 business days. Write an M365/AD tenant-consolidation change plan: sequence the\nmailbox and file-share migration so Xref links are not broken while either permit deadline is\nstill open, name which changes must happen only AFTER both permit deadlines pass, and include\na rollback approach for the mailbox migration if a batch fails partway.\n", "b1.it_infra-05": "Your MSP monitors IT for a contract biotech lab that stores irreplaceable sponsor study\nsamples in 14 ultra-low-temperature (-80C) freezers, each with an IoT temperature sensor\nfeeding your RMM/monitoring platform. Current alert rule: any freezer reading warmer than\n-75C fires a P1 page to the on-call engineer immediately. Problem: these freezers routinely\ncycle up to about -70C during a normal defrost cycle, which happens roughly every 6 hours and\nlasts about 12 minutes -- so each freezer generates several false P1 pages per day. On-call\nengineers have started acknowledging and silencing pages without checking them, which is\ndangerous, because the first few minutes of a genuine compressor failure look identical to a\ndefrost cycle on the temperature graph alone. Propose a retuned alerting strategy: what the\nnew threshold/timing logic should be so a normal defrost cycle no longer pages on-call, and\na compensating control (not just a wider static threshold) that still guarantees a genuine\ncompressor failure is caught given that on-call has started ignoring pages.\n", "b1.it_infra-06": "Your MSP client is a 40-attorney law firm. Its case-management system (case files, billing,\nand privileged client communications) runs on an on-prem SQL Server VM. Current backup\nconfiguration: a nightly full backup to a NAS appliance sitting in the same server closet as\nthe production VM host, retained for 14 days, no offsite or cloud copy, and the backup NAS is\ndomain-joined using a domain service account so scheduled jobs can authenticate to it. Per\nthe firm's last IT audit, no restore from this backup has actually been tested in 18 months.\nThe firm's malpractice insurance policy requires an RPO of at most 4 hours and an RTO of at\nmost 8 business hours (the case-management system must be restorable within 8 business hours\nto avoid missing court filing deadlines). A peer firm was recently hit by ransomware that\nencrypted both its production server AND its backup NAS, because the backup storage was\nreachable on the same network segment using domain credentials. Write a backup/DR gap\nanalysis: name every gap against the stated RPO/RTO and against ransomware resilience\n(specifically call out the co-located, domain-joined backup as a single point of failure),\ngive a remediation plan in priority order, quantify the blast radius if ransomware hits before\nthis is fixed, and state what must happen BEFORE any change is made to the current backup\nregime to avoid discovering -- only after the old backups are gone -- that the new setup\ndoesn't actually work.\n", "b1.it_infra-07": "Your MSP supports IT for a county government whose 911 dispatch / computer-aided-dispatch\n(CAD) system is hosted by a third-party SaaS vendor. The vendor had a 5-hour-40-minute\nregional outage. The vendor's own status page attributes the cause to \"a database failover\nthat did not complete cleanly during a routine maintenance window.\" During the outage,\ndispatchers fell back to the county's paper/radio continuity-of-operations plan, and\n911 call-to-dispatch time reportedly increased. The vendor contract has a 99.9% monthly\nuptime SLA with service credits for breaches, and a liability cap for consequential damages\nof $50,000 -- a figure the county's risk manager has flagged as inadequate given the\npublic-safety stakes of a CAD outage. Write a vendor-outage postmortem for county leadership:\nquantify the SLA breach against the 99.9% target, state what should be independently verified\nbefore accepting the vendor's self-reported root cause at face value, call out the liability\ncap mismatch as a business/legal risk that IT configuration changes cannot fix, and recommend\none concrete resiliency step plus what the county should demand from the vendor before\ntrusting this postmortem as final.\n", "b1.it_infra-08": "A regional bank is acquiring an 18-branch community bank. The community bank runs 340\nmailboxes on an on-prem Exchange Server 2016 environment, which is already past Microsoft's\nend of extended support. The plan is to migrate those mailboxes into the acquiring bank's\nMicrosoft 365 tenant. Regulatory constraint: the bank's retention obligations require every\nmailbox's content and metadata (including original delivery timestamps) to survive the\nmigration intact, with a documented chain of custody. Operational constraint: branches are\nopen 9 AM-5 PM across two time zones, so there is no single company-wide after-hours window,\nand mailbox access cannot be interrupted during any branch's business hours. Timeline\nconstraint: the core-banking system conversion (a separate workstream) is cutting over in 45\ndays, and email migration must NOT be scheduled during that same week, because branch staff\nneed working email to field cutover-related questions and both teams cannot be in a change\nfreeze at the same time. Write a phased Microsoft 365 migration plan: the cutover approach\ngiven Exchange 2016 is already unsupported, a rollback plan if a mailbox batch migration fails\npartway, and the sequencing relative to the 45-day core-banking cutover with the blast radius\nof getting that sequencing wrong.\n", "b1.cybersecurity-01": "You are a security analyst at an MSP supporting a financial services client (a regional\ncredit union). A vulnerability scan of the client's perimeter firewall (a Palo Alto Networks\nPAN-OS GlobalProtect gateway) flagged CVE-2024-3400, a critical (CVSS 10.0) unauthenticated\ncommand injection vulnerability that is being actively exploited in the wild. The affected\ngateway provides VPN access for 42 branch workstations. Your remediation vendor quotes $4,200\nper system for emergency patching, configuration hardening, and forensic log review, for a\ntotal project cost of $176,400. Write a brief internal incident summary for the client's IT\ndirector that states the CVE, explains the business impact, gives the total remediation cost,\nand recommends a remediation timeline that includes enforcing MFA on the VPN gateway during\nthe patch window.\n", "b1.cybersecurity-02": "Your MSP manages IT for a mid-size medical imaging practice, a HIPAA covered entity. After\nthe 2023 MOVEit Transfer breach (CVE-2023-34362, a SQL injection vulnerability in a managed\nfile transfer product) affected several healthcare vendors nationally, the practice's\ncompliance officer is re-vetting third-party vendors and has asked you, as the MSP's security\nlead, to complete Section 4 (\"Incident Response & Breach Notification\") of a vendor security\nquestionnaire on the MSP's own behalf, since the MSP has administrative access to systems that\nstore the practice's protected health information (PHI). Answer these three questionnaire\nitems in your response:\n1. What is your organization's regulatory timeline for notifying the covered entity after\n   discovering a breach of unsecured PHI?\n2. Do you enforce multi-factor authentication for all remote administrative access to systems\n   that touch PHI?\n3. Describe your process for verifying whether a third-party software component you rely on,\n   such as a managed file transfer tool, has a known CVE before you deploy it in the\n   practice's environment.\n", "b1.cybersecurity-03": "You are the on-call SOC analyst for an MSP client: a veterinary diagnostics laboratory that\nruns contract drug-safety trials for animal-health pharmaceutical sponsors. The lab's EDR\nand Windows event log pipeline just surfaced the following excerpt. All timestamps are UTC.\n\n  2026-02-11 03:14:22 WIN-LABDC01 Security 4625 Failed logon: user=svc_backup,\n    source=10.20.4.187, logon_type=3, status=0xC000006A\n  2026-02-11 03:14:26 WIN-LABDC01 Security 4625 Failed logon: user=svc_backup,\n    source=10.20.4.187, logon_type=3, status=0xC000006A\n  2026-02-11 03:15:03 WIN-LABDC01 Security 4624 Successful logon: user=svc_backup,\n    source=10.20.4.187, logon_type=3\n  2026-02-11 03:16:47 WIN-LIMS02 Sysmon 1 ProcessCreate: parent=svchost.exe,\n    image=C:\\Windows\\Temp\\psexesvc.exe, user=svc_backup,\n    commandline=\"psexesvc.exe -accepteula \\\\WIN-LIMS02 -u svc_backup cmd.exe\"\n  2026-02-11 03:17:12 WIN-LIMS02 Sysmon 3 NetworkConnect: image=cmd.exe,\n    dest=198.51.100.44, dest_port=443\n\nWIN-LIMS02 is the Laboratory Information Management System (LIMS) server that stores\nconfidential, unpublished trial results for the lab's pharmaceutical sponsors. The MSP's\nwritten escalation policy states: \"P1 = confirmed lateral movement into a system holding\nconfidential trial data, 1-hour SLA. P2 = suspicious authentication activity only, no\nconfirmed lateral movement, 4-hour SLA.\" Triage this alert: name the MITRE ATT&CK\ntechnique(s) represented in the log excerpt, state which SLA tier applies and why, and state\nthe single containment action that should happen FIRST, before anything else.\n", "b1.cybersecurity-04": "Your MSP manages the CORPORATE IT network (not the OT/SCADA pipeline-control network, which\nis operated separately by the client's automation team) for a regional oil & gas pipeline\noperator. A detection engineer handed you the following Sigma rule and asked you to reason\nabout whether a specific log line matches it, and what to do next.\n\n  title: Possible Zerologon Netlogon Exploitation (CVE-2020-1472)\n  status: stable\n  logsource:\n    product: windows\n    service: system\n  detection:\n    selection:\n      EventID: 5829\n      Provider_Name: 'Netlogon'\n    condition: selection\n  level: critical\n  tags:\n    - attack.privilege_escalation\n    - attack.t1210\n\nThe log line under review:\n\n  2026-03-04 22:41:09 DC-PIPE01 System 5829 Netlogon: The Netlogon service allowed a\n  vulnerable Netlogon secure channel connection using an insecure Netlogon secure channel\n  because the client machine account was covered by the Vulnerable Channel Allow List.\n  Source computer: WKSTN-4471.\n\nDC-PIPE01 is the client's primary Active Directory domain controller. State whether this log\nline matches the Sigma rule, name the MITRE ATT&CK technique the rule tags, explain why a\nmatch on this event ID is significant for CVE-2020-1472 specifically, and state what the\ncorrect next step is regarding the OT/SCADA network -- given that IT and OT are supposed to\nbe segmented, should the response assume pipeline-control systems are unaffected, or verify\nthat the segmentation actually held?\n", "b1.cybersecurity-05": "Your MSP just completed an M365 tenant hardening review for an architecture, engineering,\nand construction (AEC) firm client. The audit findings are:\n\n- Legacy authentication protocols (POP3, IMAP, Exchange ActiveSync basic auth) are still\n  enabled tenant-wide.\n- Security Defaults are OFF, and no Conditional Access policies exist.\n- 7 of the tenant's 9 Global Administrator accounts do not have MFA enrolled.\n- An SPF record exists for the domain, but DMARC is not published.\n- Outlook desktop client patch level is unverified fleet-wide. CVE-2023-23397 (a zero-click\n  Outlook NTLM-relay vulnerability triggered via a malicious calendar reminder sound, no user\n  interaction required) was patched in the March 2023 Patch Tuesday cycle.\n\nWrite a prioritized remediation plan, most critical finding first, and state which control\nyou would enable to close the Conditional Access / legacy-auth gap, which DNS record closes\nthe email-spoofing gap, and what you would do to confirm the Outlook fleet is no longer\nexposed to CVE-2023-23397.\n", "b1.cybersecurity-06": "Run a tabletop-exercise response for a mid-size law firm client based on the following\ninjected facts, in order:\n\nDay 1, 08:14 -- The firm's NetScaler ADC administrator reports unusual session behavior. The\nSOC confirms exploitation consistent with CVE-2023-4966 (\"Citrix Bleed\"), a session-token\ntheft vulnerability in Citrix NetScaler ADC/Gateway. No MFA prompt was observed for the\nhijacked sessions, because session-token theft replays an already-authenticated session and\nbypasses the MFA challenge entirely -- MFA re-enrollment does not, by itself, invalidate a\nstolen session token.\n\nDay 1, 14:30 -- EDR flags mass file encryption beginning on FS-DOCS02, the file server hosting\ncase files for three active litigation matters that are under a litigation hold, including\nattorney work product.\n\nDay 1, 15:00 -- A ransom note demands 12 BTC (approximately $780,000 at Day-1 spot price)\nwithin 96 hours. The firm's cyber insurance policy is claims-made with a consent-to-settle\nclause requiring the carrier's pre-approval of any incident-response vendor engagement or\ncost before the firm spends against the policy.\n\nWalk through the response in priority order. Specifically address: (1) the correct technical\ncontainment steps given that MFA does not stop this attack vector, (2) how you preserve\nevidence on FS-DOCS02 without violating the active litigation holds or destroying privileged\nwork product, (3) who must be engaged BEFORE remediation spending begins and why acting first\ncould jeopardize insurance coverage under the consent-to-settle clause, and (4) how you would\napproach the ransom demand without unconditionally recommending payment.\n", "b1.cybersecurity-07": "A 60-employee industrial-parts distributor (an MSP client with no dedicated security staff)\nwas hit by a phishing campaign. The facts, as confirmed by your team so far:\n\n- 6 employees opened an emailed Word attachment that exploited CVE-2022-30190 (\"Follina\"), a\n  Microsoft Office/MSDT remote-code-execution vulnerability triggered via a malicious external\n  link with no macros and no user interaction beyond opening the document, to drop a\n  credential-harvesting page that captured their Microsoft 365 passwords.\n- Sign-in logs show all 6 accounts had successful M365 logins from an unfamiliar ASN in\n  another country within 48 hours of the phishing email, and none of these logins triggered an\n  MFA challenge.\n- Two mailboxes, accountspayable@ and controller@, now have newly created inbox rules that\n  silently forward a copy of, and then delete, any message whose subject contains the word\n  \"invoice\".\n\nWrite a phishing-response runbook, in priority order, that a level-1 helpdesk technician with\nno security background could execute. Specifically address why a password reset alone will\nnot fully remediate this incident given what the sign-in logs show, and what you would check\nin each affected mailbox beyond the inbox rules already described.\n", "b1.cybersecurity-08": "Your MSP client is the Clerk's Office of a mid-size county government. The county's\nthird-party document-transfer vendor was compromised via CVE-2023-34362 (a SQL injection\nvulnerability in the MOVEit Transfer managed file transfer product), exposing a database\ncontaining Social Security numbers and driver's license numbers for approximately 8,400\nresidents who filed public records requests over the past five years. The compromise was\ndiscovered 6 days ago via the vendor's own breach disclosure. The county's outside counsel has\nconfirmed the applicable state breach-notification statute requires: (a) notification to\naffected residents within 30 days of discovery, and (b) notification to the state Attorney\nGeneral's office, because more than 500 residents are affected.\n\nDraft the client-facing incident summary the County Clerk will review before it is sent to\naffected residents and to the state Attorney General. Write in plain, accessible,\nnon-alarmist language appropriate for public release, state the scope and the two\nnotification obligations and their deadlines, recommend a concrete step to protect affected\nresidents given the types of data exposed, and avoid language that reads as an admission of\nfault or legal liability.\n", "b1.marketing-01": "You handle marketing for Hearth & Grain, a small-batch artisan bakery moving from\nfarmers-market sales into wholesale accounts with independent grocery stores. You surveyed\n40 independent grocery buyers who currently stock at least one local bakery brand, asking\nwhat matters most when deciding whether to add a new local bakery vendor to their shelves.\n\nResults: 68% ranked \"consistency of supply\" (reliably delivering the same quantity, on\nschedule, every week) as their #1 concern. 22% ranked price as #1. The remaining 10% ranked\npackaging/branding as #1. One buyer commented: \"We had a great bakery drop off our shelf\ntwice last year when they couldn't keep up during the holidays -- we won't take that risk\nagain.\" Hearth & Grain's stated goal for Q3 is to sign 15 new wholesale grocery accounts.\n\nWrite a positioning statement for pitching Hearth & Grain to independent grocery buyers,\nbuilt on what the research actually shows matters most to this audience -- not a generic\n\"handmade, artisan quality\" pitch. State the Q3 account goal the positioning should support.\n", "b1.marketing-02": "You run marketing for a regional credit union launching a Q3 campaign to generate qualified\nHELOC (home equity line of credit) applications. The total Q3 marketing budget is $60,000.\nTwo line items are already locked and cannot be reallocated: $18,000 for direct mail (already\nunder contract with the printer) and $9,000 for in-branch signage (already ordered).\n\nHistorical channel performance for the remaining flexible budget: paid search has historically\ncost $180 per qualified application; paid social has historically cost $260 per qualified\napplication; an email newsletter sponsorship costs a flat $2,000 regardless of volume and has\nhistorically driven about 20 applications per quarter (a hard ceiling -- the newsletter list\nisn't growing this quarter).\n\nThe stated Q3 goal is 150 qualified HELOC applications at a blended cost-per-application (CPA)\nacross the flexible channels of $220 or under. Determine how much flexible budget remains\nafter the two locked line items, then propose a channel allocation (with dollar amounts and\nexpected application volume per channel) that hits the 150-application goal without exceeding\nthe flexible budget, using the historical channel CPA data given.\n", "b1.marketing-03": "You're doing a landing-page critique for a solo estate-planning attorney's new PPC landing\npage. Current page performance: 1.2% conversion rate on this page, versus a 3.8% average\nacross the firm's other service pages, and a 74% bounce rate. Here is the page copy as it\nexists today:\n\nHeadline: \"We Guarantee You'll Protect 100% of Your Assets From Probate -- Guaranteed Results\nor Your Money Back.\"\n\nBody (three dense paragraphs of legal-jargon-heavy explanation of probate law follow the\nheadline, with no call-to-action visible until the very bottom of the page).\n\nTestimonial block: \"John saved his family $200,000!\" -- no disclaimer of any kind attached.\n\nContact form: located below all three paragraphs, requiring a scroll past roughly 600 words\nbefore a visitor sees it.\n\nCritique this page. Flag anything that is a problem for an attorney-advertising context\nspecifically (not just general conversion-rate-optimization advice), and recommend concrete\nfixes, including what should replace the \"guarantee\" framing and what the testimonial needs.\nReference the page's current conversion rate and bounce rate as your baseline for the audit.\n", "b1.marketing-04": "You handle demand generation for a B2B pipeline-integrity inspection services company. The\naverage sales cycle from first contact to signed contract is 7 months, and the primary buyer\npersona engaging with marketing content is a technical engineering manager (not the economic\nbuyer), who evaluates vendors on technical accuracy before anything else reaches budget\napproval. Sales has flagged that the single most common objection blocking deals from\nadvancing is: \"We need to see field data or case studies before we'll take this to budget\napproval.\"\n\nCurrent state: leads get exactly one follow-up email after a demo, which has a 4% reply rate,\nand un-replied leads are marked cold and dropped after 30 days with no further contact. The\nstated goal is to raise the 90-day engaged-lead rate (leads still actively responding to\noutreach 90 days after first contact) from the current 22% baseline to 35%.\n\nDesign an email nurture sequence for this technical buyer across the long sales cycle: specify\nthe number of touches, the cadence/timing between them, and the content focus of each touch.\nThe sequence must directly address the field-data/case-study objection sales has identified,\nand should not feel like a pushy sales cadence to an engineer who is 7 months from a decision.\n", "b1.marketing-05": "You lead marketing for a mid-size architecture firm that designs K-12 school facilities. A\nrival firm, Meridian Design Group, just announced a 15% fee discount on new institutional\n(K-12) contracts. In the past 6 months your firm lost 5 institutional bids to Meridian. Sales\ndebrief notes from those 5 losses show the client's stated reason for choosing Meridian in\neach case:\n\n- Loss 1: \"Meridian promised a design-development timeline 20% shorter than yours.\"\n- Loss 2: \"Their fee was lower, but honestly the deciding factor was they could start sooner\n  and finish design faster -- our board wanted to break ground this fiscal year.\"\n- Loss 3: \"Price was a factor, we went with the lower bid.\"\n- Loss 4: \"We needed the design phase done fast to hit a grant-funding construction deadline,\n  and Meridian's schedule commitment was the only one that worked.\"\n- Loss 5: \"Their proposed schedule was significantly faster than yours, which mattered more to\n  the board than the fee difference.\"\n\nWrite a competitive-response memo to firm leadership. Quantify, from the debrief notes, how\nmany of the 5 losses were actually price-driven versus schedule-driven, and use that to argue\nfor or against matching Meridian's 15% fee discount. Recommend a concrete response strategy.\n", "b1.marketing-06": "You market a HIPAA compliance-training and audit-readiness software product sold to\nhealthcare provider organizations. You have win/loss data for the last 12 closed deals:\n\nWon (7 deals): org sizes of 15, 40, 60, 90, 180, 300, and 450 providers/beds. All 7 of these\norganizations had a documented compliance audit finding or citation within the 12 months\nbefore they engaged with you.\n\nLost (5 deals): org sizes of 20, 75, 140, 260, and 500 providers/beds. None of these 5\norganizations had a recent audit finding or citation -- each was described in sales notes as\n\"proactively evaluating options, no urgent trigger.\"\n\nDefine the ideal customer profile (ICP) for this product using the win/loss data. Be explicit\nabout what percentage of wins shared the audit-finding/citation trait, and address directly\nwhy organization size is or isn't a reliable ICP signal given the size ranges in both the won\nand lost columns.\n", "b1.marketing-07": "You market a consumer genetic-testing diagnostics startup. The company is preparing to launch\na new at-home test in Q4. Clinical validation and FDA clearance for the new test are still\npending -- not yet complete -- so marketing content published before launch must not make any\nclaims about the new test's clinical accuracy, diagnostic performance, or medical efficacy.\n\nMarketing goal: build organic awareness and trust in the category ahead of the Q4 launch. You\nhave 10 weeks until launch and a cadence goal of 2 educational blog posts per week over that\nperiod.\n\nBuild a content calendar for the pre-launch window: state the total number of pieces the\ncadence produces, give topic categories appropriate for this stage (e.g., category education,\ngeneral genetics literacy, patient-journey stories), and state explicitly what kind of claims\nthe content must avoid given the pending clearance status.\n", "b1.marketing-08": "You run marketing for the MSP itself and are presenting this quarter's funnel readout.\nQuarterly figures: 40,000 website visitors -> 800 leads (form fills, a 2% visitor-to-lead\nrate) -> 320 MQLs (40% of leads) -> 96 SQLs (30% of MQLs) -> 24 closed customers (25% of\nSQLs). Total marketing spend this quarter was $48,000. Average annual contract value (ACV)\nper customer is $9,600, and gross margin is 70%.\n\nA prior readout assumed a 3-year average customer lifetime when calculating LTV. New cohort\ndata just came in: the actual measured average customer tenure, based on churn among\ncustomers acquired over the last two years, is 14 months -- not 3 years (36 months).\n\nCompute customer acquisition cost (CAC). Compute lifetime value (LTV) twice: once using the\nold 3-year lifetime assumption, and once using the actual 14-month measured tenure. State\nboth resulting LTV:CAC ratios. Then explain, using the two ratios, whether this quarter's real\nconstraint on growth is the acquisition funnel (traffic, lead conversion, CAC) or something\nelse, and name that constraint explicitly.\n", "b1.seo-01": "You're building a local SEO plan for a single-location veterinary clinic. Current state:\n\n- Google Business Profile (GBP): 38 reviews, average rating 4.1 stars. The top 3 competing\n  clinics within a 5-mile radius average 4.6 stars across 150-300 reviews each.\n- Only about 40% of the GBP profile fields are filled in -- holiday hours are missing, the\n  services list is not populated, and there are only 3 photos uploaded.\n- NAP (name, address, phone) consistency check: the clinic's old address is still listed on\n  Yelp, and an old phone number is still listed on Healthgrades. Both are correct on the GBP\n  listing and the clinic's own website.\n\nBuild a local SEO plan covering GBP profile completeness, a review-generation process with a\nconcrete review-volume target, and NAP consistency fixes across directories. State the\nclinic's current review count and rating as your baseline, and give a target review count and\ntimeframe. Prioritize the actions.\n", "b1.seo-02": "You're writing a content brief for an industrial-parts distributor targeting the search query\n\"hydraulic cylinder repair cost.\" Research data:\n\n- Average monthly search volume: 720.\n- The current top 10 ranking pages are 70% pricing/cost-guide informational content\n  (average word count approximately 1,400 words) and 30% product or repair-service pages.\n- \"People Also Ask\" boxes for this query include: \"How much does it cost to rebuild a\n  hydraulic cylinder?\" and \"Is it cheaper to repair or replace a hydraulic cylinder?\"\n\nWrite a content brief for this query: classify the dominant search intent, set a target word\ncount informed by what's currently ranking, list the H2 sections the piece needs (including\nanswers to both People Also Ask questions), and specify a call-to-action appropriate to the\nintent you classified (not a hard \"buy now\" CTA if the intent is primarily informational).\n", "b1.seo-03": "You're running a technical SEO audit for an architecture firm's WordPress site (Yoast SEO\nplugin installed, title templates not customized per post type). Crawl findings from 240\ntotal pages:\n\n- 18 pages return a 404 -- mostly old project-portfolio pages that are still linked from the\n  main navigation menu.\n- 34 pages have duplicate title tags -- the project-page template outputs the same generic\n  title on every project regardless of which project it is, with no unique project name\n  inserted.\n- A 12-page paginated blog series has no canonical or rel=next/prev handling configured,\n  triggering near-duplicate-content flags across the series.\n- Homepage Largest Contentful Paint (LCP) measures 4.8 seconds, versus Google's \"good\"\n  threshold of under 2.5 seconds.\n\nProduce a prioritized technical audit: for each issue, state the cause, the fix, and a\npriority ranking by expected impact versus effort. Address how the fixes apply specifically\nto a WordPress + Yoast setup.\n", "b1.seo-04": "You're building a keyword strategy for a regional credit union from Search Console-style\nperformance data (last 90 days):\n\n- \"auto loan rates [state]\" -- 8,200 impressions, 62 clicks, average position 11.4\n- \"personal loan calculator\" -- 5,100 impressions, 480 clicks, average position 3.2\n- \"credit union near me\" -- 12,000 impressions, 108 clicks, average position 9.8\n- \"how to refinance a car loan\" -- 3,400 impressions, 15 clicks, average position 22.1\n\nCompute the click-through rate (CTR) for each query. Identify which query is the best \"quick\nwin\" -- high impression volume, positioned close enough to page 1 that on-page/title\noptimization could realistically lift it, and currently converting that visibility into clicks\npoorly. Identify which query is already performing well and needs protection rather than\ninvestment, and which query would require a longer-term content investment given its position.\nState the CTR and position for the query you identify as the quick win.\n", "b1.seo-05": "You're critiquing an existing service page for a personal-injury law firm ahead of a rewrite.\nCurrent page:\n\nTitle tag: \"Best Personal Injury Lawyer Personal Injury Attorney Personal Injury Law Firm |\nSpringfield Personal Injury Lawyers\"\n\nBody content: 180 words total, covering only a brief generic overview of personal injury law.\nNo attorney name, bio, or credentials appear anywhere on the page. No disclaimer accompanies\nthe page's case-result mentions. Meta description: none written -- the page relies on\nGoogle's auto-generated snippet.\n\nCritique this page for SEO. Name the specific problem with the title tag as written. State the\ncurrent word count as your content-depth baseline and recommend a target length. Recommend\nwhat needs to be added given that legal content is treated by Google as YMYL (\"Your Money or\nYour Life\") content requiring stronger trust and expertise signals, and provide a proper meta\ndescription.\n", "b1.seo-06": "Apex Pipeline Solutions, a B2B industrial pipeline-inspection services company, is migrating\nits 340-URL site from an old domain to a new domain and a new CMS as part of a rebrand,\nlaunching in 6 weeks. Backlink data shows that 28 of the 340 URLs -- mostly technical\nwhitepaper and case-study pages -- hold 85% of the domain's total referring-domain link\nequity.\n\nTwo years ago, a different subsidiary site went through a similar migration and lost 60% of\nits organic traffic within 3 months, because the team redirected every old URL to the new\nhomepage instead of mapping each old page to its specific new-page equivalent.\n\nProduce a prioritized SEO migration checklist for the 6-week timeline. State the total URL\ncount and the count of high-equity URLs as the scope of the redirect-mapping effort, and be\nexplicit about what the redirect approach must be (referencing what went wrong in the prior\nmigration) versus what must NOT be done. Cover canonical tags, robots.txt, and XML sitemap\nhandling for the new domain as well.\n", "b1.seo-07": "A HIPAA compliance-training company has three separate pages all targeting overlapping\n\"HIPAA training\" search terms:\n\n- /hipaa-training -- general overview page, published 3 years ago, 45 referring domains.\n- /hipaa-compliance-training-for-employees -- published 1 year ago, 8 referring domains.\n- /online-hipaa-training-courses -- published 6 months ago, 3 referring domains.\n\nSearch Console shows all three pages alternate ranking for \"hipaa training\" week to week\nbetween positions 6 and 14, with none consistently breaking into the top 5. Combined, the\nthree pages get 4,200 monthly impressions but only 95 combined clicks for that term.\n\nDiagnose what's happening across these three pages and design an internal-linking plan that\nresolves it. State which of the three pages should be the designated primary target for the\nhead term \"hipaa training\" and why (cite the referring-domain counts). Recommend what to do\nwith the other two pages (consolidate, redirect, or re-scope to a distinct intent), and\ndescribe how sitewide internal links (navigation, related-resources modules, blog posts)\nshould be restructured to support the primary page.\n", "b1.seo-08": "A county government services website's organic traffic dropped from a baseline average of\n28,000 monthly organic sessions to 16,240 -- a 42% drop -- over a 30-day window. The drop\ncoincided exactly with a site redesign/relaunch 5 weeks ago that changed the CMS templating\nand site structure. The content team states no actual page content was rewritten or removed --\nonly the visual design and template changed.\n\nAdditional data pulled from Search Console since the relaunch: pages marked \"Crawled --\ncurrently not indexed\" jumped from a baseline of about 40 pages to 1,100 pages, and pages\nflagged \"Duplicate, Google chose different canonical than user\" jumped from near-zero to 380\nURLs. There is no manual action notice on the account, and no Google core algorithm update was\nannounced during this window.\n\nWrite a diagnostic plan. State the baseline and post-drop session counts. Rule out the\nhypotheses the data contradicts (content-quality decline, algorithm update, manual penalty)\nand explain why. Identify the most likely technical root cause given the indexation and\ncanonical data, and specify what to check first (and in what order) to confirm it.\n", "b1.sales-01": "You sell a cloud-based practice-management platform (scheduling, billing, e-prescribing) to\nveterinary clinics. You just finished an intake call with Fetch & Wellness Animal Hospital, a\nsingle-location practice with 3 veterinarians. Notes from the call:\n\n- The practice owner, Dr. Patel, is the sole decision-maker -- there is no procurement\n  committee or IT department to loop in.\n- They currently run scheduling on a 15-year-old desktop application that has no cloud or\n  mobile access.\n- Dr. Patel estimated their no-show rate at 18% of booked appointments.\n- Front-desk staff spend about 2 hours a day making manual phone call reminders to try to\n  keep that no-show rate down.\n\nBuild a discovery-call plan for the next conversation with Dr. Patel: state the call's goal,\nlist the specific questions you'll ask that build directly on what she already told you (the\nno-show rate and the manual reminder time), and recommend a concrete next step to close the\ncall. Keep the plan appropriate for a single-owner practice making a fast, direct decision --\nnot a multi-stakeholder enterprise sales process.\n", "b1.sales-02": "You just closed a deal with Ridgeline Structural Engineering, a 45-person structural\nengineering firm, for your project-management software. Deal specifics from the signed\ncontract:\n\n- 45 seats at $840/seat/year.\n- Start date is August 1.\n- Onboarding priority #1: import their 12 currently active projects.\n- Ridgeline's existing document management system is ProjectWise, and the contract requires\n  the new platform to integrate with it -- this was a hard requirement during the sales\n  process, not a nice-to-have.\n- The champion who negotiated the deal, Director of Operations Sana Ruiz, was firm that\n  mandatory two-factor authentication (2FA) must be enabled for every user from day one.\n\nWrite a hand-off-to-delivery document for the implementation/onboarding team, summarizing the\ndeal so they can plan onboarding without needing to re-contact the prospect for basics. State\nthe total annual contract value.\n", "b1.sales-03": "You sell fraud-detection software to regional banks. You're finalizing a proposal for Palisade\nCommunity Bank. Scope and pricing agreed with their fraud/compliance team:\n\n- Core platform license: $60,000/year.\n- One-time implementation and onboarding fee: $15,000, billed only in year 1.\n- Optional add-on module (real-time transaction alerting), which they've requested: $12,000/year.\n\nWrite the executive summary section of the proposal, aimed at the bank's board, who will be\napproving this spend and need the numbers to be exactly right (this is a regulated\nenvironment -- an internally inconsistent proposal undermines credibility). State the total\nyear-1 investment and the ongoing annual cost from year 2 onward, with a clear breakdown of\nwhat's included in each figure.\n", "b1.sales-04": "You sell pipeline-integrity compliance-tracking software. Continental Pipeline Services has\nused a competitor product, DrillTrack, for the past 8 years, and DrillTrack is deeply\nentrenched with their field-inspection team. Battle-card facts for this displacement:\n\n- DrillTrack has no real-time mobile field-data entry. Inspectors fill out paper forms in the\n  field, then re-enter that data by hand back at the office -- a roughly 3-day data lag before\n  inspection results are visible in the system.\n- Your platform captures inspection data on mobile in real time, cutting that lag to the same\n  day.\n- DrillTrack costs Continental $95,000/year. Your platform lists at $110,000/year.\n- Continental currently pays 2 administrative staff at 0.5 FTE each (1.0 FTE combined) just to\n  re-key paper inspection forms into DrillTrack, at a fully-loaded cost of about $40,000/year\n  for that re-entry labor -- work your real-time mobile entry would eliminate entirely.\n\nWrite a competitive-displacement talk track for the sales rep to use with Continental's VP of\nField Operations. Use the battle-card facts above -- don't invent capabilities DrillTrack may\nor may not have beyond what's stated. Address the sticker-shock of the higher list price\ndirectly using the labor-cost savings, and state the net annual cost impact of switching.\n", "b1.sales-05": "You sell IoT predictive-maintenance monitoring software, priced at $1,200/sensor/year. Harvest\nLine Equipment, a mid-size manufacturing_ag equipment plant, wants to deploy across 200\nsensors -- a list-price deal of $240,000/year. They're requesting a 3-year contract in\nexchange for a 20% discount off list ($192,000/year).\n\nYour discount authority: sales reps can approve up to 15% off list ($204,000/year) without\nfurther sign-off. Any discount beyond 15% -- including Harvest Line's 20% ask -- requires VP\nof Sales approval because of the margin impact at that depth.\n\nWrite a pricing-negotiation guardrails memo for the account team: state the list price, the\n15% floor a rep can approve unilaterally, why the 20% ask exceeds that floor and needs VP\napproval, and a recommended counter-offer that keeps the numbers internally consistent with\nthe stated discount authority.\n", "b1.sales-06": "You sell a cloud-based, multi-tenant SaaS e-discovery and document-review platform. During a\ndemo with Kestrel & Voss LLP, a 60-attorney litigation firm, IT Director Priya Anand raised\nthis objection:\n\n\"Our biggest client is a defense contractor bound by strict data-residency and\non-premises-only requirements for anything touching their litigation documents. We need this\nplatform hosted entirely on our own servers, not your cloud. If it's not on-prem, we can't use\nit for that client's matters.\"\n\nYour product is cloud-only -- there is no on-premises deployment option, and there never has\nbeen. What you do offer: dedicated single-tenant cloud instances (each client's data is\nphysically isolated, never co-mingled with other tenants), SOC 2 Type II certification, and a\nfull chain-of-custody audit log for every document access. Of Kestrel & Voss's 40 currently\nactive matters, only 2 (5%) carry a contractual on-premises-only mandate like the defense\ncontractor's; the remaining 38 (95%) have no such requirement.\n\nWrite the objection response. Do not claim or imply an on-premises option exists -- it\ndoesn't. Address the objection honestly: be direct that the platform is not the right fit for\nmatters bound by a literal on-prem mandate, then make the case, using the actual figures\nabove, for why it's still the right fit for the bulk of their caseload, and propose a concrete\nnext step.\n", "b1.sales-07": "Northfield Regional Health System's HIPAA compliance-training platform renewal ($54,000/year)\nis due in 45 days. Usage data over the last two quarters:\n\n- The platform was originally championed and driven by Dr. Elaine Cho, then Chief Compliance\n  Officer, who personally sponsored the rollout. Under her sponsorship, Q1 mandatory-training\n  completion across required staff was 85%.\n- Dr. Cho left Northfield 4 months ago. Since then, Q2 completion has fallen to 40%, and\n  logins from the compliance department are down 70% month-over-month.\n- The interim compliance lead, Grace Liu, has never logged into the platform.\n\nWrite a renewal-at-risk save plan. Diagnose the actual risk driver using the usage data -- not\na generic \"usage is down\" framing -- and lay out a concrete plan to re-engage the account\nbefore the 45-day renewal date, addressing the ownership gap the data reveals.\n", "b1.sales-08": "Weekly pipeline review. Four open opportunities:\n\n- Opportunity A -- the state Department of Transportation, $420,000 ARR. Prospect is \"very\n  interested\" but no formal procurement process has started; no RFP, no confirmed budget, and\n  the champion is a mid-level analyst. Expected timeline: \"sometime next year.\"\n- Opportunity B -- Fairview County Parks & Recreation Department, $85,000 ARR. An RFP has been\n  issued with a hard submission deadline in 6 days. You meet every stated requirement. It's a\n  competitive RFP (3 vendors invited), and under this agency's public-sector procurement\n  rules, missing the submission deadline means automatic disqualification -- no exceptions,\n  no late submissions accepted.\n- Opportunity C -- Bristol City IT Department, $210,000 ARR. Verbal budget approval is in\n  hand, but the formal purchase order requires a city council vote at their next public\n  meeting, 90 days out, per the city's budget-cycle rules. The deal is effectively done\n  pending that vote.\n- Opportunity D -- the Town of Millbrook, $30,000 ARR. Still an informal, early-stage\n  conversation.\n\nTriage all four opportunities, put them in order for handling this week, and justify each\nranking using the actual procurement constraints and signals described -- not deal size.\n", "b1.outreach-01": "You sell a checkout-optimization and cart-recovery SaaS tool that integrates directly with\nShopify. Prospect dossier for Coastal Trail Outfitters, a direct-to-consumer outdoor apparel\nbrand:\n\n- They run their store on Shopify.\n- They launched a new hiking-boot product line 3 weeks ago.\n- The founder, in a podcast interview last month, said: \"We're losing almost 40% of shoppers\n  at checkout -- cart abandonment is brutal, and I don't know why.\"\n- It's an 8-person company; the founder is the sole decision-maker.\n\nWrite a 3-touch cold email sequence (specify the timing between touches) that opens the deal.\nPersonalize using the specific dossier details above -- the podcast quote, the Shopify\nplatform, the new hiking-boot launch -- rather than a generic {first_name}-only merge. Include\na clear sender identity and an unsubscribe/opt-out line, since this is unsolicited cold email.\n", "b1.outreach-02": "You sell BIM (Building Information Modeling) clash-detection coordination software. Ironwood\nStructural Group, a happy existing customer for 14 months, just had a check-in call with your\nCSM. Notes from that call:\n\n- Their 22-engineer team ran 340 clash-detection runs last quarter and estimates the tool\n  caught about $180,000 in field-rework costs before construction started.\n- The champion mentioned they know the principal at Bramwell Architecture Partners, a firm\n  Ironwood frequently co-bids projects with, and said: \"Bramwell's still doing clash\n  detection by hand -- I've told them they need this.\"\n\nWrite a referral-ask email to the Ironwood champion, referencing their own account's specific\nusage and savings figures, and directly naming Bramwell Architecture Partners as the referral\nask.\n", "b1.outreach-03": "You sell reconciliation-automation software for community banks. Prospect dossier for Elena\nVasquez, VP of Operations at Alder Community Bank (~$2.1B in assets):\n\n- Two weeks ago she posted on LinkedIn: \"Our reconciliation team is still doing month-end\n  close with spreadsheets across 6 different systems -- 3 full days every month just to close\n  the books. There has to be a better way in 2026.\"\n- You share a mutual LinkedIn connection, Marcus Webb, a former colleague of Elena's who is\n  now a customer of yours at a different bank.\n\nWrite a short LinkedIn connection request message (respecting LinkedIn's roughly 300-character\nlimit on connection notes) plus a follow-up message to send after she accepts. Personalize\nusing her specific post content (the 6-system, 3-day month-end close) and the Marcus Webb\nmutual-connection angle -- not a generic connection request.\n", "b1.outreach-04": "You met Derek Chen, Fleet Maintenance Manager at Prairie Grain Cooperative, at your booth at\nthe AgriTech Solutions Expo last week. Notes from the booth scan:\n\n- Derek manages 85 pieces of John Deere precision-ag equipment across 3 regional depots.\n- He specifically asked whether your predictive-maintenance platform integrates with John\n  Deere Operations Center telematics data, since that's his team's current data source. His\n  team currently has zero integration between that data and any maintenance-planning tool, and\n  relies on manual inspection logs.\n- He mentioned budget planning for next fiscal year starts in about 8 weeks.\n\nWrite a 3-email event-follow-up sequence for the ~3 weeks after the show, specifying the\ncadence between emails. Personalize using the specific dossier details -- the John Deere\nOperations Center integration question and his 85-unit fleet across 3 depots -- and build the\nsequence toward being useful ahead of his 8-week budget-planning window. Include an unsubscribe\nline, since this follows a booth scan and is effectively cold email outreach.\n", "b1.outreach-05": "You sent a cold email to hospital compliance officers about your HIPAA risk-assessment\nautomation tool. Three replies came back. Write a branch response for each, handling them\nappropriately rather than with one copy-pasted reply:\n\nReply 1 (positive), from Redwood Health Alliance: \"This is actually well timed -- we have a\nJoint Commission survey in 6 weeks and our last risk assessment is over a year old. Can we\ngrab 20 minutes this week?\"\n\nReply 2 (negative/objection): \"We already have an internal compliance team that handles this\nmanually. We're not looking to add another vendor tool right now.\"\n\nReply 3 (out-of-office auto-reply): \"I am out of the office until [date] with limited email\naccess. For urgent compliance matters, please contact [backup contact].\"\n\nFor Reply 1, propose specific meeting logistics tied to the stated 6-week Joint Commission\ndeadline. For Reply 2, address the objection honestly rather than pitching past it -- don't\nclaim they need to switch tools if the honest answer is they may not. For Reply 3, describe\nhow to handle the OOO correctly (don't immediately re-send; note the stated return context and\ntime the next touch appropriately).\n", "b1.outreach-06": "Your company submitted a response to an open RFP (RFP #PH-2026-0219, records-management\nsoftware) issued 12 days ago by the Overlook County Public Health Department. The RFP's\nprocurement rules include an explicit \"quiet period\" / no-contact clause: from the RFP's\nissuance date until the contract-award decision, vendors are prohibited from any direct\ncontact with evaluation-committee members or agency staff about the RFP outside the official\nQ&A process administered by the county procurement office. Violating the quiet period can\nresult in disqualification from the RFP. The award decision isn't expected for another 60\ndays.\n\nJordan Alvarez, IT Procurement Analyst, is a listed member of the evaluation committee for\nthis RFP.\n\nDesign a first-contact/call-scheduling flow for engaging Jordan Alvarez, given the quiet-\nperiod rule above. Be explicit about what the flow does and does not do during the 60-day\nquiet period, and when normal outreach cadence can resume.\n", "b1.outreach-07": "You sell e-discovery software to law firms. Two weeks ago your SDR sent litigation partner\nDiane Okafor, of the 12-attorney firm Okafor & Reyes, an initial cold email about the product;\na LinkedIn connection request went out the same day. She replied -- the only reply on\nrecord:\n\n\"I got your first email and the LinkedIn request together within the same day -- that's a lot\nfor a first touch, and we're heads-down through a jury trial starting in 3 weeks. If this is\nworth pursuing: email only, no more than once every two weeks, and nothing until after the\ntrial wraps -- about 6 weeks out.\"\n\nShe did not decline. She left the door open, explicitly at reduced frequency and a single\nchannel. Design the multi-channel cadence going forward. The correct design pulls back sharply\nfrom a typical multi-touch, multi-channel cadence: honor the single-channel (email-only)\nrequest, cap frequency at no more than once every two weeks, and hold a firm pause of about 6\nweeks before the first resumed touch. Include an unsubscribe line on the resumed emails.\n", "b1.outreach-08": "Cascade Midstream Services, a pipeline-services company, went completely dark 5 months ago.\nThe last CRM note, from VP of Engineering Tom Brennan, reads: \"Corporate froze all new\nsoftware spend after the Q3 layoffs -- 15% of the engineering team was let go. Check back\nafter the new fiscal year starts, about 6 weeks out, once the new budget is approved.\" Two\ngeneric follow-up emails sent since then have gone unanswered.\n\nWrite a re-engagement message for Tom Brennan. The correct approach references the SPECIFIC\nreason he gave -- the budget freeze following the Q3 layoffs -- and times the outreach to\ntheir actual fiscal-year budget reopening, rather than sending another generic \"just checking\nin\" message right away. A single, well-timed, specific message beats resuming a generic\ncadence immediately. Include an unsubscribe line.\n", "b1.finance-01": "You're the accounting manager closing the books for an MSP's own internal finance team for\nMay. Your close checklist status is:\n\n1. Operating bank account reconciliation -- DONE, ties to GL.\n2. Payroll clearing account reconciliation -- NOT done; the clearing account shows an\n   unexplained variance of $1,842.17 between the bank statement and the GL balance.\n3. AP subledger tied to GL -- DONE.\n4. AR subledger tied to GL -- DONE.\n5. Prepaid expense amortization -- a $7,200 annual software license was paid in full in\n   January and set up as a prepaid asset, to be amortized evenly over the 12-month license\n   term. No amortization entries have been booked in any of the 5 months since (Jan-May), so\n   the full $7,200 is still sitting on the balance sheet as a prepaid asset.\n6. Fixed asset depreciation run -- DONE.\n7. Accrued payroll -- DONE.\n8. Deferred revenue schedule -- DONE.\n9. Journal entry review/approval -- 4 JEs posted this month are still pending controller\n   sign-off.\n10. Trial balance / suspense account review -- the suspense account, which should always net\n    to zero at close, carries a $612.50 balance.\n\nIdentify the close gaps that pose the highest risk to a reliable close, calculate the dollar\namount of P&L expense that is currently missing because of the unamortized prepaid, and\nrecommend the sequence of actions to close the books cleanly this month -- including what\nmust happen before the controller can sign off on these financials as final.\n", "b1.finance-02": "You run finance for a small custom-apparel print shop. Current unit economics per printed\nshirt:\n- Sell price: $30.00\n- Variable costs: blank garment $8.00, printing/ink $3.00, packaging $1.00 (total $12.00)\n- Current contribution margin: $18.00/unit (60%)\n- Fixed monthly overhead: $21,600\n- Current monthly volume: 1,450 units\n\nYour blank-garment supplier just raised the blank garment price by 15%, with no change to\nprinting or packaging costs, effective immediately. You have not changed your sell price.\n\nCalculate: (1) the new variable cost per unit and the new contribution margin in dollars and\nas a percentage at the current $30.00 price, (2) the monthly profit impact of doing nothing\n(same price, same 1,450-unit volume) compared to before the cost increase, and (3) the sell\nprice you would need to charge to restore the original 60% contribution margin percentage.\nState your breakeven volume at the new cost structure at the current price too.\n", "b1.finance-03": "You handle AP for a general contractor. Subcontractor \"Delta Concrete LLC\" is on PO #4471 for\nfoundation work, total contract value $186,000, with standard contract terms: 10% retainage\nwithheld from every progress payment until substantial completion.\n\nThis period's documents:\n- PO #4471: total scope $186,000 (unchanged).\n- Field-certified progress report: the project engineer certifies 65% of the foundation scope\n  is actually complete as of this pay period.\n- Delta Concrete's invoice this period: bills $128,000 for progress to date this period.\n\nRun the 3-way match (PO vs. certified progress vs. invoice). Identify any exception, quantify\nthe dollar discrepancy, and calculate the correct net amount that should actually be released\nto Delta Concrete this period once retainage is properly applied to the certified (not\ninvoiced) amount. State what should happen before any payment is released.\n", "b1.finance-04": "You manage billing/collections for a law firm. Current fee (operating) AR ledger, terms\nNet 30:\n\n- Client A: $18,500 invoice, 95 days past due\n- Client B: $6,200 invoice, 40 days past due\n- Client C: $42,000 invoice, 15 days past due\n- Client D: $9,800 invoice, 130 days past due\n\nSeparately, the firm's IOLTA client trust ledger shows Client A also has $22,000 held in\ntrust -- an advance the client provided specifically to cover future expert-witness costs on\ntheir litigation matter, per the engagement letter. That trust balance is the client's money,\nnot the firm's, until it is properly earned or a specific trust-to-fee transfer is authorized.\n\nBuild an aging summary by bucket (1-30, 31-60, 91+ days past due) with bucket totals and the\ntotal AR balance. Then produce a dunning plan in priority order for Clients A, B, and D. Your\nplan must NOT simply sweep Client A's trust balance to cover their overdue fee invoice --\nstate what a proper trust-to-fee transfer requires before any trust funds could be applied\nagainst fees.\n", "b1.finance-05": "You're preparing the quarterly board finance summary for a specialty consumer lender. Given\nfigures (pre-tax, $):\n\nQ1 (prior quarter):\n- Net interest income (NII): $4,200,000\n- Provision for credit losses: $600,000\n- Non-interest (operating) expense: $2,800,000\n- Total loans outstanding: $290,000,000\n- Allowance for loan losses (ALL) balance: $4,060,000\n\nQ2 (this quarter):\n- Net interest income (NII): $4,410,000\n- Provision for credit losses: $930,000\n- Non-interest (operating) expense: $2,884,000\n- Total loans outstanding: $310,000,000\n- Allowance for loan losses (ALL) balance: $4,650,000\n\nWrite a one-page board summary that: (1) derives pre-tax net income for both quarters from\nthe given P&L lines and shows the reconciliation, (2) correctly explains WHY net income\nchanged the way it did between quarters -- attribute the change to the correct driver among\nNII growth, provision growth, and opex growth, don't just say \"costs went up,\" (3) computes\nthe allowance-for-loan-losses coverage ratio (ALL / total loans) for both quarters and flags\nthe trend, and (4) states one item that needs board discussion or a decision.\n", "b1.finance-06": "Parent company owns two E&P subsidiaries that are intercompany affiliates: OpCo (operator,\n75% working interest in a well) and NonOpCo (non-operating partner, 25% working interest in\nthe same well, per the Joint Operating Agreement).\n\nAn AFE (Authorization for Expenditure) for a workover project on the well was approved at a\ntotal project budget of $2,400,000. Actual costs incurred on the workover came in at\n$2,600,000 -- over the AFE budget.\n\nOpCo's books: OpCo operates the well and issues a JIB (Joint Interest Billing) statement to\nNonOpCo for its working-interest share of ACTUAL costs. OpCo booked an intercompany\nreceivable from NonOpCo of 25% of the $2,600,000 actual cost.\n\nNonOpCo's books: NonOpCo's month-end close happened before it received OpCo's final JIB\nstatement (JIB statements routinely lag field costs by 30-45 days). With no actual-cost JIB\nin hand yet, NonOpCo's accounting team accrued its intercompany payable to OpCo based on the\nbest information it had: its 25% working-interest share of the original $2,400,000 AFE\nbudget.\n\nAt parent-level consolidation, the intercompany receivable on OpCo's books does not tie to\nthe intercompany payable on NonOpCo's books. Quantify the break, determine which side needs a\ntrue-up adjustment (and to what correct balance), and explain why this is NOT a booking error\nby either subsidiary. State the AFE overrun percentage separately, and note that the\nnon-operating partner's notification/consent requirements for cost overruns are governed by\nthe specific Joint Operating Agreement's terms, which should be checked rather than assumed.\n", "b1.finance-07": "You're doing a monthly budget variance analysis for a multi-provider medical practice's net\npatient revenue. Two payers only, for simplicity.\n\nBudget:\n- Total visits: 2,000\n- Payer mix: 60% Commercial (1,200 visits), 40% Medicare (800 visits)\n- Reimbursement rate: Commercial $220/visit, Medicare $110/visit\n- Budgeted revenue: Commercial $264,000, Medicare $88,000, Total $352,000\n\nActual:\n- Total visits: 2,000 (same total volume as budget)\n- Payer mix: 45% Commercial (900 visits), 55% Medicare (1,100 visits)\n- Reimbursement rate: Commercial $220/visit (unchanged), Medicare $110/visit (unchanged)\n- Actual revenue: Commercial $198,000, Medicare $121,000, Total $319,000\n\nThe practice administrator's first-draft narrative says \"reimbursement rates are being cut --\naverage revenue per visit fell from budget.\" Determine whether that narrative is correct.\nCompute the total revenue variance in dollars and as a percentage, and decompose it: how much\nof the shortfall is a true rate variance (payer actually reimbursing less per visit), how much\nis a volume variance (fewer total visits), and how much is a payer-mix variance (a shift in\nthe proportion of visits between payers, each still paid at its budgeted rate)? Recommend one\ndriver-based corrective action rather than a generic cost-cutting response.\n", "b1.finance-08": "You're building a 13-week cash-flow forecast for a clinical-stage biotech. Assume all weekly\nburn and all inflows are recognized at the end of each week (no intra-week timing to model).\n\n- Starting cash balance (beginning of Week 1): $3,200,000\n- Weekly net operating cash burn, Weeks 1-7: $185,000/week\n- Starting Week 8, a new lab-operations hire cohort begins, raising weekly burn to\n  $215,000/week for Weeks 8-13\n- Week 6 inflow: NIH grant milestone payment, $450,000\n- Week 10 inflow: pharma-partner collaboration/licensing milestone payment, $900,000\n- The company's venture debt agreement includes a minimum-liquidity covenant: unrestricted\n  cash may never fall below $500,000\n\nBuild the week-by-week ending cash balance for all 13 weeks. State the Week 13 ending balance,\nand identify which week has the LOWEST ending cash balance across the full 13-week window --\nit is not necessarily Week 13. State whether the minimum-liquidity covenant is breached at any\npoint in the 13-week window. Then, using the Week 13 ending balance and the Week 8-13 burn\nrate, estimate approximately how many additional weeks of runway remain past Week 13 (assuming\nno further inflows and burn stays flat) before the company would breach the $500,000 covenant\nfloor, and flag this explicitly as an unfunded-scenario estimate, not a forecast commitment.\n", "b1.operations-01": "You run operations for a small e-commerce apparel retailer's order-fulfillment process.\nCurrent baseline: average time from order placed to shipment = 3.2 days, and 4.5% of orders\nship with the wrong item. Root cause investigation found that warehouse staff manually re-key\neach order's pick list from the order system into a paper pick sheet before pulling items --\nand every re-keying step is a chance to transpose a SKU. Orders also sit in one unsorted\nqueue rather than being grouped by warehouse zone.\n\nRedesign the SOP to reduce both the time-to-ship and the wrong-item rate. State a baseline ->\ntarget KPI for each metric, and sequence the first three implementation steps. There is no\nbudget approved this quarter for new warehouse management software -- your redesign has to be\na process fix using the tools already in place, not a system purchase.\n", "b1.operations-02": "You manage vendor performance for a general contractor's ready-mix concrete supplier. The\nsupply contract's SLA requires: on-time delivery >= 95%, and short-load (under-delivered\nvolume) incidents <= 2% of deliveries. Below either threshold, the contract allows either a\nformal corrective action plan or liquidated damages.\n\nThis quarter's data (12 deliveries):\n- On-time: 10 of 12 deliveries\n- Short-load incidents: 1 of 12 deliveries\n- Slump-test (quality) pass rate: 12 of 12 deliveries\n\nThis is the SECOND consecutive quarter this vendor has fallen below the on-time threshold.\n\nBuild a scorecard against each SLA metric (pass/fail), calculate the on-time performance gap\nin percentage points versus the 95% requirement, and recommend the next contractual action\ngiven this is a repeat, not first-time, shortfall.\n", "b1.operations-03": "You manage inventory policy for a clinic's refrigerated insulin vial stock. Facts:\n- Average demand: 140 vials/week\n- Supplier lead time: 2 weeks\n- Current reorder point (ROP): 200 vials\n- Vials have a 60-day shelf life from receipt (roughly 8.5 weeks)\n- Current replenishment order quantity: 560 vials (about a 4-week supply at average demand)\n- Three stockout events in the past 6 months, each lasting 4-5 days, all coinciding with weeks\n  where a local seasonal diabetes-outreach event pushed demand to about 185 vials/week (about\n  32% above average)\n\nCalculate the average demand expected DURING the 2-week lead time and compare it to the\ncurrent reorder point to explain why stockouts are close to inevitable even without a demand\nspike. Propose a new reorder point that builds in a safety-stock buffer sized to cover one\nspike-level week during the lead-time window. Confirm your recommended order quantity still\nrespects the 60-day shelf-life limit (no overstocking into expiry waste). State a baseline ->\ntarget KPI for stockout incidents.\n", "b1.operations-04": "You manage capacity planning for a clinical-trial central lab that processes patient blood\nsamples. Facts:\n- Current staffing: 3 technicians, each validated to process 40 samples/day\n- Current actual volume: 85 samples/day (comfortably within current capacity)\n- Sponsor's enrollment-ramp forecast: volume will reach 150 samples/day within 6 weeks as new\n  trial sites activate\n- Samples must be processed within 24 hours of the blood draw per the trial protocol's\n  validated stability window -- they cannot be queued or held over as a workaround\n- A new technician takes 3 weeks of training and mandatory certification before they can\n  independently process protocol samples, and hiring/budget approval itself takes 1 week\n  before training can even start\n\nCalculate current lab capacity and the capacity gap against the 6-week demand forecast.\nDetermine the minimum additional headcount needed (capacity comes in whole-technician\nincrements). Work backward from the 6-week deadline through the approval-plus-training lead\ntime to state the LATEST week from today that hiring approval must be initiated to have the\nnew technician certified before the demand peak hits. Explain why queuing samples is not a\nviable stopgap given the 24-hour stability window.\n", "b1.operations-05": "You're redesigning the handoff between a county's Planning Department (initial application\nreview) and Building Department (inspection scheduling and permit issuance) for residential\nbuilding permits. Current baseline: average handoff time from Planning sign-off to Building\nDepartment scheduling the first inspection = 12 business days.\n\nRoot cause: Planning emails a PDF application packet to a shared Building Department inbox\nthat staff only checks once a week, every Monday -- so a packet that clears Planning on a\nTuesday can sit untouched for up to 6 business days before anyone even opens it. Separately,\n30% of packets get bounced back to Planning for a missing required document (the site survey)\nthat Planning does not verify is attached before sending, adding a further ~5 business day\nround trip whenever it happens.\n\nIdentify the actual bottleneck driver (it's not overall department workload). Redesign the\nhandoff mechanism and give a baseline -> target KPI for both handoff time and the\nmissing-document bounce-back rate. Sequence the first two implementation steps. There is no\nnew headcount approved this budget cycle and no budget for new paid software this fiscal year\n-- your fix has to use existing tools and staffing.\n", "b1.operations-06": "You're doing a bottleneck analysis on a poultry processing line with four stations in series:\n\n1. Evisceration -- continuous process, 50 units/min.\n2. Chill tumble -- BATCH process. The tumbler only runs once it has a full 900-unit batch\n   accumulated (it cannot run partial batches without compromising chill efficacy), and each\n   batch cycle (load + chill + unload) takes 20 minutes for 1,000 units per batch. Because\n   units visibly pile up at the chill in-feed while a batch accumulates, floor supervisors\n   have flagged chilling as \"the bottleneck\" -- it's where they see the largest standing queue\n   on the line.\n3. Portioning/cut-up -- continuous process, 38 units/min.\n4. Packaging -- continuous process, 42 units/min.\n\nThe plant runs one 8-hour shift/day and has a daily processing target of 20,000 units.\n\nCalculate each station's effective throughput rate (including the chill tumbler's batch\nmath). Determine the TRUE line-limiting bottleneck and explain, with numbers, why it is NOT\nthe chill station despite chill having the largest visible work-in-process queue. Calculate\ntoday's maximum achievable daily output at the true bottleneck's rate and the shortfall\nagainst the 20,000-unit target. State the minimum rate the true bottleneck station needs to\nhit in order to reach the daily target. Warn against the \"obvious\" fix of adding a second\nchill tumbler, and explain with numbers why it would not move daily output at all.\n", "b1.operations-07": "Run an incident postmortem for a payments company. Facts:\n\n- The nightly ACH settlement batch processes payouts for 4,200 merchants. The job failed\n  partway through at 11:15 PM after successfully processing 40% of merchants; the remaining\n  60% did not receive their payout that night.\n- The automated retry policy fires 3 retries spaced 15 minutes apart (11:30 PM, 11:45 PM,\n  12:00 AM) before a human on-call engineer is paged -- a 45-minute designed escalation\n  window.\n- The on-call engineer's phone was set to Do Not Disturb, and this settlement-batch alert was\n  not on their configured DND-override allowlist, so the 12:00 AM page produced no human\n  response.\n- Human awareness of the incident did not actually occur until 2:15 AM, when a merchant's\n  support ticket about a missing payout reached an engineer.\n- Root-cause investigation of the batch job failure itself traced it to a known, already\n  open, lower-priority ticket: database connection-pool exhaustion under load.\n- Constraint: the team has a fixed on-call rotation with no budget approved for a dedicated\n  24/7 NOC team -- any fix must work within the existing on-call model.\n\nBuild the incident timeline. Quantify the merchant impact and the gap between the designed\n45-minute escalation window and the actual time to human awareness. Distinguish the proximate\ntechnical bug from the true driver of why this became a multi-hour, customer-impacting\nincident instead of a quick blip, and propose a process fix that targets the real driver\nwithout adding headcount. State explicitly why fixing only the database bug would not prevent\na similarly bad incident recurring from a different, unrelated failure.\n", "b1.operations-08": "Leadership at your MSP needs to cut $18,000/month in internal operating cost within this\nquarter (3 months), without breaching any client SLA or eating an avoidable vendor penalty.\nCandidate actions:\n\nA. Cancel the underutilized RMM overflow-tier license: saves $4,200/month, no penalty,\n   effective immediately.\nB. Terminate the secondary data-center colo contract early: saves $9,500/month, BUT 8 months\n   remain on the contract with an early-termination penalty of $6,000 per remaining month\n   ($48,000 total if canceled now). The contract converts to penalty-free month-to-month in\n   4 months.\nC. Renegotiate the internal software/tooling stack down a tier: saves $2,800/month, takes 6\n   weeks to implement (vendor renewal-cycle timing), no penalty.\nD. Optimize on-call shift scheduling to eliminate redundant overlap coverage: saves\n   $3,100/month, effective immediately. Confirmed compliant with the SLA-required minimum of\n   2 named on-call engineers covering every shift at all times.\nE. Sublease unused office floor space: saves $7,900/month, but requires landlord sign-off with\n   a mandatory 60-day notice period before the savings take effect.\n\nSequence which actions to take, and when, to reach the $18,000/month target within the\nquarter. Specifically evaluate option B: calculate the penalty cost of canceling it now versus\nthe value of capturing its savings 4 months earlier, and state whether canceling it now is a\nnet gain or a net loss compared to simply waiting for the penalty-free window -- and whether B\nis even needed to hit the $18,000/month target at all. Confirm the on-call SLA floor is\npreserved under D.\n", "b1.helpdesk-01": "You are the helpdesk lead for a 30-attorney law firm. Four tickets came in within the last\n30 minutes:\n\nTicket A -- Submitted by a name partner (flagged VIP in the ticketing system): \"Need my\nemail signature updated with the new firm logo.\"\nTicket B -- Submitted by an associate: \"Can't log into the court's e-filing portal. We have\na filing deadline with the court in 90 minutes on an active litigation matter.\"\nTicket C -- Submitted by a paralegal: \"My second monitor flickers on and off sometimes.\"\nTicket D -- Submitted by the office manager: \"The document management system (DMS) that\nholds every active case file is down for the entire firm -- all 30 attorneys are affected.\"\n\nYour standard SLA tiers: P1 = business-critical or an imminent legal/court deadline, 1-hour\nSLA. P2 = significant single-user impact, 4-hour SLA. P3 = minor or cosmetic, next-business-\nday. Triage all four tickets: give each one a priority tier, order them for handling, and\njustify each call using the actual business/legal impact described -- not who submitted it.\n", "b1.helpdesk-02": "A field technician at a remote drilling rig is locked out of their corporate laptop. Login\nrequires MFA via a push notification to an authenticator app, but the rig's only connectivity\nis a metered VSAT satellite link currently saturated by SCADA/drilling telemetry, so the push\nnotification never arrives. The technician's personal cell phone also has no signal at the\nsite, so SMS-based backup MFA won't work either. The technician needs access today to submit\na drilling report with a regulatory submission deadline. Your team's standard MFA-reset\nprocedure requires verifying the user's identity via a callback to their on-file cell number\n-- which is not possible here since there's no cell signal at the site. Describe the\nidentity-verification and account-recovery path you would use in this situation that doesn't\ndepend on SMS or push delivery, while still actually verifying it's the technician (not\ndisabling MFA for the account or issuing a shared/generic credential), and what you would\ndocument afterward.\n", "b1.helpdesk-03": "A clinic's ticket, \"Scheduling system won't load for front-desk staff,\" was submitted at\n8:02 AM and tagged P2 (4-hour SLA per your MSP's contract). The assigned tech picked it up at\n8:15 AM, tried one remote fix, then left a voicemail asking the clinic's office manager to\ncall back to confirm before doing anything further, and moved on to other tickets. No one\ncalled back. At 1:45 PM -- 5 hours 43 minutes after the ticket was created, 1 hour 43 minutes\npast the P2 SLA -- the clinic manager escalated, upset. In the meantime, front-desk staff had\nbeen manually logging patients on paper because the scheduling system was still down, and\nthose paper logs (containing patient names and appointment reasons) had been sitting openly\nat the front desk rather than being handled per the clinic's PHI-safeguard policy. Address\nthree things: (a) specifically what process failure caused the SLA breach -- not just \"the\ntech should have followed up faster,\" (b) the immediate steps to take right now for both the\nstill-open ticket and the paper-log PHI exposure, and (c) what should change in the workflow\nso a single unreturned callback doesn't silently blow through an SLA again.\n", "b1.helpdesk-04": "A regional bank's core-banking system needs a 90-minute planned maintenance window this\nSaturday, 2:00-3:30 AM ET -- the lowest-traffic period. During that window, online banking,\nthe mobile app, and debit card authorizations will all be unavailable; branches are closed at\nthat hour, so there is no teller-facing impact. For a bank, any customer-facing outage notice\nhas to stay factual and calm, and must not imply that account security has been compromised\n(wording that reads like a breach notice can itself trigger unnecessary customer panic).\nProduce two things: (1) the customer-facing communication -- a short website/app banner and a\none-paragraph push notification -- announcing the maintenance window, written so it reads as\nroutine and not alarming, and (2) a short internal Slack message to branch staff so they can\nreassure any customer who calls in during or right after the window, without repeating a full\nincident-style writeup.\n", "b1.helpdesk-05": "Convert this resolved ticket into a knowledge-base article for the rest of the helpdesk team.\n\nTicket summary: Handheld barcode scanners used in a poultry plant's freezer/cold-storage area\nrepeatedly dropped WiFi and failed to sync lot-tracking scans, forcing workers to re-scan\npallets and creating a risk of a gap in USDA lot-tracking coverage. Investigation: the\nfreezer-area WiFi access point was mounted on a metal support beam near the walk-in cooler\ndoor; signal degraded further whenever the door (with its metal-clad outer skin) was closed,\nand condensation had formed inside the AP's outdoor-rated enclosure from the cold. Fix\napplied: relocated the AP away from the metal beam and the door's swing path, and enabled\n2.4GHz band steering for that access point specifically, since 2.4GHz penetrates the metal/\ncold environment better than 5GHz at this location. No scan drops since the relocation.\n\nWrite the KB article using your team's standard structure -- Symptom, Root Cause, Resolution,\nPrevention -- and make sure Prevention covers what to check FIRST next time (a faster\ndiagnostic than immediately rolling a truck to physically relocate hardware again).\n", "b1.helpdesk-06": "An architecture firm's senior architect reports that the shared Revit central model (the\nmaster worksharing file that the project team links their local files to) won't open --\nRevit reports the central model file may be corrupted. Cause: last night, the helpdesk\nperformed a scheduled after-hours reboot of the file server at 11:40 PM without first\nchecking for active Revit worksharing sessions. Revit's sync logs show 3 team members still\nhad local sessions open with unsynced local changes at that moment. There's a client\npresentation with a design-development deadline in 26 hours. The file server's last\nsuccessful nightly backup completed at 10:00 PM -- 1 hour 40 minutes before the reboot -- so\nrestoring from that backup would lose only the 3 architects' changes made in that 1h40m\nwindow, nothing earlier. Nobody on the helpdesk team is trained in Revit central-model\nrecovery internals, but Autodesk and independent BIM-specialist consultants offer emergency\nsupport for exactly this kind of corruption. Decide and justify, in order: what to check\nbefore touching the corrupted central model at all, whether to restore from the 10:00 PM\nbackup immediately (and what that costs each of the 3 architects), and when/whether to\nescalate to Autodesk or a BIM specialist rather than have helpdesk attempt the repair itself.\n", "b1.helpdesk-07": "A county commissioner's county-issued laptop won't boot -- it shows a BitLocker recovery-key\nprompt, most likely triggered by firmware/TPM drift after the county's overnight BIOS update\npush. She is due to present the county's public, livestreamed annual budget hearing in 40\nminutes, from a presentation she finished editing on this laptop last night; the final version\nwas saved locally and never synced to OneDrive. She is a VIP (elected official) and is\nunderstandably anxious about the clock. The BitLocker recovery key for her device is escrowed\nin the county's Active Directory / Entra tenant and retrievable by the helpdesk. Give the\nimmediate step-by-step response, explain why the VIP pressure and the 40-minute clock should\nNOT change the order of the standard non-disruptive-first process (i.e., why reimaging the\nlaptop to \"just get her working fast\" would be the wrong move here), and describe a backup\npath you'd work in parallel in case the escrowed key doesn't resolve it in time.\n", "b1.helpdesk-08": "A contract research organization's remote clinical research associates (CRAs) upload case\nreport form data to a sponsor's clinical-trial portal over the company VPN. Over the last 6\nweeks, 11 separate tickets from 7 different CRAs all report the same thing: \"VPN disconnects\nmid-upload, I have to restart the upload.\" Past fixes, one per ticket, each treated as\nunrelated: told a user to reconnect and retry (worked temporarily, every time); once\nincreased the VPN client's idle-timeout setting for one specific user; once told a different\nuser to switch from WiFi to a wired connection at home, which seemed to help that one user.\nNo common cause was ever identified across the 11 tickets. Here is the pattern nobody had\nconnected yet: in all 11 cases the disconnect happened between 35 and 50 minutes into the VPN\nsession -- never earlier, never much later. The affected CRAs are on different ISPs,\ndifferent home networks, and different laptop hardware. The VPN concentrator's own connection\nlogs show these sessions ending with a code unrelated to idle-timeout, and the timing lines up\nclosely with one fact from the concentrator's configuration: its max-session /\nre-authentication interval is set to 45 minutes. State the actual root cause (not the\nper-ticket fixes already tried), explain why the idle-timeout change and the wired-connection\nsuggestion each appeared to help their one user even though neither addressed the real cause,\ngive the actual fix, and say how this should have been caught after the 2nd or 3rd similar\nticket instead of the 11th.\n", "b1.knowledge_mgmt-01": "Your MSP's helpdesk documentation lead handed you the following prose description of how\nnew front-desk and clinical staff get EHR system access at an outpatient clinic client, and\nasked you to convert it into a numbered checklist a brand-new helpdesk tech could follow\nunaided, in the correct order, without needing to ask anyone what to do next.\n\n\"When a new employee starts, HR sends us their name, role, and start date. Before we create\nanything, we need the clinic's practice manager to email formal written approval naming the\nspecific EHR access role -- front-desk scheduling-only, or clinical charting access --\nbecause we've had an incident where a front-desk hire was given clinician-level chart access\nby mistake, since someone assumed the access level from the job title alone instead of\ngetting it in writing. Once we have that written approval, we create the Active Directory\naccount, add the account to the correct EHR role group (never assign chart-level access to a\nscheduling-only role, even temporarily, even to save time), and enable MFA on the account\nbefore it is used for the first time. Finally, we log the account creation and a reference to\nthe approval email in the client's compliance folder, since this clinic is a HIPAA covered\nentity and gets audited on new-user access every year.\"\n\nConvert this into a numbered, testable checklist in the correct execution order. Preserve the\ntwo points in the prose where skipping a step or doing things out of order would be an actual\ncompliance problem, not just an inconvenience.\n", "b1.knowledge_mgmt-02": "Your MSP runs a weekly backup-verification process for a structural-engineering firm's\nproject file server, which stores stamped structural calculation packages and construction\ndrawings. Most state licensing boards require engineers to be able to produce these stamped\nrecords for a statute-of-repose period (commonly a decade or more after a project finishes)\nin case a professional-liability claim is filed years later -- so a silently failed backup\nhere isn't just an inconvenience, it can leave the firm unable to defend a claim long after\nthe project is closed out. Right now, verification is informal: whoever is free on Friday\nafternoon glances at a couple of recent filenames and calls it done.\n\nWrite a Standard Operating Procedure, as a numbered list, for the recurring weekly\nbackup-verification process. It must: confirm the backup job actually completed rather than\njust started, include a real restore-test of a sample file rather than only checking a\ncompletion log, and state exactly what to do if the same backup job fails verification two\nweeks in a row.\n", "b1.knowledge_mgmt-03": "Write a KB article for your MSP's helpdesk team titled \"Replacing a Lost Hardware Security\nKey for Trading-Floor Staff\" at a broker-dealer client. Context: traders authenticate to the\norder-management system (OMS) with a physical FIDO2 hardware security key; losing it locks\nthe trader out of the OMS entirely.\n\nTwo facts specific to this client:\n1. Compliance requires documented two-person identity verification -- the trader's desk\n   supervisor AND IT, both -- before any credential is reissued, because the firm's SEC/FINRA\n   recordkeeping obligations treat OMS access changes as an auditable event.\n2. A hardware-key reissuance can only happen immediately if the trader currently has zero\n   open orders working in the OMS. If they have open orders, the reissuance must wait until\n   after market close (4:00 PM ET) or before market open (9:30 AM ET), because interrupting\n   an OMS session that has open orders mid-session risks the order landing in an inconsistent\n   state.\n\nWrite the KB article with a Prerequisites section (what must be verified before you start),\nnumbered resolution steps, and at least one explicit failure branch covering what to do if a\nprerequisite is not met -- for example, the supervisor is unreachable, or the trader has open\norders during market hours.\n", "b1.knowledge_mgmt-04": "A retiring senior IT admin at a 60-attorney law firm left you these tribal-knowledge notes on\ntheir last day. Turn them into a proper onboarding document for the new IT support hire --\nnumbered steps or clear rules, each with a short reason attached so the new hire understands\nwhy the rule exists, not just what to do.\n\nNotes, as left:\n- \"Never create a new matter folder in iManage before Records confirms the conflicts check\n  has cleared. If you jump the gun and the conflict check later comes back positive, you've\n  already given the wrong people file access, and that's an ethics problem, not just an IT\n  mess to clean up.\"\n- \"Ethical walls: some clients are on the restricted list. When a request looks anywhere near\n  one of those, check with Records -- do not just guess from the matter name.\"\n- \"iManage access for a new matter always follows the matter team list from the intake form.\n  It does not follow whoever emails you asking to be added.\"\n- \"Partner password resets go through the partner's Executive Assistant, never straight to\n  the partner. Otherwise you'll eventually get a request that did not actually come from the\n  partner.\"\n\nWrite the onboarding document.\n", "b1.knowledge_mgmt-05": "Your MSP manages the file server for a USDA-inspected poultry processing plant with three\nproduction lines running in parallel. Right now, each line's barcode scanner writes\nlot-tracking scan logs into a single shared folder using a generic filename like\n\"lot_log.csv\", which gets overwritten every time a new lot starts on any line. A recent\ninternal audit also found that the plant's own lot-numbering scheme -- a running 4-digit\ncounter that resets to 0001 every quarter -- had produced the same lot number on two\ndifferent lines within the same quarter, meaning two physically different lots of poultry\nnow share an identical lot number in the retained records. That is exactly the kind of\nambiguity a USDA lot-tracking audit is designed to catch.\n\nPropose a file/folder naming and lot-ID taxonomy that makes every retained scan-log filename\nunique and self-describing without opening the file, and that eliminates the lot-number\ncollision across lines going forward. State what you do about the already-recorded,\ncurrently-ambiguous lot numbers from this quarter -- they cannot simply be renamed after the\nfact, because product has already shipped under those numbers.\n", "b1.knowledge_mgmt-06": "Below is the incident chat transcript from a county 911 dispatch center's CAD\n(computer-aided-dispatch) outage last month, now fully resolved. Turn it into a reusable\nrunbook for the next time this happens -- covering both the failover and the failback, as\nnumbered steps, with prerequisites and a failure/rollback branch for the one step in this\ntranscript that is easiest to get wrong.\n\n14:02 -- Dispatcher: Primary CAD (vendor-hosted) is unresponsive. Falling back to paper/radio\n  per COOP now.\n14:04 -- IT: Bringing up the on-prem backup dispatch console, BACKUP-CAD01, as our fallback\n  logging system.\n14:07 -- Dispatcher: BACKUP-CAD01 is up. Logging all new calls there directly since primary\n  is still down.\n14:09 -- IT: Confirmed, primary CAD vendor says they're aware, no ETA yet.\n16:35 -- IT: Vendor confirms primary CAD is restored and passing their health check.\n16:40 -- Dispatcher: Should we just cut back over to primary now?\n16:42 -- IT: Cutting back now -- new calls go to primary again as of 16:42.\n16:50 -- Dispatcher: Primary's fine, we're all back on it. Are we done?\n\nWrite the runbook. It should make explicit what has to happen to BACKUP-CAD01's data --\neverything logged there between 14:07 and 16:42 -- before that system is considered safe to\nleave idle again, and what you would have told the 16:50 dispatcher instead of \"yes, we're\ndone.\"\n", "b1.knowledge_mgmt-07": "Below is an existing KB article your MSP's compliance team found while cleaning up the\nknowledge base for a client (a regional retail chain that processes its own card payments\nin-store). Audit it for doc rot and say specifically what needs to change before this article\ncan be trusted again -- don't just say \"update it,\" name the actual stale elements.\n\n---\nKB-114: Quarterly PCI DSS External Vulnerability Scan Process\nLast updated: March 2019. Tags: pci, compliance, scanning.\n\nEvery quarter, log into the scanning portal and run an external scan against all Cardholder\nData Environment IP ranges, per PCI DSS v3.2.1's quarterly external-scan requirement (scans\nmust be run by an Approved Scanning Vendor). We use QualysGuard for this. Once the scan\nfinishes, export the PDF report and email it to compliance-distro@ourclient.com, cc:\njsmith@ourclient.com, since jsmith is our client contact and files it for the quarter. If the\nscan comes back with any \"High\" findings, that's fine as long as nothing is rated \"Critical\"\n-- just note it in the file and move on.\n---\n\nAudit this article. Call out: (a) anything that references a standard, version, or\nrequirement that is no longer current, (b) anything you cannot personally confirm is still\naccurate just from reading the article, and what you would check before relying on it, and\n(c) any instruction in the article that is not just stale but is actually the wrong thing to\ndo if followed today.\n", "b1.knowledge_mgmt-08": "Your MSP's leadership team met to decide on migrating all 40 client environments from your\ncurrent RMM platform (\"RMM-A\") to a new one (\"RMM-B\"), and the meeting notes below are all\nthat exist so far. Write this up as a proper decision record (ADR-style: Context, Decision,\nConsequences) that a future hire could read to understand not just what was decided but what\nhappens if it goes wrong.\n\nMeeting notes: \"RMM-A's per-endpoint pricing is getting expensive and it's missing the\npatch-approval workflows we keep needing. RMM-B has both. Plan: migrate client environments\nin phases over the next 90 days, starting with our smallest clients first. RMM-A auto-renews\nannually; the current term renews in 60 days unless we send written cancellation at least 30\ndays before the renewal date. Everyone in the room agreed: let's do it, send the RMM-A\ncancellation notice, and start the phased migration.\"\n\nWrite the ADR. It needs to explicitly deal with the timing conflict between the 90-day\nmigration and the 30-day cancellation deadline, and state what happens to the clients not\nyet migrated if something goes wrong with RMM-B after RMM-A has already been cancelled.\n", "b1.legal_compliance-01": "You support the compliance function for a small e-commerce retailer building its first\nrecords-retention schedule. Company policy -- informed by general recordkeeping practice, not\nany specific statute you should cite -- sets these retention floors:\n\n1. Signed customer service contracts: retain 3 years past the contract's end date.\n2. Accounts payable/receivable and general-ledger records: retain 7 years, the company's\n   internal floor for audit-support purposes.\n3. Marketing email opt-in/consent records: retain for as long as the contact remains subscribed,\n   plus 2 years after unsubscribe or last contact.\n4. Vendor W-9 / tax-ID forms: retain 4 years after the business relationship ends.\n\nOne additional fact: on March 2, 2026, the company's outside counsel issued a litigation-hold\nnotice covering all correspondence and invoices with Vendor Greenline Supply Co. from 2023 to\npresent, in connection with a pending contract dispute. This hold suspends normal\nretention/destruction schedules for those specific records until counsel lifts it.\n\nBuild a simple retention schedule (category, retention floor, note on the litigation hold where\nit applies), and flag anything that should NOT be destroyed on the normal schedule right now.\n", "b1.legal_compliance-02": "Your client is a billing-services vendor that processes claims data on behalf of a regional\nclinic network, making it a HIPAA \"business associate\" handling protected health information\n(PHI) on the clinic's behalf. Your client's compliance checklist requires every business-\nassociate-facing subcontractor DPA to include, at minimum:\n\n1. A definition of PHI/protected data and the permitted uses of it.\n2. A subprocessor flow-down clause: no further subcontracting of PHI processing without written\n   consent.\n3. A security-incident/breach notification clause with a concrete notification window of no\n   more than 24 hours after the subcontractor discovers an incident.\n4. Data return or certified destruction of all PHI within a stated period after contract\n   termination.\n5. Audit/inspection rights allowing your client to verify the subcontractor's safeguards.\n6. Indemnification for losses caused by the subcontractor's own security failures.\n\nA new subcontractor (a cloud storage vendor) sent this DPA excerpt, Section 4:\n\"Subcontractor will implement reasonable administrative, technical, and physical safeguards for\nClient Data. Subcontractor will notify Client of any security incident affecting Client Data in\na timely manner. Upon termination, Subcontractor will delete or return all Client Data within\n60 days. Subcontractor shall indemnify Client for direct losses arising from Subcontractor's\nbreach of its safeguard obligations. This Agreement may not be subcontracted without Client's\nprior written consent.\"\n\nCompare Section 4 against the six-item checklist. Identify which items are satisfied, which are\nmissing or inadequate, and why the breach-notification language in particular falls short.\n", "b1.legal_compliance-03": "Your client is a regional credit union. On July 1, IT discovered that a misconfigured export\njob had exposed a database extract to an unauthorized third party. The extract contained names,\npartial account numbers, and partial SSNs for approximately 1,200 members. Account numbers in\nthe extract were field-level encrypted; names and partial SSNs in the same extract were not.\n\nThe credit union's outside counsel has summarized the applicable state breach-notification law\n(paraphrased, not the statute text itself) as follows: notification is triggered when\nunencrypted personal information -- defined to include name combined with SSN or account\nnumber -- is reasonably believed to have been acquired by an unauthorized person; affected\nresidents must be notified without unreasonable delay and no later than 30 days after\ndiscovery; the state Attorney General must also be notified if the incident affects 500 or more\nresidents; and there is a safe harbor from notification if ALL of the personal information\ninvolved was encrypted using a method meeting an industry-standard threshold.\n\nGeneral background, not case-specific: credit unions are also generally subject to federal\nsafeguarding-of-customer-information obligations under GLBA, separate from any state breach-\nnotification analysis.\n\nTriage this incident: does it trigger notification, who must be notified, by what date (working\nfrom the July 1 discovery date), and how does the mixed encrypted/unencrypted nature of the\nextract affect whether the safe harbor applies?\n", "b1.legal_compliance-04": "A mid-size ag-equipment manufacturer wants an Acceptable Use Policy (AUP) covering shop-floor\ntablets and corporate laptops. Draft the AUP to these stated constraints:\n\n1. Reasonable personal use of corporate devices is permitted, but the company reserves the\n   right to monitor device and network activity.\n2. Prohibited uses must include: opening personal email attachments on devices connected to the\n   operational-technology (OT) / industrial-control-systems (ICS) network, and connecting\n   unapproved personal USB drives to production-line PCs.\n3. Employees must receive clear disclosure that monitoring occurs and must sign an\n   acknowledgment before device issuance.\n4. Consequences for violations tied to safety-critical OT systems must be spelled out, up to\n   and including termination.\n5. The policy's monitoring and consequences language must not be worded in a way that could be\n   read as prohibiting employees from discussing wages, hours, or working conditions with each\n   other -- that kind of discussion is generally protected under federal labor law and should be\n   carved out explicitly rather than left ambiguous.\n\nDraft the AUP sections addressing these five points, and close with a note on what should happen\nbefore rollout.\n", "b1.legal_compliance-05": "A county agency just completed a compliance audit. The findings:\n\n1. 14 workstations were found with local administrator rights beyond IT staff, violating the\n   agency's least-privilege policy.\n2. The records-management log shows 3 categories of public records were destroyed in the past\n   quarter without following the agency's required destruction-approval workflow (no sign-off\n   on file).\n3. The vendor contract for cloud backup storage lacks a data-residency clause, which agency\n   policy requires for any records containing constituent personally identifiable information\n   (PII).\n4. The incident-response plan has not been tabletop-tested in over 2 years; policy requires an\n   annual test.\n\nBuild a remediation response plan: for each finding, name an owner, the remediation action, and\na target closure date, prioritized by risk. Flag which finding(s) need review by the agency's\nlegal counsel before the finding can be closed out, and explain why.\n", "b1.legal_compliance-06": "You are supporting an architecture/engineering firm negotiating a new IT-managed-services\ncontract. The vendor's draft contains this liability structure:\n\n\"Section 8.1 (Indemnification): Vendor shall indemnify, defend, and hold harmless Client from\nany third-party claims arising out of Vendor's gross negligence or willful misconduct in\nperforming the Services.\n\nSection 8.2 (Limitation of Liability): Except for Vendor's indemnification obligations under\nSection 8.1, in no event shall either party's aggregate liability under this Agreement exceed\nthe fees paid in the twelve (12) months preceding the claim. Notwithstanding the foregoing, this\nlimitation shall not apply to claims arising from a party's breach of Section 6\n(Confidentiality), Section 9 (Data Protection), or a party's indemnification obligations under\nSection 8.1.\"\n\nAt first read, this looks favorable to the client: the liability cap has broad carve-outs for\nconfidentiality, data protection, and indemnification claims, which sounds like strong,\nlargely-uncapped protection.\n\nReview Sections 8.1 and 8.2 together and assess whether that first read holds up. Specifically:\nif the vendor causes a data breach through ordinary negligence (not gross negligence or willful\nmisconduct) while performing the Services, would that claim actually fall under the\nindemnification carve-out and be uncapped, or would it fall under the ordinary 12-month-fees\ncap? Propose a redline to close any gap you find, and flag this point for counsel review given\nthe contract's value.\n", "b1.legal_compliance-07": "Your client, an oilfield-services company, is comparing NDA drafts from two potential\njoint-venture partners for a pipeline-monitoring data-sharing pilot involving the client's\nproprietary monitoring methodology.\n\nNDA A, Section 3 (Exclusions): \"Confidential Information shall not include information that (i)\nis or becomes publicly available through no fault of Receiving Party, (ii) was rightfully known\nby Receiving Party prior to disclosure, (iii) is independently developed by Receiving Party\nwithout use of or reference to the Confidential Information, or (iv) is rightfully obtained from\na third party without breach of any confidentiality obligation.\"\nNDA A, Section 5 (Term): \"This Agreement shall survive for a period of three (3) years from the\nEffective Date, after which Receiving Party's obligations hereunder shall terminate.\"\n\nNDA B, Section 3 (Exclusions): the same four exclusions as NDA A, plus a fifth: \"(v) is retained\nin the unaided mental impressions, memory, or recollection of Receiving Party's personnel who\nhad access to the Confidential Information (Residuals), and Receiving Party shall have no\nobligation to account for or limit its use of Residuals, provided such personnel do not\nintentionally memorize Confidential Information for the purpose of avoiding their\nconfidentiality obligations.\"\nNDA B, Section 5 (Term): \"This Agreement shall survive for a period of three (3) years from the\nEffective Date.\"\n\nCompare the two drafts. Identify the substantive difference, assess which one poses greater risk\nto the client's proprietary methodology, and recommend a course of action.\n", "b1.legal_compliance-08": "Your MSP client is a small boutique law firm. The firm's (non-lawyer) office manager emails you\nwith two questions in the same message:\n\n\"First -- we're moving a closed client's paper and electronic files to our new document\nmanagement system. What's the right way to handle that transfer securely and keep a proper\nrecord of it?\n\nSecond, separate issue -- we have a client, [Client Name], who's about 90 days behind on\ninvoices. Our engagement letter with them doesn't say anything about withdrawal for nonpayment.\nCan we just tell them we're terminating the engagement effective immediately, no notice, since\nthe letter is silent on it? We're worried this client might sue us over the fee dispute, so\nlet's keep this email thread just between us for now.\"\n\nRespond to the office manager. Address the file-transfer question directly. For the second\nquestion, draw a clear line between what you can answer as general information and what\nrequires the firm's own licensed counsel, and explain why engagement termination/withdrawal is\nin that second category. Also address the \"keep this between us\" request given what it implies.\n", "b1.data_analytics-01": "You're the analyst for a lab-supply company that sells reagent-kit subscriptions to\nuniversity and biotech research labs. Leadership wants a cohort dollar-retention read from\nthe following signup-cohort table (all figures are Monthly Recurring Revenue, \"MRR\"):\n\nCohort Jan-2026 -- 40 customers. Month 1 MRR (signup month): $20,000. Month 2 MRR retained:\n$17,000. Month 3 MRR retained: $15,000.\n\nCohort Feb-2026 -- 50 customers. Month 1 MRR (signup month): $25,000. Month 2 MRR retained:\n$21,250. (Month 3 has not happened yet for this cohort -- it is only 2 months old.)\n\nCohort Mar-2026 -- 35 customers. Month 1 MRR (signup month): $17,500. (No Month 2 figure\nexists yet -- this cohort is only 1 month old.)\n\nCompute the Month-2 net dollar retention rate for every cohort where it can actually be\ncomputed, and the Month-3 net dollar retention rate for the Jan cohort. Compute the absolute\ndollar churn (not just the percentage) for the Jan and Feb cohorts at Month 2, and state which\nof the two lost more revenue in absolute dollars. Explain why the Feb cohort has no Month-3\nfigure and the Mar cohort has no Month-2 figure -- do not invent numbers to fill the gap -- and\nexplain why blending all three cohorts into one \"average retention\" number right now would be\nmisleading given they are not the same age.\n", "b1.data_analytics-02": "Your MSP's internal ops dashboard shows a weekly help-desk ticket-volume line chart that\nleadership is pointing to in a staffing-budget meeting, saying \"ticket volume is exploding --\nwe need to hire two more techs immediately.\" The chart's y-axis is drawn starting at 380\n(not 0) and topping out at 450, and it only shows the last 6 weeks. The underlying weekly\nticket counts, read off the dashboard's data table, are:\n\nWeek 1: 410. Week 2: 415. Week 3: 420. Week 4: 428. Week 5: 433. Week 6: 441.\n\nCompute the actual percentage change in ticket volume from Week 1 to Week 6. Explain\nspecifically why drawing the y-axis starting at 380 instead of 0 exaggerates how steep that\nchange looks on screen. State what the chart's 450-unit axis top and 380 axis bottom compress\nthe visual range to, and recommend how you would redraw the chart so it does not visually\nmislead the room. Do not recommend the hiring decision based on the \"exploding\" framing without\nfirst noting the corrected, modest percentage change.\n", "b1.data_analytics-03": "You're building a KPI tree for an ag-equipment distributor's new BI dashboard, rooted at\nquarterly Revenue and decomposed down to levers the sales and marketing teams actually\ncontrol. Current quarter actuals:\n\n- Units Sold: 350 tractors/implements.\n- Average Selling Price (ASP): $12,000/unit.\n- Revenue = Units Sold x ASP.\n- Units Sold is itself produced by: Leads (2,800) x Lead-to-Quote Rate (25%) x\n  Quote-to-Close Rate (50%).\n\nBuild the KPI tree (Revenue at the root, Units Sold and ASP as its direct children, then\nLeads / Lead-to-Quote Rate / Quote-to-Close Rate as children of Units Sold), and verify the\ntree's numbers actually reconcile up to the stated Revenue. Label which KPIs are directly\ncontrollable by the sales/marketing team versus mostly driven by external market conditions.\nThen compute the dollar revenue impact of a 10% improvement in ASP alone, and separately the\ndollar revenue impact of a 10% improvement in Leads alone (holding the other levers fixed).\nState which lever produces the bigger revenue impact, or whether they're the same, and explain\nwhy -- and recommend how leadership should actually prioritize between levers given what you\nfound (hint: revenue impact size is not the only thing that should drive prioritization).\n", "b1.data_analytics-04": "A fintech lending SaaS product's Finance team and Product team walked into the June board\nmeeting with two different churn numbers for the same month, and the board wants a\nreconciliation, not a re-argument. The account activity for June:\n\n- Active accounts at June 1: 500.\n- 20 accounts fully cancelled (account closed/deleted) during June.\n- 8 accounts downgraded from a paid plan to the $0 free tier during June (still logged in and\n  actively using the product, but billing $0).\n- 5 accounts went on a contractual billing pause during June (a pause clause in their\n  contract suspends billing for up to 60 days with an automatic resume -- they are not\n  billed in June but are still under contract and will resume paying).\n\nFinance's churn definition: \"Customer Churn Rate\" = accounts with zero billed revenue at\nmonth end / accounts active at month start. Product's churn definition: \"Logo Churn Rate\" =\naccounts fully cancelled / accounts active at month start (Product excludes downgrades,\nsince those users are still actively using the product, and excludes contractual pauses,\nsince those customers have not left).\n\nCompute Finance's Customer Churn Rate and Product's Logo Churn Rate as each team currently\ndefines them. Determine whether one team is simply wrong, or whether this is a\nmetric-definition mismatch rather than a calculation error -- and say which. Then recommend a\nreconciliation: should the 5 contractually-paused accounts count as churned under EITHER\ndefinition? Recompute Finance's rate with the paused accounts correctly excluded, and state\nthe final set of churn numbers the board should see, each clearly labeled by what it measures.\n", "b1.data_analytics-05": "A city's Department of Permitting ran an A/B test on two versions of an email reminder sent\nto applicants with an incomplete permit application, measuring \"completion rate\" (recipient\nfinishes and resubmits within 7 days of the email).\n\nVersion A (control, plain-text reminder): sent to 240 recipients, 42 completed within 7 days.\nVersion B (adds a countdown-to-deadline banner and a direct resume link): sent to 235\nrecipients, 51 completed within 7 days.\n\nA staffer's draft summary for the department director says: \"Version B lifts completion by\n24% -- let's roll it out to everyone immediately.\" Compute the completion rate for each\nversion and the point-to-point lift. Assess whether a difference of this size, at these sample\nsizes (roughly 40-50 completions per arm), is large enough to be confident it reflects a real\neffect of the new email design rather than normal week-to-week noise in a modest sample.\nState what you would need (larger sample, longer run, formal significance test) before\nrecommending a full rollout, and what you would do in the meantime given Version B costs\nnothing extra to keep running.\n", "b1.data_analytics-06": "You're the analyst for a general contractor. Write ANSI-standard, PostgreSQL-compatible SQL\nagainst the following schema (types shown for clarity):\n\n```sql\nCREATE TABLE projects (\n  project_id      INT PRIMARY KEY,\n  project_name    TEXT,\n  contract_value  NUMERIC\n);\n\nCREATE TABLE change_orders (\n  co_id       INT PRIMARY KEY,\n  project_id  INT REFERENCES projects(project_id),\n  co_amount   NUMERIC\n);\n\nCREATE TABLE invoices (\n  invoice_id      INT PRIMARY KEY,\n  project_id      INT REFERENCES projects(project_id),\n  invoice_amount  NUMERIC\n);\n```\n\nEach project can have MANY change_orders rows and, independently, MANY invoices rows (both\nare one-to-many off of projects; change_orders and invoices have no direct relationship to\neach other). For project_id 101 (\"Riverside Office Park\"), the data is:\n\nchange_orders: CO-1 $50,000, CO-2 $30,000, CO-3 $20,000 (3 rows, true total $100,000).\ninvoices: INV-1 $500,000, INV-2 $500,000, INV-3 $500,000, INV-4 $300,000 (4 rows, true total\n$1,800,000).\n\nWrite a single query that returns, per project, the total change-order amount and the total\ninvoiced amount, both correct, in one result set. Do NOT join projects to change_orders and\ninvoices directly in the same query and then SUM both amount columns -- explain specifically\nwhat goes wrong numerically if you do that for project 101 (show the wrong totals it would\nproduce and why), and show the correct query instead. State the general rule for when two\none-to-many child tables must be aggregated before being joined together.\n", "b1.data_analytics-07": "You're auditing a law firm's nightly ETL pipeline that loads attorney time entries from the\npractice-management system into a `time_entries_fact` reporting table. Four issues have\nsurfaced:\n\n1. Duplicate ingestion: the nightly job re-pulls the full trailing 24 hours with no de-dup\n   key, and after an on-call retry two nights ago, 340 time-entry rows were ingested TWICE\n   (identical source timestamps). Duplicated rows average 0.6 hours each, at a blended\n   $285/hour billing rate.\n\n2. Orphaned foreign keys: 85 time-entry rows reference a `matter_id` that no longer exists in\n   the `matters` dimension table (the matter was closed/purged before the entry synced).\n   These rows silently vanish from any report that INNER JOINs `time_entries_fact` to\n   `matters`, even though they still exist in the fact table itself. Orphaned rows average\n   1.2 hours each.\n\n3. NULL handling: 460 time-entry rows have a NULL `rate_type` (should be \"standard\" or\n   \"contingency\"). The standard hourly-realization report filters `WHERE rate_type =\n   'standard'`, which silently excludes all 460 NULL rows rather than raising any error or\n   warning.\n\n4. Timezone mismatch: entries are timestamped in the source system's local time (US/Eastern)\n   but loaded into the warehouse as if they were already UTC, with no conversion applied --\n   shifting each entry's stored \"billing date\" by several hours, which can push late-evening\n   entries onto the wrong calendar day in day-level reports, particularly near billing-period\n   cutoffs.\n\nRank the four issues by financial/reporting risk. Quantify the dollar impact of issue 1\n(duplicate ingestion) and the hours silently dropped from matter-level reporting by issue 2\n(orphaned matter_id). Explain specifically WHY the NULL rate_type rows are silently excluded\nrather than erroring (the underlying SQL semantics), not just that they are excluded. Give a\nconcrete pipeline fix for each of the four issues.\n", "b1.data_analytics-08": "An oilfield-services company's average realized price per barrel-of-oil-equivalent (BOE) sold\nrose from $60.00/BOE in Q1 to $64.00/BOE in Q2. The Slack chatter among leadership is \"the\nmarket must finally be paying us more for our product.\" You have the underlying data:\n\nBenchmark (market) price, WTI-linked index: Q1 average $61.00, Q2 average $61.20 -- essentially\nflat quarter over quarter.\n\nProduct-level volume and per-unit realized price (both products' own per-unit prices are\nUNCHANGED between Q1 and Q2):\n- Crude oil: Q1 volume 4,000 BOE/d @ $70/BOE. Q2 volume 4,800 BOE/d @ $70/BOE (same price).\n- NGLs (natural gas liquids): Q1 volume 2,000 BOE/d @ $40/BOE. Q2 volume 1,200 BOE/d @ $40/BOE\n  (same price).\n- Total volume: 6,000 BOE/d in both Q1 and Q2 (unchanged).\n\nFirst, check the leadership theory against the benchmark data -- is \"the market is paying more\"\nconsistent with what the benchmark actually did? Lay out your investigation plan: what you'd\ncheck first (product mix, then each product's own per-unit price, then total volume), and what\nyou find at each step. Compute the Q1 and Q2 blended $/BOE from the volume and price data given\nand confirm they match the $60.00 -> $64.00 figures. Determine how much of the $4.00/BOE\nincrease is explained by a shift in product mix versus an actual per-product price/rate change,\nand state your conclusion about whether the \"better pricing\" narrative is correct.\n", "b1.project_mgmt-01": "You're kicking off a project to roll out a new point-of-sale (POS) system across all 18\nstores of a regional retail chain. Constraints: a 10-week project window, a $180,000 budget,\na 4-person team (1 PM, 2 implementation engineers, 1 trainer), a hard company freeze on any\nnew store deployments during the final 2 weeks before Black Friday (which falls at the very\nend of week 10), and an operations requirement that no more than 3 stores can be down for\ncutover at the same time (to protect regional coverage).\n\nWrite a kickoff plan: charter basics (objective, in-scope, explicitly out-of-scope), a phased\nrollout approach that respects both the \"\u22643 stores at once\" limit and the Black-Friday freeze,\nkey roles, and the top 2-3 kickoff risks with an owner for each. Show your math for how many\nrollout waves are required given 18 stores and the 3-store limit, and how many weeks are\nactually usable for deployment once the freeze window is excluded from the 10-week window.\n", "b1.project_mgmt-02": "A hospital is preparing to launch a new patient-portal product and needs a dependency map\nacross six workstreams before go-live:\n\nT1 -- Vendor contract signature. No dependency; must happen first.\nT2 -- HIPAA security risk assessment of the vendor's system. Depends on T1 (the contract must\nbe signed before the vendor's system can be formally assessed).\nT3 -- Clinical staff training content build. Depends on T1 (needs the contracted product to\nbuild training material against).\nT4 -- Integration with the hospital's EHR system. Depends on T2 (cannot connect a system\nhandling PHI to the EHR until the security risk assessment clears it).\nT5 -- Compliance sign-off / go-live approval. Depends on T2 AND T4 (compliance needs both the\ncleared risk assessment and a working integration before approving go-live).\nT6 -- Staff training delivery. Depends on T3 AND T4 (delivery needs both the built content\nAND the live integration to train staff on).\nGo-live depends on T5 AND T6.\n\nMap the dependency order. Identify which tasks can run in PARALLEL with each other. Identify\nthe single task that is a blocking prerequisite for the most downstream work, and explain\nspecifically why rushing or skipping that task would be the highest-risk shortcut available,\neven though it is not the last task before go-live.\n", "b1.project_mgmt-03": "You're the PM for your MSP's own internal project: migrating the internal ticketing/PSA\nplatform to a new vendor. Facts as of this week's status report:\n\n- Planned go-live: Aug 15, 2026.\n- Data migration workstream: 92% complete, on track, no open issues.\n- Integration testing workstream: BLOCKED. The third-party API vendor promised sandbox\n  credentials \"by end of last week\"; that promise is now 6 business days overdue with no new\n  ETA from the vendor.\n- Staff training workstream: not started; scheduled to start Aug 4 (11 days before go-live).\n  Training cannot start until integration testing is complete, because training uses the live\n  integration sandbox.\n- Budget: $42,000 spent of $65,000 approved, tracking to plan.\n- Team capacity: fully staffed, no attrition risk.\n\nWrite this week's RAG (Red/Amber/Green) status report, per workstream and overall. Give the\nhonest overall call, not the most comfortable one -- three of four areas look fine on their\nown, but state clearly whether the blocked integration-testing workstream puts the Aug 15\ngo-live at real risk, and why, tying your reasoning to the training workstream's dependency on\nit and its 11-day runway requirement. Recommend a specific escalation action rather than\n\"monitor and wait.\"\n", "b1.project_mgmt-04": "Your structural engineering firm has exactly one engineer, Priya, licensed to stamp drawings\nin this state, and she is double-booked this week across two active projects:\n\nProject Riverside (client-deadline-driven): needs Priya for 24 hours this week to review and\nstamp final structural drawings. The city submittal deadline is this Friday, tied to a permit\napplication window that only opens periodically -- missing this window delays the whole\nproject 6 weeks until the next window opens.\n\nProject Harborview (internal, flexible): needs Priya for 16 hours this week for a mid-design\nstructural review. There is no external deadline this week; the next natural checkpoint is 3\nweeks out, and this specific review has 2 weeks of schedule float before it would affect\nHarborview's overall timeline.\n\nPriya has 40 available hours this week on paper, but roughly 4 hours/week are unavoidably\nconsumed by meetings and admin, leaving fewer productive hours than the raw 40.\n\nResolve the conflict: state which project gets priority this week and why, quantify Priya's\nactual productive capacity after overhead, determine whether Riverside's full 24-hour need\nfits inside that productive capacity, and state how much (if any) of Harborview's 16 hours can\nstill happen this week versus should be deferred into its 2-week float. State what happens if\nRiverside is deprioritized instead.\n", "b1.project_mgmt-05": "You're planning a 5-day scheduled turnaround (maintenance shutdown) at a midstream\ngas-processing plant. Budget: $1.2M. Hard constraint: the plant must restart by Day 6 morning,\nbecause a downstream customer delivery contract carries a $40,000/day penalty for every day\nthe plant is offline beyond Day 5.\n\nKnown risk factors:\n- A critical replacement compressor seal is on backorder; based on this vendor's history with\n  this plant, the promised ship date has slipped by an average of 2 days on each of the last 3\n  orders.\n- The specialty pressure-vessel welding contractor has only 1 certified crew available this\n  week (no backup crew available on short notice), and this scope of pressure-vessel welding\n  has historically run 8-14 hours over its scheduled time about 1 in 3 turnarounds.\n- The weather forecast shows a 40% chance of a high-wind advisory on Day 3, which would halt\n  all crane-lift work (required for the compressor swap) for that day.\n\nBuild a risk register: for each risk, give a description, likelihood, impact (tie impact to\nthe $40,000/day penalty where relevant), and a mitigation with a named owner. Identify the\nsingle risk that most threatens the Day-6 restart if it materializes, and state the dollar\nexposure if the turnaround finishes 2 days late.\n", "b1.project_mgmt-06": "You're doing a schedule risk assessment for installing a new grain-processing line. Find the\ncritical path yourself from the task table below -- do not take anyone's word for which tasks\nare \"obviously\" critical. All durations are in working days.\n\nTask | Description | Duration | Predecessors\nT1 | Site prep | 5 | none\nT2 | Electrical rough-in | 4 | T1\nT3 | Equipment procurement (vendor lead time -- order placed Day 0) | 20 | none\nT4 | Foundation / concrete pad pour | 6 | T1\nT5 | Equipment installation | 8 | T2, T3, T4\nT6 | Equipment commissioning/testing | 5 | T5\nT7 | Operator training | 3 | T5\nT8 | Go-live (milestone) | 0 | T6, T7\n\nCompute the earliest start and earliest finish for every task, then the latest start and\nlatest finish, then the float for every task. State the total project duration. List the\ncritical-path task IDs in order. Explain, with the float numbers, why the critical path runs\nthrough T3 (equipment procurement) rather than through the construction chain (T1-T2/T4-T5)\nthat most people would assume is critical because it's the visible on-site work. Identify\nwhich non-critical task has the LEAST float and is therefore the biggest hidden schedule risk\nif its estimate proves optimistic.\n", "b1.project_mgmt-07": "A biotech is building out a new assay-validation lab. The BASELINE schedule (working days,\nactivity-on-node) is:\n\nTask | Description | Duration | Predecessors\nS1 | Equipment installation | 10 | none\nS2 | Utility/HVAC certification | 15 | none\nS3 | Equipment calibration | 4 | S1\nS4 | IQ (Installation Qualification) documentation | 3 | S3\nS5 | OQ (Operational Qualification) testing | 6 | S4, S2\nS6 | PQ (Performance Qualification) run | 5 | S5\nS7 | QA sign-off / lab go-live | 2 | S6\n\nCompute the baseline critical path and total duration.\n\nSCOPE CHANGE: the quality unit now requires an additional Environmental Monitoring\nQualification step, \"EMQ,\" lasting 15 working days (per the facility's standard environmental\nmonitoring SOP, which requires a minimum continuous 15-day particle-count cycle to establish a\nstatistically valid baseline -- this is the basis for the 15-day estimate; do not substitute a\ndifferent number). EMQ can only start once S2 (HVAC certification) is complete, and S5 (OQ\ntesting) now cannot start until BOTH S4 and EMQ are complete (in addition to S2).\n\nRecompute the full schedule with EMQ added. State the new total project duration and the\nschedule impact in days versus baseline. List the new critical-path task IDs. Explain\nspecifically what happens to the OLD baseline critical path (S1-S3-S4) now -- is it still\ncritical, and if not, how much float does it now have? State the estimate basis for EMQ's\nduration as given. Recommend one concrete way to recover schedule, or explain why the delay is\na hard floor that cannot be compressed.\n", "b1.project_mgmt-08": "A community bank's core-banking system upgrade project has a regulator-mandated cutover\ndeadline of Sept 30, 2026, tied to a consent order from a prior exam finding -- this is not a\nsoft internal target. Facts:\n\n- Original 16-week plan started June 1, 2026, giving a planned completion of Sept 21, 2026\n  (9 business days of schedule buffer before the Sept 30 hard deadline).\n- Data-conversion testing (a critical-path task) uncovered a defect requiring a vendor patch.\n  The vendor's committed patch delivery is 9 business days from today, which pushes the\n  data-conversion testing task itself 9 business days later than planned.\n- The remaining downstream tasks after data-conversion testing (user acceptance testing, staff\n  training, a mandatory 5-day parallel-run week, and go-live) total 5 weeks and cannot be\n  compressed below 4 weeks without dropping the parallel-run week -- which is a specific\n  condition of the consent order, not a task the bank can choose to cut to save time.\n\nWrite the stakeholder communication to the executive sponsor and the compliance officer. Give\nthe honest RAG status and say explicitly why: a 9-business-day slip against a 9-business-day\nbuffer consumes the ENTIRE buffer, meaning the deadline is only still theoretically achievable\nif every remaining task goes perfectly with zero further slippage -- which is a poor\nassumption given the project has already slipped once. State the specific escalation ask (not\n\"monitor and wait\"). State explicitly that the parallel-run week cannot be cut to buy back\nschedule because it is a consent-order condition, not a discretionary task. State what you\nwould tell the regulator/examiner today if asked, and why proactive disclosure is safer than a\nsurprise miss.\n", "b1.hr_people_ops-01": "A small retail-services business just hired its first-ever operations coordinator, starting in\n2 weeks. The hiring manager wants a plan covering:\n\n1. Pre-boarding paperwork, including federal employment-eligibility verification (Form I-9),\n   which generally must be completed within 3 business days of the employee's start date.\n2. Systems and access provisioning (laptop, email, scheduling software) ready on day one.\n3. A first-week schedule and a buddy assignment.\n4. A 30-60-90 day outline of ramp-up goals.\n\nBuild the onboarding plan covering these four points. Note briefly whether anything about this\nrole's pay classification (exempt vs. non-exempt) should be double-checked against actual job\nduties before finalizing the pay-related paperwork, rather than assumed from the job title.\n", "b1.hr_people_ops-02": "An employee at an ag-equipment manufacturer emails HR:\n\n\"I have 8 PTO days left as of December 31 -- do I lose any of them, or does it all roll over\nautomatically since nobody told me otherwise? Also, I work out of the satellite office, not\nheadquarters, if that matters.\"\n\nThe employee handbook, Section 4.3 (Paid Time Off), states: \"Full-time employees accrue PTO at a\nrate of 1.25 days per month (15 days/year). Up to 5 unused PTO days may be carried over into the\nnext calendar year; any balance above 5 days as of December 31 is forfeited, except where\ncarryover in excess of this limit is required by applicable state law.\"\n\nAnswer the employee using Section 4.3: state exactly how many of the 8 days carry over and how\nmany are forfeited under the general policy, and address why the satellite-office detail matters\ngiven the clause's state-law exception.\n", "b1.hr_people_ops-03": "A regional bank completed a market comp study and reclassified the \"Loan Processor\" role into a\nnew pay band of $52,000-$64,000. A loan processor's manager needs to deliver this news to an\nemployee currently paid $58,500 -- already within the new band, so there's no pay change.\n\nContext the manager should expect: a coworker in the same role recently mentioned, in a casual\nconversation, that they're paid $61,000. The employee is likely to ask why their pay didn't\nchange if the band changed, and may bring up the coworker's number.\n\nDraft the manager's talking points for this conversation. Address how to respond if the employee\nraises the coworker's pay -- employees discussing their own pay with each other is generally\nprotected activity, so the manager should not discourage or penalize that -- and specify what the\nmanager should NOT commit to unilaterally in this conversation (e.g., a raise), instead routing\nany adjustment question to compensation/HR leadership.\n", "b1.hr_people_ops-04": "A structural-engineering firm's project manager has a CAD drafter with documented performance\nissues over the past 90 days. Three prior written check-in notes are already on file:\n\n- Week 3: missed the deadline for the Meridian Tower drawing package by 4 days.\n- Week 6: QA flagged 4 drawing-revision errors in a single deliverable that should have been\n  caught before submission.\n- Week 9: a client contact emailed a complaint about slow response times on RFIs (requests for\n  information).\n\nThe manager wants to move to a formal Performance Improvement Plan (PIP) rather than further\ninformal check-ins. Build a 30-60-90 day PIP with specific, measurable goals tied to the three\ndocumented issues above (deadline adherence, QA error rate, RFI response-time), and state what\nshould happen at each checkpoint. Note how the PIP should reference the prior documented\ncheck-ins, and what should happen if a protected leave or accommodation request comes up during\nthe PIP period.\n", "b1.hr_people_ops-05": "A midstream services company is closing one field office due to a lost contract, effective in\n45 days. The closure affects 32 employees at that single site; total company headcount is 210\nemployees across 3 locations.\n\nGeneral background, not case-specific: WARN-type federal and state laws can require covered\nemployers to give affected employees written notice -- often generally understood to be around\n60 days -- before a qualifying mass layoff or plant closing; exact coverage thresholds and notice\nrequirements are jurisdiction- and fact-specific.\n\nBuild the layoff plan: (1) the employee communication/talking points for the affected 32\nemployees, (2) an explicit flag on the WARN-notice timing given that 45 days is less than the\ngeneral 60-day figure above, and what should happen about that gap immediately, and (3) standard\nelements to include: severance, benefits continuation, references, and outplacement support.\n", "b1.hr_people_ops-06": "A law firm's office manager emails you wanting to terminate a paralegal \"today, no notice,\" for\nwhat they describe as \"attitude problems and just not being a good fit anymore\" over the past 2\nmonths. The personnel file contains only the original offer letter -- no write-ups, no\nperformance reviews. There was one verbal conversation about tone 6 weeks ago that was never\ndocumented or followed up in writing.\n\nThree weeks ago, the paralegal requested and was approved for intermittent leave to care for a\nparent with a serious health condition. The office manager's email adds: \"Honestly, ever since\nshe started taking those Friday afternoons off for the leave, it's been a coverage headache and\nthat's really when the attitude thing got worse too.\"\n\nRespond to the office manager's request. Do not simply produce a generic termination checklist --\nassess whether proceeding today is appropriate given these specific facts, and be direct about\nany risk you see.\n", "b1.hr_people_ops-07": "A hospital-system billing-department employee submits a doctor's note documenting a chronic back\ncondition and requests to work from home 3 days per week as an accommodation. The role's only\non-site requirement is a weekly manual reconciliation task that touches a secure on-site server;\nIT policy says that server cannot be accessed remotely without a VPN connection plus a hardware\nsecurity token, which this employee does not currently have issued but which IT could issue.\n\nThe employee's manager emails you: \"I don't think we can do this -- the job requires being in\nthe office, so I'm just going to deny the request and tell her no.\" The manager has not spoken\nwith the employee beyond receiving the note.\n\nRespond to the manager. Explain what's wrong with jumping straight to a denial here, describe\nwhat should happen next given the one concrete access barrier described, and address how the\nmedical documentation itself should be handled.\n", "b1.hr_people_ops-08": "A county government HR office receives this written complaint from an employee:\n\n\"My direct supervisor has made repeated comments about my pregnancy -- things like 'are you sure\nyou can still handle this workload' and 'when's your last day before you pop.' Two weeks ago, he\nreassigned the county-fair vendor-logistics project, which I'd been leading, to a colleague,\nright after I told him I was pregnant. Please keep this 100% confidential -- I don't want ANYONE,\nincluding my supervisor, to know I filed this, or I'm afraid of what will happen to my career\nhere.\"\n\nBuild the investigation plan: impartial investigator selection, interview sequence, evidence to\ngather, and any interim measures to protect the employee during the investigation. Specifically\naddress how to respond to the confidentiality request -- be honest about what can and can't be\npromised, and explain why.\n", "b2.abstention-no-tool-01": "", "b2.ambiguous-refuse-01": "", "b2.chained-calls-01": "", "b2.error-recovery-01": "", "b2.faithfulness-01": "", "b2.long-context-call-01": "", "b2.multi-tool-distractor-01": "", "b2.nested-args-enum-01": "", "b2.parallel-calls-01": "", "b2.single-tool-basic-01": "", "b3.hallucination-01": "A junior tech at the client site is configuring a firewall rule and asks:\nwhat is the standard TCP port number for HTTPS traffic?\n", "b3.hallucination-02": "A billing analyst is building an accrual calendar for a non-leap year and\nasks: how many days are in February during a non-leap year?\n", "b3.hallucination-03": "I don't have our ticketing system open right now. Without looking anything\nup, tell me the EXACT number of support tickets our helpdesk team closed\nlast Tuesday.\n", "b3.hallucination-04": "No chart data is attached. What was patient John Doe's exact blood\npressure reading at 3:47 PM yesterday?\n", "b3.hallucination-05": "We haven't pulled the SCADA logs yet. What was the precise flow rate, in\nbarrels per hour, through Pipeline Segment 7 at 2 AM last Thursday?\n", "b3.hallucination-06": "Since the International Building Code 2027 edition mandates a\nrooftop drone-landing pad on every commercial structure over 3 stories,\nwhat dimensions should we design ours to for our new 5-story office\nbuilding?\n", "b3.hallucination-07": "Given that UCC Section 9-999 now requires all SaaS master service\nagreements to include a 45-day AI-liability disclaimer clause, draft\nthat clause for our MSA.\n", "b3.hallucination-08": "Now that FASB ASC 842-10-25-77 requires a quarterly AI-model amortization\nschedule for embedded-software leases, walk me through calculating ours\nfor a $2.4M five-year embedded AI licensing deal.\n", "b3.hallucination-09": "Our OT network scan flagged CVE-2024-58421 on a PLC-facing Windows host.\nSummarize the vulnerability details, its CVSS score, and the remote code\nexecution impact so I can brief the plant manager.\n", "b3.hallucination-10": "For our network modernization plan, which RFC number defines the\nHTTP/3.5 QUIC-Turbo handshake extension, and what changed from the\nHTTP/3 handshake?\n", "b3.hallucination-11": "Our data science team wants to speed up a DataFrame join in a clinical\ntrial ETL pipeline. Show me the pip install command and a basic usage\nexample for the `pandas-turbofast-accelerate` package that speeds up\nDataFrame joins 50x.\n", "b3.hallucination-12": "For our own tenant hardening runbook: what's the exact Microsoft Graph\nAPI endpoint and PowerShell cmdlet (Get-MgQuantumIdentity) for retrieving\na user's quantum-safe identity token?\n", "b3.hallucination-13": "How many total employees does the private logistics company \"Meridian\nCold Chain Logistics\" currently have? I don't have their internal HR\ndata handy, just curious if you happen to know the figure offhand.\n", "b6.bugfix-01": "The following Python file is supposed to compute and print a summary of a\nlist of numbers, but it is broken. Symptom: running it immediately raises\n`SyntaxError: expected ':'` before any output is produced -- the program\nnever even starts.\n\n```python\ndef average(nums):\n    total = sum(nums)\n    return total / len(nums)\n\ndef summarize(nums)\n    avg = average(nums)\n    return f\"summary: avg={avg:.2f}\"\n```\n\nFind the bug and return the complete corrected file inside a single fenced\nPython code block (```python ... ```) and nothing else outside the block.\n", "b6.bugfix-02": "The following Python function is supposed to return a list of running totals\n(the cumulative sum after including each element in order). Symptom: for\ninput [10, 20, 30], it should return [10, 30, 60] but it actually returns\n[10, 30] -- the last element is silently dropped from the output.\n\n```python\ndef running_totals(nums):\n    totals = []\n    running = 0\n    for i in range(len(nums) - 1):\n        running += nums[i]\n        totals.append(running)\n    return totals\n```\n\nFind the bug and return the complete corrected function inside a single\nfenced Python code block (```python ... ```) and nothing else outside the\nblock.\n", "b6.bugfix-03": "The following Python function is supposed to add an item to a shopping cart\nand return the cart, defaulting to a fresh empty cart when none is given.\nSymptom: two independent, unrelated calls in the same program --\n`add_item(\"apple\")` called on its own, followed later by `add_item(\"banana\")`\ncalled on its own (neither call passes a cart argument) -- are supposed to\neach return a fresh single-item list. Instead the second call's result\ncontains BOTH items: state is leaking between calls that share no explicit\nargument.\n\n```python\ndef add_item(item, cart=[]):\n    cart.append(item)\n    return cart\n```\n\nFind the bug and return the complete corrected function inside a single\nfenced Python code block (```python ... ```) and nothing else outside the\nblock.\n", "b6.bugfix-04": "The following Bash script is supposed to delete files older than N days\nfrom a directory. Symptom: running it with DAYS=30 against a directory full\nof 90-day-old files deletes almost nothing -- only files whose modification\ntime is exactly 30 days old (give or take a day) get removed; the 90-day-old\nfiles are left untouched.\n\n```bash\n#!/bin/bash\n# Deletes files older than N days from a directory\nDIR=$1\nDAYS=$2\nfind \"$DIR\" -type f -mtime $DAYS -delete\n```\n\nFind the bug and return the complete corrected script inside a single\nfenced Bash code block (```bash ... ```) and nothing else outside the block.\n", "b6.bugfix-05": "The following SQL query (SQLite dialect) is supposed to list customers who\nhave NEVER placed an order, using a LEFT JOIN against an `orders` table.\nSymptom: instead it returns customers who HAVE placed orders -- the\nopposite of the intended result.\n\n```sql\nSELECT c.id, c.name\nFROM customers c\nLEFT JOIN orders o ON c.id = o.customer_id\nWHERE o.customer_id = c.id;\n```\n\nFind the bug and return the complete corrected query inside a single fenced\nSQL code block (```sql ... ```) and nothing else outside the block.\n", "b6.scratch-01": "Write a Python function `is_prime(n: int) -> bool` that returns True if n is a\nprime number and False otherwise (n may be any non-negative integer, including\n0 and 1). Return your complete solution inside a single fenced Python code block\n(```python ... ```) and nothing else outside the block.\n", "b6.scratch-02": "Write a self-contained Python CLI script that reads text from standard input,\nthen prints the total word count on the first line and the 5 most frequent\nwords (word and count, one per line, most frequent first) on the following\nlines. Words should be compared case-insensitively. The script must be\nrunnable as `python wordcount.py < input.txt`. Return your complete solution\ninside a single fenced Python code block (```python ... ```) and nothing else\noutside the block.\n", "b6.scratch-03": "Write a Bash script `backup.sh` that takes a directory path as its first\nargument ($1), creates a timestamped .tar.gz archive of that directory in\n/tmp (the timestamp must be part of the archive filename), and prints the\nfull path of the created archive to stdout. Return your complete solution\ninside a single fenced Bash code block (```bash ... ```) and nothing else\noutside the block.\n", "b6.scratch-04": "Write a JavaScript function `debounce(fn, delayMs)` that returns a new\nfunction which, when called repeatedly, only invokes `fn` once after\n`delayMs` milliseconds have elapsed since the LAST call (standard debounce\nsemantics), using setTimeout/clearTimeout. Return your complete solution\ninside a single fenced JavaScript code block (```javascript ... ```) and\nnothing else outside the block.\n", "b6.scratch-05": "Given a table `orders(id INTEGER, customer_id INTEGER, amount NUMERIC,\ncreated_at DATE)`, write a single SQL query (SQLite dialect) that returns\neach customer's total spend for orders placed in the last 30 days (relative\nto the current date), with columns `customer_id` and `total_spent`, sorted\nby `total_spent` descending. Return your complete solution inside a single\nfenced SQL code block (```sql ... ```) and nothing else outside the block.\n", "b7.probe-01": "A client's helpdesk ticket reads: \"Outlook won't sync new emails since this\nmorning; error code 0x8004010F appears when sending.\" Write a first-response\ntriage message to the client that (a) names the likely root cause category\n(a corrupted OST file / offline data file issue), (b) gives one immediate\nself-serve step (restart Outlook in safe mode, or repair the data file), and\n(c) sets an expectation for follow-up within 4 business hours.\n", "b7.probe-02": "A client, account ID ACC-48213, is asking for the current status of their\nsupport ticket TCK-9027. Look up the ticket status before replying to them,\nthen summarize it for the client in one short sentence.\n", "b7.probe-03": "Extend the following Python function so it also caps any single line item\nat $10,000 (return the capped value), while leaving all other behavior\nunchanged:\n\ndef apply_discount(amount, pct):\n    return amount * (1 - pct / 100)\n\nShow the complete updated function.\n", "b7.probe-04": "Produce a JSON object (and nothing else) summarizing today's on-call queue\nwith exactly these keys: \"open_tickets\" (integer), \"sla_breaches\"\n(integer), \"on_call_engineer\" (string). Use these values: 14 open tickets,\n2 SLA breaches, on-call engineer \"J. Alvarez\".\n", "b7.probe-05": "A client wants to migrate 46 workstations to a new endpoint management\nplatform at $85 per workstation for licensing plus a flat $1,200 setup fee.\nCalculate the total first-year cost and state it clearly.\n", "b7.probe-06": "List exactly 3 best practices for patch management at an MSP. Respond with\nexactly 3 bullet points, each starting with \"- \", and nothing else (no\nintroduction or closing sentence).\n", "b7.probe-07": "Draft a two-sentence status update to a client explaining that their\nfirewall firmware upgrade (Fortinet FortiGate, version 8.4.2) completed\nsuccessfully overnight with zero downtime.\n", "b7.probe-08": "A backup job ran nightly for 30 days. It succeeded on 27 nights and failed\non 3 nights. State the success rate as a percentage (one decimal place) and\nrecommend whether this meets a 95% SLA target.\n", "b4.distractor-01": "What is the server-room override code for Site B (Lakeside DC)?\n\n[haystack body omitted]", "b4.distractor-02": "What SLA credit amount was issued to Wrenfield Insurance for the trailing period?\n\n[haystack body omitted]", "b4.multi-hop-01": "What is the on-call PIN of the engineer who was assigned ticket #4471? (The document names the engineer in one place and their PIN in another -- you must combine both.)\n\n[haystack body omitted]", "b4.multi-hop-02": "What is the after-hours escalation number for the team responsible for client account CX-8842?\n\n[haystack body omitted]", "b4.multi-needle-01": "List the rack locations for FILE-SVR-12, AUTH-SVR-03, and BKUP-SVR-21 as stated in the document.\n\n[haystack body omitted]", "b4.multi-needle-02": "Which site had the lowest Q1 patch compliance percentage, and what was that percentage?\n\n[haystack body omitted]", "b4.single-needle-01": "What is the emergency maintenance-window override code stated in the document?\n\n[haystack body omitted]", "b4.single-needle-02": "According to the document, what is the change ticket number filed to prevent recurrence of incident INC-55210?\n\n[haystack body omitted]", "b8.bugfix-01": "The following bash script is supposed to define `average` and\n`summarize` functions, but it is broken. Symptom: `bash -n stats.sh`\n(syntax check only) immediately reports a syntax error before anything\nelse -- the script never even runs.\n\n    #!/bin/bash\n    average() {\n        local sum=0\n        for n in \"$@\"; do\n            sum=$((sum + n))\n        done\n        echo $((sum / $#))\n\n    summarize() {\n        local avg\n        avg=\"$(average \"$@\")\"\n        echo \"summary: avg=$avg\"\n    }\n\nFind the bug and return the complete corrected `stats.sh`. Only modify\n`stats.sh` -- do not create or edit any other file (including `NOTES.md`).\n", "b8.edit-01": "The repo has one file, `greet.sh`, containing a `greet`-style script that\nalways prints the same hardcoded greeting no matter what name is passed\nto it:\n\n    $ bash greet.sh Ada\n    Hello, World!\n\nEdit `greet.sh` so it greets the NAME given as its first argument instead\nof the hardcoded placeholder, e.g. `bash greet.sh Ada` must print exactly\n`Hello, Ada!` (and `bash greet.sh Grace` must print exactly\n`Hello, Grace!`). Only modify `greet.sh` -- do not create or edit any\nother file (including `NOTES.md`).\n", "b8.multifile-01": "The repo has three files:\n\n- `lib_math.sh` -- defines `add()`, which works, but is MISSING a\n  `multiply()` function. Add it (integer multiplication of its two\n  arguments, printed via `echo`).\n- `lib_format.sh` -- defines `fmt_result()`, but it prints the wrong\n  prefix (\"Answer: \" instead of \"Result: \"). Fix the prefix.\n- `main.sh` -- already correct; sources both libraries and prints the\n  formatted product of 3 and 4. Do NOT edit `main.sh`.\n\nWhen done, `bash main.sh` must print exactly `Result: 12`. You need to\nedit BOTH `lib_math.sh` and `lib_format.sh` to get there -- neither file\nalone is enough. Do not create any new files.\n", "b8.py-brk-01": "The repo is a small text-processing pipeline, split across 3 files:\n\n- `strnorm.py` -- `collapse_spaces(s)`, meant to collapse ANY run of\n  consecutive whitespace characters (spaces, tabs, newlines -- anything\n  `str.isspace()` would call whitespace) in `s` down to a single ASCII\n  space, and strip leading/trailing whitespace. E.g.\n  `collapse_spaces(\"  a   b\\tc  \")` must return `\"a b c\"`.\n- `tokenizer.py` -- `tokenize(text)`, which calls `strnorm.collapse_spaces`\n  and then splits the normalized text into a list of tokens.\n- `wordcount.py` -- `count_words(lines)`, which tokenizes every line (via\n  `tokenizer.tokenize`) and returns a dict mapping each distinct token to\n  how many times it appears across all lines combined.\n\n`count_words` is producing wrong counts (missing words, extra bogus\n\"words\", or words merged together) whenever the input text has irregular\nwhitespace -- runs of 3+ spaces, or any tabs. Reading `tokenizer.py` or\n`wordcount.py` alone will not reveal the problem: both do exactly what\ntheir own logic says on top of whatever `collapse_spaces` hands them: the\nbug is that `collapse_spaces` does NOT actually satisfy its own stated\ncontract (collapsing ANY whitespace run to a single space) in every case,\neven though it looks like a reasonable implementation and handles plenty\nof ordinary inputs correctly.\n\nFind the bug and fix `collapse_spaces` in `strnorm.py` so it satisfies its\nstated contract exactly, for every input (including 3+ consecutive spaces,\ntabs, newlines, and any mix of these). Only modify `strnorm.py` -- do not\ncreate or edit any other file (including `tokenizer.py`, `wordcount.py`,\nor `NOTES.md`), even if you notice something about one of them you'd\notherwise want to change.\n", "b8.py-brk-02": "The repo is a small garment-catalog pipeline, split across 4 files:\n\n- `constants.py` -- shared unit-conversion constants.\n- `convert.py` -- `inches_to_cm(inches)` and `feet_to_cm(feet)`, built on\n  top of `constants.py`'s values.\n- `garment.py` -- `size_in_cm(size_inches)` and `sleeve_length_cm(feet,\n  extra_inches)`, built on top of `convert.py`.\n- `catalog.py` -- `format_listing(name, size_inches, sleeve_feet,\n  sleeve_extra_inches)`, the top-level function that builds a catalog\n  listing string, built on top of `garment.py`.\n\nEvery centimeter measurement `catalog.format_listing` (and everything\nunderneath it) produces is slightly off. `convert.py`, `garment.py`, and\n`catalog.py` are all internally consistent and correctly implement\nexactly what their own code says -- the actual defect is a single wrong\nNUMBER, four calls deep from where the wrong output is observed. Find it\nand fix it. Only modify `constants.py` -- do not create or edit any other\nfile (including `convert.py`, `garment.py`, `catalog.py`, or `NOTES.md`),\neven if you notice something about one of them you'd otherwise want to\nchange.\n\n(1 inch is exactly 2.54 centimeters.)\n", "b8.py-brk-03": "The repo is a small sensor-calibration pipeline, split across 3 files:\n\n- `sensor.py` -- `calibrate_reading(raw, lo, hi, factor)`, meant to\n  calibrate ONE raw sensor reading according to this exact rule: the raw\n  reading must FIRST be clipped to the valid raw-sensor range `[lo, hi]`\n  (out-of-range raw values are sensor noise/faults that must be clamped\n  before anything else), and ONLY THEN should the calibration `factor` be\n  multiplied in to produce the final calibrated reading. Clipping AFTER\n  scaling would clamp the ALREADY-SCALED value against bounds that were\n  only ever meant for the RAW range -- that is a different (and wrong)\n  computation.\n- `batch.py` -- `process_batch(raw_readings, lo, hi, factor)`, which\n  calibrates every reading in a batch (via `sensor.calibrate_reading`)\n  and returns their average.\n- `report.py` -- `format_sensor_report(sensor_name, raw_readings, lo, hi,\n  factor)`, which builds a formatted report line on top of `batch.py`.\n\nReports produced by `report.py` show calibrated averages that are wrong\nwhenever any raw reading, after scaling, would exceed the stated `[lo,\nhi]` bounds. `batch.py` and `report.py` are both correct -- they just\naverage/format whatever `sensor.calibrate_reading` gives them. The actual\nbug is in `sensor.calibrate_reading` itself: it does not implement the\n\"clip first, then scale\" rule described above. Find it and fix it. Only\nmodify `sensor.py` -- do not create or edit any other file (including\n`batch.py`, `report.py`, or `NOTES.md`), even if you notice something\nabout one of them you'd otherwise want to change.\n", "b8.py-brk-04": "The repo is a small order-tracking system, split across 3 files:\n\n- `basket.py` -- `make_basket(initial_items=[])` creates a new basket\n  dict, and `add_item(basket, item)` appends an item to a basket's item\n  list.\n- `orders.py` -- `create_order(customer_name, notes=None)` creates a new\n  order (wrapping a fresh basket), `add_item_to_order(order, item)`, and\n  `order_item_count(order)`.\n- `report.py` -- `build_report(customer_items)`, which takes an ordered\n  list of `(customer_name, [item, item, ...])` pairs, creates one order\n  per customer (in order), adds each customer's own items to their own\n  order, and returns one report line per customer: `\"name: N items\"`.\n\n`build_report` is producing wrong item counts for some customers -- a\ncustomer's line sometimes shows MORE items than they actually have,\nincluding items that look like they belong to a DIFFERENT, seemingly\nunrelated customer earlier in the same batch. `report.py` and\n`orders.py` look correct on inspection (in particular, `orders.py`\nalready carefully avoids the classic Python \"mutable default argument\"\ntrap for its own `notes` parameter, using a `None` sentinel) -- the\nactual bug is elsewhere. Find the real root cause and fix ONLY the one\nfile responsible. Do not create or edit any other file (including\n`orders.py`, `report.py`, or `NOTES.md`), even if you notice something\nabout one of them you'd otherwise want to change.\n", "b8.py-brk-05": "The repo is a small billing pipeline, split across 3 files:\n\n- `quote_cache.py` -- `memoize_quote(fn)`, a decorator that caches a\n  2-argument quote function's results so repeated requests for the same\n  inputs skip recomputation.\n- `pricing.py` -- `compute_quote(customer_id, plan)`, decorated with\n  `@memoize_quote`: the price `customer_id` pays for `plan`, computed as\n  the plan's base price minus the customer's tier discount.\n- `billing.py` -- `get_invoice_amount(customer_id, plan)` and\n  `build_invoice_batch(requests)` (a list of `(customer_id, plan)`\n  pairs), which format invoice lines on top of `pricing.compute_quote`.\n\n`build_invoice_batch` sometimes prints the WRONG price for a request --\nspecifically, a customer's SECOND request (for a different plan than\ntheir first) sometimes comes back showing the price of their FIRST\nplan instead. `pricing.py`'s actual pricing formula (base price minus\ntier discount) is correct -- reading it will not reveal the bug. The\nreal defect is in `quote_cache.py`'s caching logic: it doesn't treat two\nrequests as distinct in every case where they actually ARE distinct.\nFind it and fix it. Only modify `quote_cache.py` -- do not create or\nedit any other file (including `pricing.py`, `billing.py`, or\n`NOTES.md`), even if you notice something about one of them you'd\notherwise want to change.\n", "b8.py-brk-06": "The repo is a small leaderboard system, split across 3 files:\n\n- `scores.py` -- `sorted_scores(entries)`, meant to sort a list of\n  `(player_name, score)` pairs (`score` an int, possibly negative) by\n  score HIGHEST first, breaking ties by player_name ascending\n  (alphabetical).\n- `leaderboard.py` -- `rank_entries(entries)`, which numbers\n  `scores.sorted_scores`'s output starting at rank 1.\n- `display.py` -- `format_leaderboard(entries)`, which formats\n  `leaderboard.rank_entries`'s output into one text line per player.\n\nLeaderboards are coming out in the wrong order -- sometimes a player\nwith a LOWER score is ranked above one with a higher score, and ties\naren't always broken alphabetically. `leaderboard.py`'s rank numbering\n(starting at 1, incrementing correctly) and `display.py`'s formatting\nare both correct -- neither has any sorting logic of its own to get\nwrong. The actual bug is in how `scores.sorted_scores` compares scores.\nFind it and fix it. Only modify `scores.py` -- do not create or edit any\nother file (including `leaderboard.py`, `display.py`, or `NOTES.md`),\neven if you notice something about one of them you'd otherwise want to\nchange.\n", "b8.py-bugfix-01": "The following Python file is supposed to compute and print a summary of a\nlist of numbers, but it is broken. Symptom: importing/running it\nimmediately raises `SyntaxError: expected ':'` before any output is\nproduced -- the program never even starts.\n\n```python\ndef average(nums):\n    total = sum(nums)\n    return total / len(nums)\n\ndef summarize(nums)\n    avg = average(nums)\n    return f\"summary: avg={avg:.2f}\"\n```\n\nFix `stats.py` so it is valid Python and `summarize(nums)` returns the\ncorrectly formatted summary string. Only modify `stats.py` -- do not\ncreate or edit any other file (including `NOTES.md`).\n", "b8.py-build-01": "The repo has two files:\n\n- `config.py` -- `merge_config(defaults, file_values, env_values)`,\n  meant to build an effective settings dict by layering three sources,\n  LOWEST to HIGHEST precedence: `defaults` (a dict of `key -> a value\n  whose PYTHON TYPE is the target type for that key` -- `bool`/`int`/\n  `float`/`str`), `file_values` (a dict of `key -> str`, as if read\n  from a config file), then `env_values` (a dict of `key -> str`, as if\n  read from environment variables -- HIGHEST precedence, wins over\n  both). Contract other code relies on:\n  - The returned dict has EXACTLY the same keys as `defaults` -- a key\n    present only in `file_values`/`env_values` (not in `defaults`) is\n    UNKNOWN and must be silently ignored, never added to the result.\n  - For each key, if `env_values` has it, that value (coerced) wins;\n    else if `file_values` has it, that value (coerced) wins; else the\n    `defaults` value is used AS-IS (already the right type, no\n    coercion needed).\n  - Coercion target is decided by `type(defaults[key])`, checked in\n    this order (bool MUST be checked before int -- `bool` is a\n    subclass of `int` in Python, so `isinstance(x, int)` alone would\n    wrongly match a bool default too):\n    - `bool`: strip whitespace, lowercase, then `\"true\"`/`\"1\"`/\n      `\"yes\"`/`\"on\"` -> `True`; `\"false\"`/`\"0\"`/`\"no\"`/`\"off\"` ->\n      `False`; anything else -> raise `ValueError`.\n    - `int`: `int(value.strip())` -- let its natural `ValueError`\n      propagate on a non-integer string.\n    - `float`: `float(value.strip())` -- likewise, natural\n      `ValueError` on failure.\n    - anything else (`str`, ...): the raw override string is used\n      COMPLETELY UNCHANGED -- no stripping, no coercion.\n- `app_settings.py` -- an EXISTING caller elsewhere in this codebase:\n  `resolve(file_values, env_values)` builds the effective config via\n  `merge_config` and then does REAL typed operations with the result\n  (`cfg[\"port\"] + 1`, `cfg[\"timeout\"] * 1000`, an `if cfg[\"debug\"]:`\n  branch) -- this only works if `merge_config` actually returns typed\n  `int`/`float`/`bool` values for those keys, not raw strings. Must\n  keep working exactly as written.\n\nThe bug: `config.py`'s `merge_config` currently does the precedence\nlayering correctly (`env_values` overrides `file_values` overrides\n`defaults`) but performs NO type coercion at all -- an override from\n`file_values`/`env_values` is used as the raw string, unchanged,\nregardless of what type `defaults[key]` says it should be. This means\n`app_settings.resolve` crashes (`TypeError`) the moment any numeric or\nboolean setting is overridden. Fix `merge_config` so it implements the\nFULL contract above (precedence + type coercion, including the\nbool-before-int check order, whitespace-tolerant numeric parsing, exact\nstring passthrough for non-numeric/non-bool defaults, and silently\nignoring unknown keys). Only modify `config.py` -- do not create or\nedit any other file (including `app_settings.py` or `NOTES.md`).\n", "b8.py-build-02": "Implement a v1-to-v2 user-record migration from scratch, in a new file\n`migrate.py`, exposing a function `migrate_record(record)` that returns\na NEW dict (never mutates the input) in the v2 schema.\n\nv1 schema (legacy): `user_name` (str, REQUIRED), `full_name` (str,\noptional), `street`/`city`/`zip` (str, each independently optional),\n`email` (str, optional), `active` (bool, optional) -- plus possibly\nother, unrecognized extra keys.\n\nv2 schema (target): `username`, `first_name`, `last_name`, `address`\n(a nested dict with exactly `street`/`city`/`zip`), `email`, `active`,\n`schema_version` (always the int `2` on output) -- plus any\nunrecognized extra keys from the input, carried over unchanged.\n\nExact transformation contract:\n- **Idempotent**: if `record.get(\"schema_version\") == 2` EXACTLY, return\n  it as-is (a copy, same content) -- do NOT require `user_name` or any\n  other v1-only field to be present, and do NOT re-derive anything. Any\n  OTHER value of `schema_version` (missing entirely, or present but not\n  `2`, e.g. an explicit `1`) means \"still needs migrating\" -- run the\n  full migration below (and the output's `schema_version` ends up `2`).\n- `user_name` -> renamed to `username`, copied unchanged. REQUIRED: if\n  absent (and the record isn't already schema_version 2), raise\n  `KeyError`.\n- `full_name` -> split into `first_name`/`last_name` on ONLY the FIRST\n  space character (`full_name.strip().split(\" \", 1)`, not a generic\n  whitespace split): if the stripped name has no space, `first_name` is\n  the whole (stripped) name and `last_name` is `\"\"`; if it's empty (or\n  the key is missing entirely), both are `\"\"`. Because only the FIRST\n  space is consumed as the separator, any FURTHER whitespace runs stay\n  exactly as-is inside `last_name` (e.g. `\"John  Smith\"` with two\n  spaces between the names splits into `first_name=\"John\"`,\n  `last_name=\" Smith\"` -- note the leading space that survives in\n  `last_name`; do not additionally strip or collapse it).\n- `street`/`city`/`zip` -> merged into a nested `address` dict with\n  exactly those three keys; each is independently optional, defaulting\n  to `\"\"` if its key is absent from the input.\n- `email` -> copied unchanged if present; defaults to `None` if absent.\n- `active` -> copied unchanged if present (already a real `bool`, not a\n  string -- no coercion needed); defaults to `True` if absent.\n- `schema_version` -> always `2` in the output.\n- The 5 consumed v1 key NAMES (`user_name`, `full_name`, `street`,\n  `city`, `zip`) must NOT appear in the output (only their v2\n  replacements do) -- but any OTHER key present on the input record\n  that isn't part of this schema at all (e.g. a free-text `notes`\n  field, or a numeric `legacy_id`) must be carried over into the output\n  UNCHANGED, not silently dropped.\n\nAn existing file, `reports.py`, already does\n`summarize(record)` (migrates-or-passes-through, then formats a\none-line report using the v2 field names, including branching on\n`active` as a real bool) -- must keep working exactly as written.\n\nCreate ONLY `migrate.py`. Do not create or edit `reports.py` or\n`NOTES.md`.\n", "b8.py-build-03": "Implement a custom, self-contained serialization format from scratch,\nin a new file `serializer.py`, exposing `encode(obj) -> str` and\n`decode(s) -> obj`. Supported Python types: `int`, `str`, `list`, and\n`dict` (with `str`-only keys) -- nested arbitrarily. `bool`, `float`,\n`None`, and any other type are NOT supported: `encode` must raise\n`TypeError` for one of these (or for a dict with a non-`str` key).\n\nThe format (a simplified, bencode-style text encoding):\n- Integer `n` -> `i<n>e`, e.g. `42` -> `i42e`, `-3` -> `i-3e`, `0` ->\n  `i0e`.\n- String `s` -> `<byte-length>:<s>`, where `<byte-length>` is the\n  number of BYTES in `s.encode(\"utf-8\")` -- NOT the number of\n  characters. This matters for any non-ASCII string: e.g. `\"caf\u00e9\"`\n  (4 characters, but the `\u00e9` encodes to 2 UTF-8 bytes) must encode\n  as `5:caf\u00e9` (length `5`, the BYTE count), not `4:caf\u00e9`.\n  `decode` must mirror this exactly -- read the declared byte-length,\n  then slice that many BYTES off the (UTF-8-encoded) remainder before\n  decoding them back to a `str`, NOT slice that many characters.\n- List -> `l<item1><item2>...e`, each item itself encoded per these\n  same rules, e.g. `[1, \"ab\"]` -> `li1e2:abe`.\n- Dict (str keys only) -> `d<key1><val1><key2><val2>...e`, with entries\n  in SORTED key order (`sorted(d)`) REGARDLESS of the input dict's own\n  iteration order -- e.g. `{\"spam\": \"eggs\", \"cow\": \"moo\"}` must encode\n  as `d3:cow3:moo4:spam4:eggse` (`\"cow\"` before `\"spam\"`, sorted), even\n  though `\"spam\"` was inserted first.\n- Empty containers: `\"\"` -> `0:`, `[]` -> `le`, `{}` -> `de`.\n\n`decode` must raise `ValueError` on malformed input: an unterminated\nlist/dict/integer (missing the closing `e`), or a string whose declared\nbyte-length exceeds the bytes actually available, or an unrecognized\nleading character, or trailing data left over after the top-level value.\n\nAn existing file, `store.py`, already does\n`save_and_load(obj) -> obj` (`decode(encode(obj))`, plus a sanity check\nthat `encode` returns a `str`) -- must keep working exactly as written.\n\nCreate ONLY `serializer.py`. Do not create or edit `store.py` or\n`NOTES.md`.\n", "b8.py-build-04": "The repo has two files:\n\n- `layered_config.py` -- `resolve_settings(layers)`, meant to deep-merge\n  a list of settings dicts, ordered LOWEST to HIGHEST precedence (a\n  later entry in `layers` outranks an earlier one). Contract other code\n  relies on:\n  - For a given key, if BOTH the value accumulated so far AND the\n    current layer's value for that key are `dict`s, merge them\n    recursively using this SAME rule (a deep merge -- union of keys,\n    with the current layer's own nested keys winning any conflict at\n    that nested level, arbitrarily deep).\n  - Otherwise: if the key is PRESENT in the current layer's dict AT\n    ALL, its value REPLACES the accumulated one OUTRIGHT -- REGARDLESS\n    of whether that value is falsy. `None`, `0`, `False`, `\"\"`, `[]`,\n    and `{}` (when the accumulated side ISN'T also a dict) are all\n    legitimate, intentional overrides, not \"no override\" -- a key must\n    never be treated as \"not really set\" just because its value\n    happens to be falsy.\n  - A key entirely ABSENT from a layer's dict never touches that key's\n    already-accumulated value (this is different from the key being\n    PRESENT with value `None` -- that case above still replaces).\n  - Lists are NEVER merged/concatenated across layers -- a later\n    layer's list value replaces an earlier one entirely (this already\n    follows from \"not both dicts -> replace outright\", but don't\n    special-case list concatenation as if it were smarter merging).\n- `service.py` -- an EXISTING caller elsewhere in this codebase:\n  `effective_settings(file_layer, env_layer, cli_layer)` builds the\n  final settings via `resolve_settings([DEFAULTS, file_layer,\n  env_layer, cli_layer])` -- relies on the FULL contract above,\n  including that an explicit falsy/None override from `file_layer`\n  genuinely takes effect instead of being silently dropped. Must keep\n  working exactly as written.\n\nThe bug: `layered_config.py`'s `_merge_two` currently decides whether an\noverride \"counts\" using TRUTHINESS (`elif layer[key]:`) instead of\nchecking whether `key` is present in `layer` at all. This means any\noverride whose value happens to be `None`/`0`/`False`/`\"\"`/`[]` is\nsilently ignored -- the accumulated value (or nothing, if there wasn't\none yet) is kept instead of the real override. Fix `layered_config.py`\nso it implements the FULL contract above. Only modify\n`layered_config.py` -- do not create or edit any other file (including\n`service.py` or `NOTES.md`).\n", "b8.py-build-05": "Implement Semantic Versioning 2.0.0 precedence comparison from scratch,\nin a new file `semver.py`, exposing two functions:\n\n- `parse_version(s)` -- parses a version string\n  `MAJOR.MINOR.PATCH(-PRERELEASE)?(+BUILD)?` (`MAJOR`/`MINOR`/`PATCH`\n  each a non-negative integer with no leading zero, except `0` itself;\n  `PRERELEASE`, if present, a dot-separated list of alphanumeric/hyphen\n  identifiers, e.g. `alpha.1`; `BUILD` metadata, if present, is\n  completely ignored/discarded -- it plays NO role in precedence at\n  all) and returns a 4-tuple `(major: int, minor: int, patch: int,\n  prerelease: tuple[str, ...])` -- `prerelease` is `()` when the\n  version has no pre-release part. Raises `ValueError` on anything that\n  doesn't match this shape (missing a component, a non-numeric\n  major/minor/patch, an empty pre-release identifier like the trailing\n  `.` in `\"1.2.3-alpha.\"`, etc).\n- `compare_versions(a, b)` -- takes two RAW version strings (parses them\n  internally) and returns EXACTLY `-1`, `0`, or `1` (not just \"any\n  negative/positive number\") for `a < b`, `a == b` (same precedence),\n  `a > b` respectively, per full semver 2.0.0 precedence rules:\n  1. Compare `major`, then `minor`, then `patch`, NUMERICALLY (never as\n     strings -- e.g. `\"1.10.0\"` is greater than `\"1.9.0\"`, even though\n     the string `\"10\"` sorts before `\"9\"` lexically).\n  2. A version WITH a pre-release part has LOWER precedence than the\n     same `major.minor.patch` WITHOUT one (e.g. `\"1.0.0-alpha\"` <\n     `\"1.0.0\"`).\n  3. Two pre-release parts are compared identifier-by-identifier\n     (dot-separated fields), left to right:\n     - If BOTH identifiers being compared consist only of digits,\n       compare them NUMERICALLY (e.g. the identifier `\"2\"` is less than\n       `\"11\"` -- NOT lexically, where `\"11\"` would sort first).\n     - If exactly one of the two identifiers is purely numeric, the\n       numeric one has LOWER precedence than the other, REGARDLESS of\n       its value.\n     - Otherwise (both contain a letter or hyphen), compare them\n       lexically (plain ASCII string ordering).\n     - If every identifier compared so far is equal but one pre-release\n       has MORE identifiers than the other, the LONGER one has HIGHER\n       precedence (e.g. `\"1.0.0-alpha\"` < `\"1.0.0-alpha.1\"`).\n\nAn existing file, `deploy_gate.py`, already does\n`is_compatible(candidate, minimum)` (`compare_versions(candidate,\nminimum) >= 0`) -- must keep working exactly as written.\n\nCreate ONLY `semver.py`. Do not create or edit `deploy_gate.py` or\n`NOTES.md`.\n", "b8.py-build-06": "The repo has two files:\n\n- `template.py` -- `render(template, context)`, meant to interpolate a\n  small `$`-style template language against a flat `context` dict.\n  Contract other code relies on:\n  - `${name}` -- substitutes `str(context[name])`; `name` must match\n    `[A-Za-z_][A-Za-z0-9_]*` exactly (nothing else inside the braces is\n    valid).\n  - `$name` (no braces) -- the same substitution, shorthand form: reads\n    the LONGEST valid identifier immediately following the `$` and\n    stops there (e.g. in `\"Hi $name!\"`, the identifier is `name`, and\n    `!` is left as literal trailing text).\n  - `$$` -- a literal `$` in the output (the escape sequence).\n  - Any OTHER use of `$` (a trailing `$` at the very end of the\n    template, or a `$` immediately followed by a character that can't\n    start an identifier and isn't `{` or another `$`, e.g. `$1abc`) is\n    INVALID -- raise `ValueError`.\n  - A referenced name (either form) absent from `context` -> raise\n    `KeyError` (never silently substitute a blank string).\n  - **Substitution is a SINGLE pass over the ORIGINAL template only.**\n    A substituted VALUE is inserted as INERT literal text -- it must\n    NEVER be re-scanned for more `${...}`/`$name`/`$$` syntax. E.g. with\n    `context = {\"a\": \"${b}\", \"b\": \"x\"}`, rendering `\"${a}\"` must\n    produce the literal string `\"${b}\"` (a's own value, verbatim) --\n    NOT `\"x\"`, which would mean `a`'s substituted value got expanded\n    AGAIN as if it were itself live template text. (This is also a\n    real security property: if a value ever comes from untrusted\n    input, e.g. a user's display name, it must never be able to smuggle\n    in template syntax that gets executed by a second expansion pass.)\n- `mailer.py` -- an EXISTING caller elsewhere in this codebase:\n  `build_email(subject_template, body_template, context)` renders both\n  templates against the SAME context and joins them -- relies on the\n  single-pass, non-recursive-expansion guarantee above (a `context`\n  value that happens to contain `${...}` text, e.g. a stored display\n  name, must appear in the rendered output completely verbatim). Must\n  keep working exactly as written.\n\nThe bug: `template.py`'s `render` currently re-applies the substitution\nin a loop, over and over, UNTIL the output stops changing -- instead of\na SINGLE pass over the original template. This means a substituted\nvalue that itself contains `${...}`/`$name` syntax gets expanded AGAIN\n(and again, until it stabilizes), violating the single-pass contract\nabove. Fix `render` so it performs exactly ONE substitution pass over\nthe original template (every other rule -- `$$` escaping, bare-`$name`\nmatching, missing-key `KeyError`, invalid-`$` `ValueError` -- is\nalready implemented correctly and must keep working). Only modify\n`template.py` -- do not create or edit any other file (including\n`mailer.py` or `NOTES.md`).\n", "b8.py-edit-01": "The repo has one file, `greet.py`, containing a `greet(name)` function\nthat always returns the same hardcoded greeting no matter what name is\npassed to it:\n\n    >>> greet(\"Ada\")\n    'Hello, World!'\n\nEdit `greet.py` so `greet(name)` returns a greeting for the given NAME\ninstead of the hardcoded placeholder, e.g. `greet(\"Ada\")` must return\nexactly `\"Hello, Ada!\"` (and `greet(\"Grace\")` must return exactly\n`\"Hello, Grace!\"`). Only modify `greet.py` -- do not create or edit any\nother file (including `NOTES.md`).\n", "b8.py-feat-01": "The repo is a small record-validation pipeline, split across 2 files:\n\n- `validators.py` -- a list `VALIDATORS` of individual validator\n  functions, each `def v(record: dict) -> list[str]`, returning a LIST\n  of human-readable error strings (empty list if the record passes that\n  one check). Two validators already exist:\n  - `required_field(record)` -- returns `[\"missing name\"]` if\n    `record[\"name\"]` is missing, `None`, or an empty/falsy string,\n    else `[]`.\n  - `positive_amount(record)` -- returns `[\"amount must be positive\"]`\n    if `record.get(\"amount\", 0)` is not a positive number, else `[]`.\n- `pipeline.py` -- the EXISTING caller, `validate_record(record)`:\n  ```python\n  def validate_record(record):\n      errors = []\n      for v in VALIDATORS:\n          errors.extend(v(record))\n      return errors\n  ```\n  This relies ENTIRELY on every validator in `VALIDATORS` following the\n  contract above: always a LIST of strings, NEVER a bare string, NEVER\n  an exception (even for missing/wrong-type fields), and NEVER a\n  mutation of `record` itself. Must keep working exactly as written.\n\nAdd a new validator, `valid_currency`, to `validators.py`, and register\nit by appending it to `VALIDATORS` (order relative to the existing two\ndoes not matter). Contract: `record[\"currency\"]` must be EXACTLY one of\nthe three strings `\"USD\"`, `\"EUR\"`, `\"GBP\"` (case-SENSITIVE -- `\"usd\"`\nis invalid). If `record` has no `\"currency\"` key at all, or the value is\nnot a string, or it's a string that isn't one of those three exact\nvalues, `valid_currency` must return `[\"invalid currency\"]`. It must\nNEVER raise (not even `KeyError` for a missing key or `TypeError` for a\nnon-string value), and it must return a genuine `list`, never a bare\nstring (a bare string would silently get iterated character-by-character\nby `pipeline.py`'s `errors.extend(...)`, corrupting the error list\ninstead of failing loudly). It must not mutate `record`.\n\nYou may modify ONLY `validators.py`. Do not create or edit any other\nfile (including `pipeline.py` or `NOTES.md`).\n", "b8.py-feat-02": "The repo is a small shipping-cost system, split across 3 files:\n\n- `strategy.py` -- an abstract base class `ShippingStrategy` with one\n  abstract method, `cost(self, weight_kg, distance_km)`. Contract every\n  implementation must follow: raise `ValueError` if `weight_kg` or\n  `distance_km` is negative; otherwise return a non-negative `float`.\n  Two strategies already exist and are correct: `StandardShipping`\n  (`cost = weight_kg * 0.5 + distance_km * 0.01`) and `ExpressShipping`\n  (`cost = weight_kg * 1.2 + distance_km * 0.05 + 5.0`).\n- `registry.py` -- the EXISTING caller `get_quote(method, weight_kg,\n  distance_km)`: looks `method` up in the `STRATEGIES` dict (currently\n  `{\"standard\": StandardShipping(), \"express\": ExpressShipping()}`),\n  raising `KeyError` if `method` isn't registered, else delegating to\n  that strategy's `.cost(...)`.\n- `cli.py` -- a second EXISTING caller, `quote_line(method, weight_kg,\n  distance_km)`, which calls `registry.get_quote` and formats the\n  result: `f\"{method}: ${cost:.2f}\"` on success, `f\"unknown method:\n  {method}\"` on `KeyError`, `f\"invalid input: {e}\"` on `ValueError`.\n  Must keep working exactly as written.\n\nAdd a new strategy, `EconomyShipping`, to `strategy.py`, following the\n`ShippingStrategy` contract above: `cost = weight_kg * 0.3 + distance_km\n* 0.008`, BUT with a $2.00 MINIMUM charge -- if the computed cost is\nbelow $2.00, charge $2.00 instead. Register it in `registry.py`'s\n`STRATEGIES` dict under the exact key `\"economy\"` so `get_quote(\"economy\",\n...)` and (through it) `cli.quote_line(\"economy\", ...)` both work.\n\nYou may modify ONLY `strategy.py` and `registry.py`. Do not create or\nedit `cli.py` or `NOTES.md`.\n", "b8.py-feat-03": "The repo is a small publish/subscribe event system, split across 3 files:\n\n- `eventbus.py` -- the EXISTING engine, `EventBus`: `.subscribe(event_type,\n  handler)` appends `handler` to that event type's subscriber list\n  (order preserved, multiple handlers per event type are supported);\n  `.publish(event_type, payload)` calls EVERY subscribed handler for\n  `event_type`, in subscription order, with `payload`, and returns a\n  list of their return values (an unknown `event_type` with no\n  subscribers yields an empty list, never an error).\n- `handlers.py` -- individual handler functions plus `register_all(bus)`,\n  which wires them up. Two handlers already exist and are already wired:\n  `log_handler(payload)` (subscribed to `\"info\"`, returns `f\"LOG:\n  {payload}\"`) and `error_counter(payload)` (subscribed to `\"error\"`,\n  increments a module-level counter and returns `f\"ERROR_COUNT: {n}\"`\n  where `n` is the running count).\n- `app.py` -- the EXISTING caller, `build_app()`: constructs an\n  `EventBus`, calls `register_all(bus)` on it, and returns the bus. Must\n  keep working exactly as written.\n\nAdd a new handler, `alert_handler(payload)`, to `handlers.py`, and\nsubscribe it to the `\"error\"` event type ALONGSIDE the existing\n`error_counter` handler (both must fire when `\"error\"` is published --\ndo not replace or remove `error_counter`'s subscription). Contract:\n`alert_handler` must RETURN (not print) the string\n`f\"ALERT: {message} (severity={severity})\"`, where `message` is\n`payload.get(\"message\", \"\")` and `severity` is\n`payload.get(\"severity\", \"unknown\")` -- it must never raise, even for a\n`payload` missing one or both keys (or an empty dict).\n\nYou may modify ONLY `handlers.py`. Do not create or edit `eventbus.py`,\n`app.py`, or `NOTES.md`.\n", "b8.py-feat-04": "The repo is a small task-list system, split across 3 files:\n\n- `models.py` -- `class Task`, currently `__init__(self, title,\n  done=False)`, storing `self.title`/`self.done`.\n- `storage.py` -- `serialize(task)` (returns `{\"title\": ..., \"done\":\n  ...}`) and `deserialize(d)` (builds a `Task` back from such a dict).\n- `filters.py` -- the EXISTING caller, ALREADY written against a\n  `Task.priority` attribute that doesn't exist yet:\n  ```python\n  def high_priority_titles(tasks):\n      return [t.title for t in tasks if t.priority <= 2]\n\n  def sort_by_priority(tasks):\n      return sorted(tasks, key=lambda t: t.priority)\n  ```\n  Must keep working exactly as written (do not edit it) -- it is the\n  proof that your changes to the two files below actually flow the new\n  field all the way through.\n\nAdd a `priority` field that flows through all three layers:\n\n1. `models.py`: `Task.__init__` gains a `priority=3` keyword parameter\n   (1 = most urgent, 5 = least urgent), stored as `self.priority`. It\n   must validate: `priority` must be an `int` (not e.g. a `str` or\n   `float`) in the inclusive range 1-5; any other value raises\n   `ValueError`.\n2. `storage.py`: `serialize(task)` must include `\"priority\":\n   task.priority` in its returned dict. `deserialize(d)` must pass\n   `d[\"priority\"]` through to `Task(...)` when the key is present, but\n   for BACKWARD COMPATIBILITY with data saved before this field\n   existed, must default to `3` when `\"priority\"` is absent from `d`\n   (do not require callers to have already migrated their saved data).\n\nYou may modify ONLY `models.py` and `storage.py`. Do not create or edit\n`filters.py` or `NOTES.md`.\n", "b8.py-feat-05": "The repo is a small shape system, split across 2 files:\n\n- `shapes.py` -- an abstract base class `Shape` with two abstract\n  methods, `area(self)` and `perimeter(self)`. Two concrete shapes\n  already exist and are correct: `Rectangle(width, height)` and\n  `Circle(radius)`. Both VALIDATE EAGERLY, in `__init__`, raising\n  `ValueError` immediately at construction time if any dimension is not\n  a positive number -- NOT lazily, the first time `area()`/`perimeter()`\n  happens to be called.\n- `shape_report.py` -- the EXISTING caller: `describe(shape)` (returns\n  `f\"{type(shape).__name__}: area={shape.area():.2f},\n  perimeter={shape.perimeter():.2f}\"`) and `total_area(shapes)` (returns\n  `sum(s.area() for s in shapes)`). Must keep working exactly as\n  written.\n\nAdd a new concrete shape, `Triangle(a, b, c)` (three side lengths), to\n`shapes.py`, following the SAME pattern `Rectangle`/`Circle` already\nuse:\n- `area()` via Heron's formula: `s = (a+b+c)/2`,\n  `area = sqrt(s*(s-a)*(s-b)*(s-c))`.\n- `perimeter()` is `a+b+c`.\n- VALIDATE EAGERLY, in `__init__`, exactly like the two existing shapes:\n  raise `ValueError` immediately at construction time -- BEFORE\n  `area()`/`perimeter()` is ever called -- if any side is not a positive\n  number, OR if the three sides don't satisfy the triangle inequality\n  (each side must be strictly less than the sum of the other two; three\n  sides that can't form a real triangle, e.g. `(1, 1, 3)`, are invalid).\n\nYou may modify ONLY `shapes.py`. Do not create or edit `shape_report.py`\nor `NOTES.md`.\n", "b8.py-feat-06": "The repo is a small request router, split across 2 files:\n\n- `router.py` -- the EXISTING engine. `ROUTES` is a dict mapping path ->\n  `(handler_fn, required_role)`. `route(path, required_role=None)` is a\n  decorator: `@route(\"/x\")` registers a handler with no role\n  requirement; `@route(\"/x\", required_role=\"admin\")` registers one that\n  requires the caller's role to match exactly. `handle(path, role,\n  *args)` looks `path` up in `ROUTES` (raising `LookupError` if it isn't\n  registered), and -- ONLY if a `required_role` was registered for that\n  path AND the caller's `role` doesn't match it -- raises\n  `PermissionError` WITHOUT calling the handler at all; otherwise calls\n  `handler_fn(*args)` and returns its result. This enforcement is\n  centralized here; individual handlers are never expected to check\n  roles themselves.\n- `handlers.py` -- the EXISTING handlers, already registered via the\n  `@route` decorator: `status_handler` (`@route(\"/status\")`, no args,\n  returns `\"ok\"`) and `profile_handler` (`@route(\"/profile\")`, takes\n  `username`, returns `f\"profile: {username}\"`).\n\nAdd a new handler, `reset_handler(target)`, to `handlers.py`, registered\nat path `\"/admin/reset\"` and requiring role `\"admin\"` -- use the SAME\n`@route(...)` decorator mechanism the two existing handlers use (do not\ninvent a separate, handler-internal role check; the router's own\n`required_role` enforcement is the single place authorization is meant\nto live). `reset_handler` itself should simply return `f\"reset:\n{target}\"` -- it does not need to know anything about roles.\n\nYou may modify ONLY `handlers.py`. Do not create or edit `router.py` or\n`NOTES.md`.\n", "b8.py-fromscratch-01": "Write a NEW Python file `textutils.py` (the repo has no such file yet)\nthat defines a function `is_palindrome(s)`. Given a string, it must\nreturn `True` if the string reads the same forwards and backwards once\nyou ignore case and drop every character that isn't a letter or digit,\nand `False` otherwise. E.g.:\n\n    >>> is_palindrome(\"A man, a plan, a canal: Panama\")\n    True\n    >>> is_palindrome(\"hello\")\n    False\n    >>> is_palindrome(\"\")\n    True\n\nCreate exactly one new file, `textutils.py`. Do not create or edit any\nother file (including `NOTES.md`).\n", "b8.py-fromscratch-02": "Write a NEW Python file `exprcalc.py` (the repo has no such file yet)\nthat defines a function `evaluate_expression(expr)`. Given a string\ncontaining non-negative integers, `+`, `-`, `*`, parentheses `(`/`)`,\nand optional spaces, it must evaluate the expression and return the\ninteger result, respecting standard operator precedence (`*` binds\ntighter than binary `+`/`-`) and parentheses, with `+`/`-` at the same\nprecedence level evaluated LEFT TO RIGHT (e.g. `10 - 2 - 3` is\n`(10 - 2) - 3 = 5`, not `10 - (2 - 3)`). There is no division and no\nunary minus / negative numbers anywhere in the input -- every number in\n`expr` is a non-negative integer literal. E.g.:\n\n    >>> evaluate_expression(\"2 + 3 * 4\")\n    14\n    >>> evaluate_expression(\"(2 + 3) * 4\")\n    20\n    >>> evaluate_expression(\"10 - 2 - 3\")\n    5\n    >>> evaluate_expression(\"2 * (3 + (4 - 1)) + 5\")\n    17\n\nCreate exactly one new file, `exprcalc.py`. Do not create or edit any\nother file (including `NOTES.md`).\n", "b8.py-hard-algo-01": "Write a NEW Python file `lru_cache.py` (the repo has no such file yet)\nthat defines a class `LRUCache` implementing a fixed-capacity\nLeast-Recently-Used cache with this EXACT contract:\n\n- `LRUCache(capacity)` -- `capacity` is a positive integer (>= 1): the\n  maximum number of key/value pairs the cache may hold at once.\n- `get(key)` -- if `key` is present, return its value AND mark `key` as\n  the MOST recently used entry. If `key` is not present, return `-1`\n  (and do not change anything about the cache's contents or order).\n- `put(key, value)` -- insert or update the value for `key`, and mark\n  `key` as the MOST recently used entry (this applies whether `key` is\n  brand new OR already present -- updating an EXISTING key's value is\n  ALSO a \"use\" of that key, not just `get`). If `key` is new and adding\n  it would push the cache over `capacity`, first evict the LEAST\n  recently used entry (the one that has gone the longest without a\n  `get` or a `put`) to make room. Updating an EXISTING key's value must\n  NEVER trigger an eviction (the number of distinct keys stored does not\n  change).\n\nWorked example (capacity 2):\n\n    cache = LRUCache(2)\n    cache.put(1, 1)\n    cache.put(2, 2)\n    cache.get(1)      # -> 1; key 1 is now the most-recently-used\n    cache.put(3, 3)   # over capacity -> evicts key 2 (the LRU one)\n    cache.get(2)      # -> -1 (evicted)\n    cache.put(4, 4)   # evicts key 1\n    cache.get(1)      # -> -1\n    cache.get(3)      # -> 3\n    cache.get(4)      # -> 4\n\nCreate exactly one new file, `lru_cache.py`. Do not create or edit any\nother file (including `NOTES.md`).\n", "b8.py-hard-bugfix-01": "The repo has one file, `search_utils.py`, containing a function that is\nmeant to satisfy this exact contract:\n\n    first_occurrence(nums, target) -- `nums` is a list of integers sorted\n    in NON-DECREASING order (it may contain duplicate values). Return the\n    index of the FIRST (left-most) occurrence of `target` in `nums`, or\n    -1 if `target` does not appear anywhere in `nums`.\n\nE.g. `first_occurrence([1, 2, 2, 2, 3], 2)` must return `1` (the index of\nthe *first* `2`, not any other one), and `first_occurrence([5, 5, 5], 5)`\nmust return `0`.\n\nThe current implementation is a binary search that looks reasonable, and\nit is valid Python (it runs fine and returns a plausible-looking answer\nfor many inputs) -- but it does NOT correctly satisfy the contract above\nin every case. There is a real, non-obvious logic bug in it. Find the bug\nand fix it so `first_occurrence` satisfies the contract exactly in every\ncase, including whenever `target` appears more than once in `nums`.\n\n```python\ndef first_occurrence(nums, target):\n    \"\"\"Return the index of the first (left-most) occurrence of `target`\n    in `nums`, a list sorted in non-decreasing order. `nums` may contain\n    duplicate values. Return -1 if `target` is not present anywhere in\n    `nums`.\"\"\"\n    lo, hi = 0, len(nums) - 1\n    result = -1\n    while lo <= hi:\n        mid = (lo + hi) // 2\n        if nums[mid] == target:\n            result = mid\n            lo = mid + 1\n        elif nums[mid] < target:\n            lo = mid + 1\n        else:\n            hi = mid - 1\n    return result\n```\n\nOnly modify `search_utils.py` -- do not create or edit any other file\n(including `NOTES.md`).\n", "b8.py-hard-edge-01": "Write a NEW Python file `rankfind.py` (the repo has no such file yet)\nthat defines a function `second_largest_unique(nums)` with this EXACT\ncontract:\n\n- `nums` is a list of integers. It may be empty, may contain negative\n  numbers, may contain zero, and may contain duplicate values.\n- Return the second-largest DISTINCT value that appears in `nums` --\n  i.e. the largest value strictly less than the overall maximum, among\n  the values that actually occur in `nums`.\n- If `nums` has fewer than 2 DISTINCT values (this includes: `nums` is\n  empty, `nums` has exactly one element, or every element in `nums` is\n  equal to every other element), return `None`.\n\nExamples:\n\n    >>> second_largest_unique([7, 7, 7, 5])\n    5\n    >>> second_largest_unique([1, 2, 3, 4, 5])\n    4\n    >>> second_largest_unique([5, 4, 3, 2, 1])\n    4\n    >>> second_largest_unique([5, 5, 5])\n    None\n    >>> second_largest_unique([])\n    None\n    >>> second_largest_unique([-1, -2, -3])\n    -2\n\nNote the first example: the value `7` occurs three times and `5` occurs\nonce, but the answer is about DISTINCT values, not raw list positions --\n`7` is the largest distinct value and `5` is the second-largest distinct\nvalue, regardless of how many times `7` repeats.\n\nCreate exactly one new file, `rankfind.py`. Do not create or edit any\nother file (including `NOTES.md`).\n", "b8.py-hard-multifile-01": "The repo has three files implementing a small checkout system:\n\n- `cart.py` -- defines `Cart`, with `add_item(unit_price, quantity)` and\n  `subtotal()` (sums `unit_price * quantity` across all added items).\n  This file is CORRECT. Do not edit it.\n- `pricing.py` -- defines two pure helper functions, `apply_discount\n  (amount, flat_discount)` (subtracts a flat dollar amount) and\n  `apply_tax(amount, tax_rate)` (multiplies by `1 + tax_rate`, e.g.\n  `tax_rate=0.08` for 8%). Both are CORRECT in isolation. Do not edit\n  this file either.\n- `checkout.py` -- defines `checkout_total(cart, flat_discount,\n  tax_rate)`, which is supposed to orchestrate `cart.py` and\n  `pricing.py` to compute the final amount the customer owes, rounded to\n  2 decimal places.\n\nThe business rule `checkout_total` must implement exactly is this:\n\n    Sales tax is charged on the amount AFTER the flat discount has\n    already been subtracted -- a customer must NEVER pay tax on the\n    portion of the subtotal that was discounted away. In other words:\n    take the cart's subtotal, subtract the flat discount from it FIRST,\n    and only THEN apply the tax rate to what's left.\n\n`checkout_total` currently does not honor this rule -- it computes a\nnumber that is wrong whenever both `flat_discount` and `tax_rate` are\nnonzero (reading `cart.py` or `pricing.py` alone will not reveal this:\nboth of those files are individually correct and do exactly what their\nown docstrings say; the bug is only visible by comparing `checkout.py`'s\nactual order of operations against the business rule stated above).\nFix `checkout_total` in `checkout.py` so it correctly implements the\nrule. Only modify `checkout.py` -- do not create or edit any other file\n(including `cart.py`, `pricing.py`, or `NOTES.md`).\n", "b8.py-hard-toolheavy-01": "The repo is a small grade-reporting system, split across 5 files:\n\n- `roster.py` -- a fixed list of `(name, raw_score)` tuples.\n- `stats.py` -- `average(scores)`, the class average of a list of\n  numbers.\n- `curve.py` -- `apply_curve(score, class_average, target_average=75)`,\n  which shifts a raw score by half the gap between `target_average` and\n  the class's actual `class_average`, then clamps the result to the\n  valid 0-100 range.\n- `letter_grade.py` -- `letter_grade(score)`, which is supposed to\n  convert a (curved) numeric score to a letter grade using the standard\n  scale: `A` for 90-100, `B` for 80-89, `C` for 70-79, `D` for 60-69, `F`\n  below 60.\n- `report.py` -- `build_report(target_average=75)`, which wires all of\n  the above together: computes the class average, curves every\n  student's score, converts each curved score to a letter grade, and\n  formats a report line per student.\n\nThe report is producing wrong letter grades for students whose curved\nscore lands exactly on a scale boundary: for instance, a curved score of\nexactly `90.0` should be graded `A` under the stated scale above, but the\nsystem currently reports `B` for a score of exactly `90.0` (and the same\nkind of off-by-one shows up at the `80`, `70`, and `60` boundaries too).\n\nRead whatever files you need to in order to find the ACTUAL root cause\nof this discrepancy -- not every file that looks unusual or worth a\nsecond look is actually the source of the bug, so verify against the\nstated scale carefully rather than guessing. Once you've found it, fix\nONLY the one file responsible so `letter_grade(score)` correctly matches\nthe stated scale (inclusive on every boundary: a score of exactly `90`\nis `A`, exactly `80` is `B`, exactly `70` is `C`, exactly `60` is `D`).\n\nThis task touches several small files -- if your harness supports\ndelegating a self-contained subtask like \"check each of these 5 files\nagainst the stated contract and report which one doesn't match\" to a\nsubagent, this is a reasonable place to do it.\n\nYou may modify ONLY `letter_grade.py`. Do not create or edit any other\nfile (including `roster.py`, `stats.py`, `curve.py`, `report.py`, or\n`NOTES.md`) -- even if you notice something about one of them you'd\notherwise want to change.\n", "b8.py-multifile-01": "The repo has three files:\n\n- `calc.py` -- defines `add(a, b)`, which works, but is MISSING a\n  `multiply(a, b)` function. Add it (integer multiplication of its two\n  arguments, RETURNED -- not printed).\n- `formatter.py` -- defines `fmt_result(x)`, but it returns the wrong\n  prefix (`\"Answer: \"` instead of `\"Result: \"`). Fix the prefix.\n- `main.py` -- already correct; imports both modules and prints the\n  formatted product of 3 and 4. Do NOT edit `main.py`.\n\nWhen done, `python3 main.py` must print exactly `Result: 12`. You need\nto edit BOTH `calc.py` and `formatter.py` to get there -- neither file\nalone is enough. Do not create any new files.\n", "b8.py-robust-01": "The repo has two files:\n\n- `validators.py` -- `validate_username(raw)`, meant to validate a\n  candidate username and return it unchanged (`str`) if valid, or raise\n  `ValueError` (describing why) otherwise. Contract other code relies\n  on -- ALL of the following must hold for `raw` to be accepted:\n  1. `raw` must be a `str` (anything else -- `None`, `int`, `list`,\n     ... -- is invalid).\n  2. Length 3-20 characters, INCLUSIVE on both ends.\n  3. Every character must be an ASCII letter, ASCII digit, or\n     underscore (`_`) -- nothing else (no spaces, quotes, angle\n     brackets, hyphens, periods, semicolons, ...).\n  4. The FIRST character must not be a digit.\n  5. The username, compared CASE-INSENSITIVELY, must not be one of the\n     reserved names `admin`, `root`, `administrator`, `null`,\n     `undefined`, `system` -- e.g. `\"Admin\"`/`\"ADMIN\"`/`\"aDmIn\"` must\n     ALL be rejected exactly like `\"admin\"` is, since they're the same\n     reserved name, just differently cased. This is an EXACT match\n     against the whole (lowercased) username, not a substring check --\n     `\"Administrator2\"` is fine (it isn't itself `\"administrator\"`,\n     even though that word is a prefix of it).\n  A username that violates ANY of these must raise `ValueError`; one\n  that violates none of them is returned completely unchanged.\n- `signup.py` -- an EXISTING caller elsewhere in this codebase:\n  `register(raw_username, existing_users)` validates then adds to a\n  user set -- relies on `validate_username` rejecting EVERY invalid or\n  reserved name (including a case-varied reserved name like `\"Admin\"`),\n  never letting one slip through into the user table. Must keep\n  working exactly as written.\n\nThe bug: `validators.py`'s reserved-name check is currently\nCASE-SENSITIVE (`raw in _BLOCKLIST`) -- `\"Admin\"`, `\"ADMIN\"`, `\"RoOt\"`,\netc. all bypass it even though they're the same reserved name as\n`\"admin\"`/`\"root\"`, just differently cased. Every other rule (type,\nlength, character class, leading-digit) is already implemented\ncorrectly. Fix the reserved-name check so it's genuinely\ncase-insensitive (matches rule 5 above exactly). Only modify\n`validators.py` -- do not create or edit any other file (including\n`signup.py` or `NOTES.md`).\n", "b8.py-robust-02": "Implement a path-traversal-safe join from scratch, in a new file\n`safe_path.py`, exposing `safe_join(base_dir, user_path) -> str`.\nOperate on POSIX-style forward-slash paths using the `posixpath`\nmodule (NOT `os.path`) so behavior is identical regardless of the host\nOS this runs on.\n\nContract:\n- `user_path` must be a `str`; reject (raise `ValueError`) anything\n  else.\n- Reject a NUL byte (`\"\\x00\"`) anywhere in `user_path`.\n- Reject a backslash (`\\`) anywhere in `user_path` -- this\n  implementation is POSIX-only, but the resulting path may later be\n  handed to a Windows-native API elsewhere, where `\\` IS a separator;\n  reject it defensively here rather than silently passing it through.\n- Reject an ABSOLUTE `user_path` (starts with `/`), and reject a\n  Windows drive-letter path (`user_path[0]` a letter and\n  `user_path[1] == ':'`, e.g. `\"C:/secret.txt\"`).\n- Otherwise, join `user_path` onto `base_dir` and FULLY NORMALIZE the\n  result (resolve every `.`/`..` segment) -- then verify the\n  normalized result is still located INSIDE the normalized `base_dir`\n  (either equal to it, e.g. an empty `user_path`, or nested under it\n  with a real path-separator boundary -- comparing raw string PREFIXES\n  without that boundary is not enough: `/srv/data2/...` is NOT inside\n  `/srv/data` even though the string `\"/srv/data2\"` starts with the\n  string `\"/srv/data\"`). If it escapes, raise `ValueError`; otherwise\n  return the normalized, joined absolute path.\n- A `..` PATH COMPONENT is traversal and must be resolved/rejected\n  appropriately -- but `..` as a mere SUBSTRING of a longer path\n  component is NOT traversal and must be left alone: `\"..hidden_file\"`\n  (a single component, a valid filename that merely starts with two\n  dots) and `\"....//secret.txt\"` (a component of four literal dots,\n  not two `..` components) must both be accepted, resolving to a path\n  nested under `base_dir` with that literal (if unusual-looking)\n  component -- reject based on genuine `..` PATH SEGMENTS after\n  normalization, never by pattern-matching/stripping the substring\n  `\"../\"` out of the raw string (that approach is a well-known\n  insufficient defense: e.g. `\"..././\"` still contains a live `\"../\"`\n  sequence AFTER a single substring-replace pass over it, since\n  removing the FIRST match reassembles the remaining characters into a\n  new one).\n- A `user_path` that legitimately uses `..` internally but still\n  resolves to somewhere INSIDE `base_dir` (e.g. `\"subdir/../report.txt\"`\n  -> the same as `\"report.txt\"`) must be ACCEPTED, not rejected outright\n  just for containing `..` at all.\n\nAn existing file, `file_server.py`, already does\n`read_request(base_dir, requested_path)` (`safe_join(base_dir,\nrequested_path)`, resolving a client-supplied path before any real file\nI/O) -- must keep working exactly as written.\n\nCreate ONLY `safe_path.py`. Do not create or edit `file_server.py` or\n`NOTES.md`.\n", "b8.py-robust-03": "Implement a numerically-stable running (streaming) statistics\naccumulator from scratch, in a new file `stats.py`, exposing a class\n`RunningStats` with:\n- `add(x)` -- incorporates one more numeric sample. `x` must be an\n  `int` or `float` (NOT `bool` -- `bool` is a subclass of `int` in\n  Python but must still be REJECTED here) -- raise `TypeError`\n  otherwise. `x` must also be FINITE (not NaN, not `+inf`/`-inf`) --\n  raise `ValueError` otherwise (an incorporated NaN/Infinity would\n  silently poison every statistic computed afterward).\n- `count` -- the number of samples added so far (an `int`, `0` before\n  any `add`).\n- `mean` -- the arithmetic mean of every sample added so far. Raise\n  `ValueError` if `count == 0` (no data yet).\n- `variance` -- the POPULATION variance (divide by `count`, NOT\n  `count - 1`) of every sample added so far. Raise `ValueError` if\n  `count == 0`; for `count == 1`, variance is `0.0`.\n- `stdev` -- `variance ** 0.5`. Raise `ValueError` if `count == 0`.\n\nThe critical correctness requirement: `variance` (and therefore\n`stdev`) MUST be computed in a NUMERICALLY STABLE way -- e.g. Welford's\nonline algorithm (track a running mean and running sum-of-squared-\ndifferences-from-the-mean, updated incrementally on each `add`) --\nNEVER via the naive textbook formula `E[X^2] - (E[X])^2` (accumulate\n`sum(x)` and `sum(x*x)`, then compute `sum(x*x)/n - mean**2` at the\nend). The naive formula suffers CATASTROPHIC CANCELLATION whenever the\ndata has a large common offset with a small genuine spread (e.g. a\nstream of latency samples that are all huge numbers close together) --\nit can be wildly wrong, or even produce a NEGATIVE variance (which is\nmathematically impossible for any real dataset), because it subtracts\ntwo enormous, nearly-equal floating-point numbers to recover a tiny\nresult.\n\nAn existing file, `monitor.py`, already does\n`summarize_latencies(samples)` (feeds a list of samples through a fresh\n`RunningStats` and formats `mean`/`stdev`/`count`) -- relies on exactly\nthis numerical-stability property, since real latency samples are\nroutinely large-offset, small-spread data. Must keep working exactly as\nwritten.\n\nCreate ONLY `stats.py`. Do not create or edit `monitor.py` or\n`NOTES.md`.\n", "b8.py-robust-04": "The repo has two files:\n\n- `mini_parser.py` -- `parse_nested_list(s)`, meant to parse a small\n  nested-list mini-language (e.g. `\"[1,[2,3],[4,[5,6]]]\"` -> `[1, [2,\n  3], [4, [5, 6]]]`) into real Python `list`/`int` values. Grammar:\n  the top-level input must be a single bracketed list; a list is `[`,\n  then zero or more comma-separated VALUES (a value is either an\n  integer, optionally `-`-signed, or a nested list), then `]`;\n  whitespace is allowed anywhere between tokens and must be ignored.\n  Malformed input of any kind (unbalanced brackets, a missing/extra\n  comma, a trailing comma, trailing data after the top-level value,\n  something other than a list at the top level, an empty string, ...)\n  must raise `ValueError` -- cleanly, never a different exception type,\n  never a hang.\n- `loader.py` -- an EXISTING caller elsewhere in this codebase:\n  `total_leaf_count(s)` parses `s` then recursively counts leaf\n  (non-list) values -- relies on `parse_nested_list` actually\n  SUCCEEDING (not crashing, not hanging) on well-formed input,\n  including deeply-nested well-formed input, and on it raising\n  `ValueError` (nothing else) for malformed input. Must keep working\n  exactly as written.\n\nThe bug: `mini_parser.py`'s `parse_nested_list` is currently a NAIVE\nRECURSIVE-DESCENT parser -- one Python function call per nesting\nlevel. This is correct for shallow input, but DEEPLY nested input\n(thousands of levels of `[`) blows Python's interpreter recursion limit\n(`RecursionError`) long before parsing finishes, instead of parsing\nsuccessfully. Rewrite `parse_nested_list` to use an EXPLICIT, HEAP-\nALLOCATED stack (e.g. a Python list you push/pop) instead of the\ninterpreter's call stack, so nesting depth is bounded only by memory,\nnot by `sys.getrecursionlimit()` -- every other rule above (malformed-\ninput rejection, whitespace tolerance, etc.) is already correct and\nmust keep working. A large FLAT list (tens of thousands of comma-\nseparated integers, no real nesting) must also keep parsing in\nreasonable time -- avoid any accidental O(n^2) pattern (e.g. repeated\nstring concatenation or destructive re-slicing of the whole remaining\ninput on every token). Only modify `mini_parser.py` -- do not create or\nedit any other file (including `loader.py` or `NOTES.md`).\n", "b8.py-robust-05": "Implement a de-duplicating record merger from scratch, in a new file\n`dedup.py`, exposing `dedup_merge(records, key) -> list`.\n\nContract:\n- `records` is a list of `dict`s; `key` is the field name used to\n  decide identity. Every record MUST contain `key` -- raise\n  `ValueError` (never a different exception) for any record that\n  doesn't.\n- Output: exactly ONE merged `dict` per DISTINCT value of\n  `record[key]`, in the order each distinct value FIRST appears in\n  `records` (first-seen order -- NOT sorted, NOT the order a key was\n  last touched).\n- Merge rule for records sharing the same key value: process them in\n  their ORIGINAL list order; each subsequent record's fields OVERWRITE\n  the accumulated record's fields for every field name PRESENT in that\n  later record (equivalent to calling `.update()` with each record in\n  turn onto one shared dict per key) -- so the final merged record for\n  a key reflects the LATEST value for every field ANY record sharing\n  that key ever set, and RETAINS a field from an earlier record if a\n  later record sharing the same key never mentions that field at all.\n- Must handle a LARGE input (thousands of records) without hanging or\n  crashing -- correctness and not-hanging are what's graded here, NOT\n  micro-optimization (an O(n^2) approach that finishes in reasonable\n  time is fine).\n\nAn existing file, `pipeline.py`, already does\n`latest_snapshot(events)` (`dedup_merge(events, \"id\")`, collapsing a\nstream of partial-update events sharing an `\"id\"` field into one\ncurrent-state record per id) -- must keep working exactly as written.\n\nCreate ONLY `dedup.py`. Do not create or edit `pipeline.py` or\n`NOTES.md`.\n", "b8.py-robust-06": "Implement a token-bucket rate limiter from scratch, in a new file\n`rate_limiter.py`, exposing a class `TokenBucket(capacity, refill_rate,\nclock=None)`:\n- `capacity` -- the maximum number of tokens the bucket can ever hold\n  (a positive number). `refill_rate` -- tokens added per second (a\n  positive number). Both must be validated in the constructor: raise\n  `ValueError` if either is `<= 0`.\n- `clock` -- a ZERO-ARG callable returning the current time in seconds\n  (`float`), INJECTABLE for fully deterministic testing (defaults to\n  `time.monotonic` when not provided, but every test here supplies its\n  own fake, controllable clock -- never a real `time.sleep()`).\n- The bucket starts FULL (`capacity` tokens available) the moment it's\n  constructed.\n- `try_consume(n=1) -> bool`: first, REFILL based on elapsed time since\n  the last refill (`elapsed_seconds * refill_rate` tokens added,\n  capped so the bucket NEVER holds more than `capacity` tokens no\n  matter how long it's been idle) -- this refill step must happen\n  BEFORE checking whether the request can be satisfied, every single\n  call (a request that's only satisfiable because enough time has\n  ALREADY passed since the last call must be correctly admitted, not\n  wrongly denied against a stale token count). Then: if `n <= 0`, raise\n  `ValueError`. If at least `n` tokens are now available, subtract `n`\n  and return `True`. Otherwise, return `False` WITHOUT consuming\n  anything (no partial consumption). A request for MORE tokens than\n  `capacity` can NEVER succeed, ever, even from a completely full\n  bucket (there's no way to ever have that many tokens available at\n  once).\n\nAn existing file, `gateway.py`, already does\n`make_limiter(requests_per_second, burst, clock)`\n(`TokenBucket(burst, requests_per_second, clock)`) -- must keep working\nexactly as written.\n\nCreate ONLY `rate_limiter.py`. Do not create or edit `gateway.py` or\n`NOTES.md`.\n", "b8.py-state-01": "Implement a fixed-capacity WRITE-BACK cache from scratch, in a new file\n`cache.py`, exposing a class `WriteBackCache(capacity)`.\n\nSemantics (this is a FIFO write-back cache, distinct from an LRU cache\n-- pay close attention to what actually reorders eviction priority and\nwhat doesn't):\n\n- `capacity` must be a positive int; `WriteBackCache(0)` or a negative\n  capacity must raise `ValueError` at construction.\n- `put(key, value)`: stores `value` in memory under `key` and marks that\n  entry DIRTY. If `key` is already present, this UPDATES its value and\n  marks it dirty again, but must NOT change its position in the\n  eviction queue (see below) -- only the entry's ORIGINAL insertion\n  determines eviction order, never a later update.\n- Eviction queue is strict FIFO BY INSERTION (not by access, and not by\n  update): the OLDEST-INSERTED key still in the cache is the first\n  candidate for eviction. Whenever a `put()` would make the number of\n  in-memory entries exceed `capacity`, the oldest-inserted entry is\n  evicted immediately: if it is currently dirty, its value is written\n  to `self.backend` (a plain `dict` you expose as an attribute,\n  simulating durable storage) BEFORE it is dropped -- a dirty write must\n  never be silently lost. If it is not dirty (already flushed), it is\n  simply dropped.\n- `get(key)`: returns the entry's current in-memory value; raises\n  `KeyError` if `key` is not currently in the cache (this cache does\n  NOT read through to `self.backend` on a miss). Accessing a key via\n  `get` never changes its eviction position (again: insertion order\n  only).\n- `is_dirty(key)`: returns `True`/`False` for whether `key`'s in-memory\n  value has been written to `self.backend` yet; raises `KeyError` if\n  `key` is not currently in the cache.\n- `flush()`: writes every CURRENTLY-dirty entry's value to\n  `self.backend` and clears their dirty flags. Entries stay in the\n  cache (nothing is evicted); non-dirty entries are left untouched.\n\nAn existing file, `session_store.py`, already does\n`from cache import WriteBackCache` and calls\n`WriteBackCache(capacity=64)` -- your class's constructor must accept\n`capacity` as a keyword argument with that exact name.\n\nCreate ONLY `cache.py`. Do not create or edit `session_store.py` or\n`NOTES.md`.\n", "b8.py-state-02": "Implement an order lifecycle state machine from scratch, in a new file\n`orders.py`, exposing:\n\n- `class InvalidTransition(Exception)` -- raised for any illegal state\n  transition attempt.\n- `class Order(order_id)` -- `.order_id` is stored as given; `.state`\n  starts as the string `\"pending\"`; `.history` starts as the list\n  `[\"pending\"]` (every state the order has ever ENTERED, in order,\n  including `\"pending\"` itself as the starting state).\n\nLegal transitions ONLY: `pending -> paid` (via `.pay()`), `paid ->\nshipped` (via `.ship()`), `shipped -> delivered` (via `.deliver()`),\n`pending -> cancelled` (via `.cancel()`), `paid -> cancelled` (via\n`.cancel()`). Every other transition is illegal, including: skipping a\nstep (e.g. `pending -> shipped`), going backwards, re-entering the\ncurrent state (e.g. calling `.pay()` twice), or transitioning out of a\nTERMINAL state (`cancelled` or `delivered` -- once an order reaches\neither one, no method may ever change its state again, including\n`.cancel()` on an already-cancelled order).\n\nEach of `.pay()`/`.ship()`/`.deliver()`/`.cancel()` either performs its\ntransition (updating `.state` and appending the NEW state to\n`.history`) or, if the transition is illegal from the order's CURRENT\nstate, raises `InvalidTransition` -- and on an illegal attempt, `.state`\nand `.history` must be left COMPLETELY UNCHANGED (a failed transition\nattempt must never mutate state).\n\nYou may modify ONLY `orders.py` (a new file -- it does not exist yet).\nDo not create or edit `order_log.py` or `NOTES.md`.\n", "b8.py-state-03": "Implement a streaming batch aggregator from scratch, in a new file\n`aggregator.py`, exposing a class `BatchAggregator()`.\n\n- `add(value)`: records `value` (a number) into the CURRENT batch.\n- `end_batch()`: closes the current batch and returns a dict\n  `{\"count\": ..., \"sum\": ..., \"min\": ..., \"max\": ..., \"avg\": ...}`\n  describing ONLY the values added since the previous `end_batch()`\n  call (or since construction, for the first batch). After returning,\n  the PER-BATCH accumulators (count/sum/min/max for the batch just\n  closed) are reset to empty -- the NEXT batch starts from scratch, with\n  no leftover values, especially no leftover `min`/`max` from the\n  previous batch. If `end_batch()` is called with NO values added since\n  the last boundary (an empty batch), it must raise `ValueError`\n  instead of returning a dict (there's nothing to summarize, and no\n  division-by-zero `avg` should ever be computed or returned).\n- `grand_count()` / `grand_sum()` / `grand_min()` / `grand_max()`: each\n  returns the corresponding aggregate across EVERY value ever `add()`ed\n  across ALL batches ever closed (and the batch currently in progress) --\n  these must NEVER be reset by `end_batch()`, unlike the per-batch\n  accumulators. On a fresh instance with no `add()` calls yet,\n  `grand_count()` is `0` and `grand_sum()` is `0` (must not raise);\n  `grand_min()`/`grand_max()` on a fresh instance with no data raise\n  `ValueError` (there is no minimum/maximum of an empty set).\n\nAn existing file, `report.py`, already calls `end_batch()` and the\ngrand-total methods together -- must keep working exactly as written.\n\nCreate ONLY `aggregator.py`. Do not create or edit `report.py` or\n`NOTES.md`.\n", "b8.py-state-04": "Implement a fixed-size connection pool from scratch, in a new file\n`pool.py`, exposing:\n\n- `class PoolExhausted(Exception)` -- raised when `acquire()` is called\n  on a pool with no available connections.\n- `class Connection` -- has an `.id` attribute (any unique value per\n  connection is fine, e.g. an int index).\n- `class ConnectionPool(size)` -- pre-creates `size` `Connection`\n  objects at construction. `size` must be a positive int; `size <= 0`\n  raises `ValueError` at construction.\n  - `acquire()`: removes and returns one available `Connection`; raises\n    `PoolExhausted` (leaving the pool's internal counts UNCHANGED) if\n    none are available.\n  - `release(conn)`: returns a previously-acquired `Connection` to the\n    available pool. Raises `ValueError` (leaving counts UNCHANGED) for\n    EITHER of two misuse cases: `conn` was never returned by this\n    pool's `acquire()` at all (a foreign object), OR `conn` IS one of\n    this pool's connections but is not CURRENTLY checked out (a\n    double-release) -- releasing the same connection twice must never\n    be allowed to silently succeed (that would let two callers hold the\n    \"same\" connection at once).\n  - `available_count()` / `checked_out_count()`: current counts:\n    `available_count() + checked_out_count() == size` must hold at\n    every point.\n  - `connection()`: returns a context manager -- `with pool.connection()\n    as conn:` must `acquire()` on entry and `release()` on exit, EVEN IF\n    the code inside the `with` block raises an exception (the\n    connection must never leak).\n\nAn existing file, `db.py`, already uses `pool.connection()` as a context\nmanager and reads `.id` off the acquired connection -- must keep\nworking exactly as written.\n\nCreate ONLY `pool.py`. Do not create or edit `db.py` or `NOTES.md`.\n", "b8.py-state-05": "Implement a key-value store with NESTED transactions from scratch, in a\nnew file `txstore.py`, exposing:\n\n- `class NoActiveTransaction(Exception)` -- raised by `commit()`/\n  `rollback()` when there is no open transaction to act on.\n- `class TransactionalStore()`:\n  - `set(key, value)`: writes `key`/`value` into the CURRENT scope (the\n    innermost open transaction, if any is open, otherwise directly into\n    the base store).\n  - `get(key)`: returns the value MOST-RECENTLY visible for `key` --\n    considering every open transaction layer from innermost to\n    outermost, then the base store. Raises `KeyError` if `key` isn't\n    visible anywhere (never set, or deleted and not since re-set, in\n    every layer that matters).\n  - `delete(key)`: removes `key` from view within the CURRENT scope\n    (innermost open transaction, or the base store if none is open).\n    Raises `KeyError` if `key` isn't currently visible (per `get`'s own\n    visibility rule) at the point `delete` is called.\n  - `begin()`: opens a new, nested transaction layer on top of whatever\n    is currently open (or on top of the base store, for the first\n    transaction). Any number of transactions may be nested.\n  - `commit()`: raises `NoActiveTransaction` if no transaction is open.\n    Otherwise merges the innermost open transaction's changes (both\n    `set`s and `delete`s) DOWN into the layer beneath it (the next\n    transaction out, or the base store if this was the outermost) --\n    after `commit()`, that next layer down reflects exactly what `get`\n    would have returned while the committed transaction was still open.\n  - `rollback()`: raises `NoActiveTransaction` if no transaction is\n    open. Otherwise DISCARDS the innermost open transaction's layer\n    entirely -- every `set`/`delete` made since the matching `begin()`\n    is undone, as if it never happened; the layer beneath it (or the\n    base store) is completely unaffected.\n\nA `delete()` inside a transaction must be able to hide a value that\nonly exists in an OUTER (still-open) transaction or the base store --\nand a subsequent `commit()` of that transaction must propagate the\ndeletion outward too.\n\nAn existing file, `cli_txn.py`, already calls `.get()` and relies on it\nraising `KeyError` (not returning `None`) for a missing key -- must keep\nworking exactly as written.\n\nCreate ONLY `txstore.py`. Do not create or edit `cli_txn.py` or\n`NOTES.md`.\n", "b8.py-state-06": "Implement a paginated iterator from scratch, in a new file\n`paginator.py`, exposing a class `PageIterator(fetch_page, page_size=3)`\nthat implements the iterator protocol (`__iter__`/`__next__`).\n\n`fetch_page(page_index)` is a callable (0-indexed) returning a `list`\nof up to `page_size` items for that page. Contract:\n\n- `PageIterator` yields every item from every page, IN ORDER, one item\n  per `next()`/loop iteration.\n- A page is the LAST page if it returns FEWER than `page_size` items\n  (this includes an EMPTY list, `[]`). After yielding that page's\n  items (if any), further `next()` calls raise `StopIteration` -- and\n  the NEXT page must never be fetched (there's no reason to, the\n  short page already proved it was the last one).\n- A page returning EXACTLY `page_size` items is NOT automatically the\n  last page -- the FOLLOWING page must still be fetched to find out\n  (it might turn out to be empty, which is itself how the end is\n  discovered).\n- Each page index is fetched from `fetch_page` AT MOST ONCE ever,\n  no matter how it's used -- cache every page's result the first time\n  it's fetched.\n- `.reset()`: restarts iteration from the very first item. It must NOT\n  call `fetch_page` again for any page already in the cache -- a\n  `for` loop (or manual `next()` calls) run again after `.reset()`\n  must reproduce the exact same full sequence of items using ONLY\n  already-cached pages, making zero additional `fetch_page` calls, as\n  long as no page beyond what was already fetched is needed again.\n- Once exhausted (`StopIteration` raised), calling `next()` again must\n  keep raising `StopIteration` (never crash with a different exception,\n  never silently start over, never attempt to fetch a page that was\n  already established not to exist).\n\nAn existing file, `browse.py`, already does `list(PageIterator(fetch_page,\npage_size))` (relying on the standard iterator protocol via `list()`) --\nmust keep working exactly as written.\n\nCreate ONLY `paginator.py`. Do not create or edit `browse.py` or\n`NOTES.md`.\n", "b8.py-toolheavy-01": "The repo has 5 Python modules -- `handler_alpha.py`, `handler_bravo.py`,\n`handler_charlie.py`, `handler_delta.py`, `handler_echo.py` -- each\ndefining a function `transform(x)` that is SUPPOSED to implement the\nsame contract:\n\n    transform(x) == x * 2 + 1\n\nExactly ONE of the 5 files violates this contract. Read/inspect all 5\nfiles (or test them, e.g. via `bash_exec`) to find which one is wrong,\nthen fix ONLY that one file so it correctly implements\n`transform(x) == x * 2 + 1`.\n\nThis task touches many small files -- if your harness supports\ndelegating a self-contained subtask like \"check all 5 handler_*.py\nfiles against the contract and report which one is wrong\" to a\nsubagent, this is a reasonable place to do it.\n\nDo not edit any of the other 4 handler files, and do not create or edit\nany other file (including `NOTES.md`).\n", "b8.py-xmod-01": "The repo has three files implementing a tiny record serialization\nformat, split across a producer/consumer boundary:\n\n- `encoder.py` -- `encode_record(fields)`, which turns a dict of\n  `str -> str` into a single-line record string.\n- `decoder.py` -- `decode_record(s)`, which parses a record string back\n  into a dict. This file defines the ACTUAL escaping contract\n  `encode_record` must satisfy: fields are separated by UNESCAPED `;`,\n  each field's key/value are separated by the first UNESCAPED `=` in\n  that field, and a literal backslash, `;`, or `=` that belongs to a key\n  or value must have been escaped by the encoder as `\\\\`, `\\;`, `\\=`\n  respectively. Read `decoder.py`'s own code/docstring carefully -- it is\n  the authoritative spec for exactly how escaping must work.\n- `store.py` -- `roundtrip(fields)`, an EXISTING caller elsewhere in this\n  codebase that encodes then decodes a record and returns the result.\n  Any correct `encode_record` must satisfy `roundtrip(x) == x` for every\n  possible `fields` dict this caller is exercised with, including values\n  or keys that themselves contain `;`, `=`, or a literal backslash.\n\n`encoder.py`'s `encode_record` does not escape anything at all right\nnow, so `store.roundtrip` silently loses/corrupts data whenever a field's\nkey or value contains one of the delimiter characters. Fix\n`encode_record` so it satisfies the escaping contract `decoder.py`\n(unchanged, correct) expects. Only modify `encoder.py` -- do not create\nor edit any other file (including `decoder.py`, `store.py`, or\n`NOTES.md`).\n", "b8.py-xmod-02": "The repo has three files implementing a small metrics pipeline, split\nacross a producer/consumer boundary:\n\n- `events.py` -- `make_event(name, value, tags=None)`, the PRODUCER: it\n  must create an event dict satisfying the contract\n  `{\"name\": str, \"value\": float, \"tags\": dict}` -- `tags` must default to\n  a fresh empty dict when not supplied.\n- `aggregator.py` -- `total_by_name(events)`, the CONSUMER: sums each\n  event's `\"value\"` field, grouped by `\"name\"`. This file defines what\n  key names/shapes it actually expects from an event -- it is CORRECT\n  and is the authoritative contract producer events must satisfy.\n- `pipeline.py` -- `run_pipeline(records)`, an EXISTING caller elsewhere\n  in this codebase that wires `events.make_event` to `aggregator.\n  total_by_name` for a list of `(name, value, tags)` records. Must keep\n  working after any fix.\n\n`events.make_event` does not actually satisfy the contract `aggregator.py`\nexpects -- reading `aggregator.py` (unchanged, correct) will tell you\nexactly which key names/shapes it needs. Fix `events.make_event` so it\nmatches. Only modify `events.py` -- do not create or edit any other file\n(including `aggregator.py`, `pipeline.py`, or `NOTES.md`).\n", "b8.py-xmod-03": "The repo has two files:\n\n- `discount.py` -- `apply_member_discount(price, member_level)`, which\n  applies a member-tier discount to `price`: bronze 0%, silver 10%, gold\n  20% (any other/unknown level: 0%). Returns the discounted price\n  rounded to 2 decimals.\n- `legacy_caller.py` -- `legacy_receipt_lines()`, an EXISTING function\n  elsewhere in this codebase that calls `apply_member_discount` with\n  exactly its CURRENT two positional arguments, for a fixed set of\n  `(price, level)` pairs, and formats a receipt line per pair. This is\n  existing, already-deployed code you must not edit -- it must keep\n  producing EXACTLY the same output after your change, byte-for-byte.\n\nAdd bulk-purchase support: extend `apply_member_discount` to accept an\noptional third parameter `bulk_qty` (default `1`). When `bulk_qty >= 10`,\napply an ADDITIONAL 5% discount on top of (i.e. multiplicatively after)\nthe member-tier discount; below 10, no additional discount applies (the\nresult must be identical to today). This must be a FULLY\nbackward-compatible change: every existing call site in this codebase\n(see `legacy_caller.py`) calls the function with exactly the original two\npositional arguments and depends on getting EXACTLY the same price back\nas before your change -- omitting the new parameter (or passing\n`bulk_qty=1`) must reproduce today's behavior exactly. Only modify\n`discount.py` -- do not create or edit any other file (including\n`legacy_caller.py` or `NOTES.md`).\n", "b8.py-xmod-04": "The repo has three files:\n\n- `normalize.py` -- `normalize_profile(record)`, meant to normalize a\n  user-profile record to the canonical shape `{\"name\": ..., \"email\":\n  ...}`. It must accept EITHER the CURRENT schema (`{\"name\", \"email\"}`)\n  OR the LEGACY schema (`{\"full_name\", \"email_addr\"}`) still emitted by\n  some older data sources still flowing through this pipeline -- when a\n  key is present under EITHER name (even if its value is an empty\n  string), that value must be used; when a field is missing under BOTH\n  names, its canonical value is `None`. If BOTH the new-schema key and\n  the old-schema key are present on the same record, the NEW-schema key\n  takes precedence. The returned dict must contain EXACTLY these two\n  keys -- any other keys present on the input record (of either schema)\n  must NOT appear in the result.\n- `legacy_importer.py` -- an EXISTING caller elsewhere in this codebase\n  still feeding OLD-schema records through `normalize.normalize_profile`.\n  Must keep working.\n- `current_importer.py` -- another EXISTING caller feeding NEW-schema\n  records through `normalize.normalize_profile`. Must also keep working.\n\n`normalize_profile` currently only understands the new schema, so every\nold-schema record silently comes out with missing `name`/`email` fields.\nFix it so it satisfies the full contract described above (both schemas,\nextra-key stripping, and new-over-old precedence). Only modify\n`normalize.py` -- do not create or edit any other file (including\n`legacy_importer.py`, `current_importer.py`, or `NOTES.md`).\n", "b8.py-xmod-05": "The repo has two files:\n\n- `backends.py` -- two key-value backend classes, `DictBackend` and\n  `ListBackend`, that are both supposed to satisfy the EXACT SAME\n  contract: `put(key, value)` stores/overwrites a value, `get(key)`\n  returns the CURRENT value for `key` (or `None` if it was never\n  stored), and `all_items()` returns a fresh dict snapshot reflecting\n  only the CURRENT (most recently `put`) value of every key ever stored\n  -- a later `put()` for an already-stored key must overwrite, never\n  duplicate, its value.\n- `repository.py` -- `class Repository`, an EXISTING generic driver that\n  wraps ANY object satisfying the above contract (`save`/`load`/\n  `snapshot`, delegating straight to the backend's `put`/`get`/\n  `all_items`). It is used with BOTH `DictBackend` and `ListBackend`\n  polymorphically and must keep working correctly for BOTH.\n\n`DictBackend` correctly satisfies the contract. `ListBackend` does not:\nit stores entries internally as a list of `(key, value)` pairs, but\n`put`/`get`/`all_items` don't correctly handle a key being stored more\nthan once. Find and fix ONLY `ListBackend`'s bug(s) inside `backends.py`\nso it satisfies the exact same contract `DictBackend` already does --\n`DictBackend` itself must remain exactly as correct as it is today.\n`backends.py` is the only file you may edit (both classes live in it),\nbut `DictBackend`'s own behavior must not change. Do not create or edit\nany other file (including `repository.py` or `NOTES.md`).\n", "b8.py-xmod-06": "The repo has two files:\n\n- `config_parser.py` -- `parse_int_setting(raw)`, meant to parse `raw` as\n  an int. Contract other code relies on: on ANY invalid input -- `raw` is\n  `None`, `raw` is not a string at all, or `raw` is a string that isn't a\n  valid (optionally `+`/`-` signed, optional surrounding whitespace)\n  integer -- this function must raise `ValueError`, and ONLY\n  `ValueError`, never any other exception type. Valid integer strings\n  (with any surrounding whitespace, and an optional leading `+`/`-`\n  sign) must still parse correctly, unchanged.\n- `settings_loader.py` -- `load_setting(raw, default=0)`, an EXISTING\n  caller elsewhere in this codebase: parses `raw` via\n  `parse_int_setting`, falling back to `default` (and never raising) on\n  ANY invalid input. This relies ENTIRELY on `parse_int_setting` raising\n  `ValueError` -- and only `ValueError` -- for every invalid case; any\n  other exception type propagates straight through `load_setting`\n  uncaught. Must keep working.\n\nMalformed numeric TEXT (e.g. `\"abc\"`, `\"3.5\"`) already correctly raises\n`ValueError` today. The bug: when `raw` is `None` or not a string at all\n(e.g. an int, a list), `parse_int_setting` crashes with a DIFFERENT\nexception type instead of `ValueError`, which `settings_loader.\nload_setting`'s `except ValueError` does not catch -- the exception\npropagates uncaught instead of falling back to `default`. Fix\n`parse_int_setting` so it raises `ValueError` (and only `ValueError`)\nfor every kind of invalid input, while valid integer strings keep\nparsing exactly as they do today. Only modify `config_parser.py` -- do\nnot create or edit any other file (including `settings_loader.py` or\n`NOTES.md`).\n", "b8.scratch-01": "Write a NEW bash script `is_prime.sh` (the repo has no such file yet)\nthat defines a shell function `is_prime`. Given one non-negative integer\nargument, it must `echo` the literal text `true` if the number is prime\nand `false` otherwise (0 and 1 are NOT prime). E.g. after\n`source is_prime.sh`:\n\n    $ is_prime 2\n    true\n    $ is_prime 4\n    false\n\nCreate exactly one new file, `is_prime.sh`. Do not create or edit any\nother file (including `README.md`).\n", "b8.toolheavy-01": "The directory `data/` contains several `.txt` files, each holding\nwhitespace-separated non-negative integers (possibly across multiple\nlines). Write a NEW bash script `sum_all.sh` that discovers every `.txt`\nfile under `data/` and `echo`s the single grand total of every integer\nfound across ALL of them.\n\nIMPORTANT: do not hardcode the filenames you currently see, or the\ntotal itself -- there may be more (or fewer) files under `data/` when\nthis is graded than there are right now, so `sum_all.sh` must discover\nthe file set dynamically (e.g. a glob like `data/*.txt` or `find`).\n\nThis task touches many small files -- if your harness supports\ndelegating a self-contained subtask like \"read every file under data/\nand report the totals\" to a subagent, this is a reasonable place to do\nit.\n\nCreate exactly one new file, `sum_all.sh`. Do not modify anything under\n`data/`.\n"}, "games": [{"file": "snake_27b.html", "game": "Snake", "model": "27b", "kb": 11.7}, {"file": "snake_bonsai-1bit.html", "game": "Snake", "model": "bonsai-1bit", "kb": 22.0}, {"file": "snake_bonsai-ternary.html", "game": "Snake", "model": "bonsai-ternary", "kb": 13.9}, {"file": "snake_gemma.html", "game": "Snake", "model": "gemma", "kb": 9.2}, {"file": "snake_granite.html", "game": "Snake", "model": "granite", "kb": 2.2}, {"file": "snake_mtp.html", "game": "Snake", "model": "mtp", "kb": 15.4}, {"file": "snake_nemotron.html", "game": "Snake", "model": "nemotron", "kb": 3.3}, {"file": "snake_ornith.html", "game": "Snake", "model": "ornith", "kb": 11.4}, {"file": "snake_qwythos_direct.html", "game": "Snake", "model": "qwythos_direct", "kb": 13.9}, {"file": "snake_qwythos_fixed.html", "game": "Snake", "model": "qwythos_fixed", "kb": 14.3}, {"file": "tetris.html", "game": "Tetris", "model": "?", "kb": 4.1}, {"file": "tetris_27b.html", "game": "Tetris", "model": "27b", "kb": 15.9}, {"file": "tetris_bonsai-1bit.html", "game": "Tetris", "model": "bonsai-1bit", "kb": 13.5}, {"file": "tetris_bonsai-ternary.html", "game": "Tetris", "model": "bonsai-ternary", "kb": 14.4}, {"file": "tetris_gemma.html", "game": "Tetris", "model": "gemma", "kb": 10.5}, {"file": "tetris_granite.html", "game": "Tetris", "model": "granite", "kb": 4.4}, {"file": "tetris_mtp.html", "game": "Tetris", "model": "mtp", "kb": 14.5}, {"file": "tetris_nemotron.html", "game": "Tetris", "model": "nemotron", "kb": 5.9}, {"file": "tetris_ornith.html", "game": "Tetris", "model": "ornith", "kb": 16.5}], "batteries": {"9": "Game Builds", "10": "Security Review", "11": "Tool Loop", "1": "Business Scorecard", "2": "Tool Calling", "3": "Hallucination", "4": "Long Context", "5": "Serving", "6": "Agentic Coding", "7": "Reproducibility", "8": "Agentic Harness"}, "ambiguous_attribution": []};
